export const PART: Chapter[] = [{"n":7,"title":"没钱的时候怎么活","intro":"本节口径是金钱与保障：能领多少钱、免多少钱、得到什么服务、条件是什么，不换算成寿命。政策逐年变、各地不同，所有金额和门槛以当地当年公布为准；排序按「不花钱、手续少、见效快」优先，需要长期资格或地区差异大的靠后，经验条目放最后。","entries":[{"id":"7.1","sec":7,"n":1,"title":"失业了先在线申领失业保险金","cost":"0 元；用「掌上 12333」App、电子社保卡小程序（微信/支付宝）或国家社会保险公共服务平台提交申请，凭社保卡或身份证即可，多数地区不用跑现场；前提是已办失业登记","human":"单位和你自己交满 1 年、又不是主动辞职的，办完失业登记就能领：交满 1 年不到 5 年最长领 12 个月，5 到 10 年最长 18 个月，10 年以上最长 24 个月。金额各省自己定，比当地最低工资低、比低保高。领的这段时间，职工医保由失业保险替你交。主动辞职不算。","gain":"条件是单位和本人缴失业保险累计满 1 年、非因本人意愿中断就业、已办失业登记并有求职要求；累计缴费满 1 年不足 5 年最长领 12 个月，满 5 年不足 10 年最长 18 个月，10 年以上最长 24 个月；金额由省级政府定，低于当地最低工资、高于城市低保，国家目标是逐步提到最低工资标准的 90%；失业人员在领取失业保险金期间参加职工基本医疗保险、享受基本医疗保险待遇，应当缴纳的基本医疗保险费从失业保险基金中支付，个人不缴纳（全国，条例 1999 年起施行）","grade":"A","src":"国务院 (1999). 失业保险条例（国务院令第 258 号，第十四、十七、十八条）. <https://xzfg.moj.gov.cn/front/law/detail?LawID=517>；人力资源社会保障部. 全国人社政务服务平台·失业保险待遇申领办事指南. <https://www.12333.gov.cn/portal/common/bszn/sydysl?pfaId=202105281700000004>；国家发展改革委就业司 (2022). 失业保险金标准，将逐步提高至最低工资的 90%. <https://www.ndrc.gov.cn/fggz/jyysr/jysrsbxf/202206/t20220627_1328819.html>；全国人大常委会 (2010). 社会保险法（第四十八条）. <https://fgk.chinatax.gov.cn/zcfgk/c100009/c5192937/content.html>（国家税务总局政策法规库）","note":"主动辞职不算「非因本人意愿」；领取期间由失业保险代缴职工医保。各省金额差异大，以参保地公布为准。「最低工资 90%」出自人社部 2017 年指导意见，人社部与政府网原文页均未能打开，文号待核实。","money":"0","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":true,"ratio":"极高"},{"id":"7.2","sec":7,"n":2,"title":"被欠薪先投诉劳动监察，再申请劳动仲裁，两条路都不收费，多数案子几个月内有结果","cost":"0 元，投诉、仲裁都不收费；备齐劳动合同、工资条、考勤、转账和聊天记录，跑人社局或仲裁委 1 到 3 趟；仲裁时效 1 年，在职期间被拖欠不受 1 年限制，离职后 1 年内必须提出","human":"两条路都不收钱。先打 12333 或去人社局劳动监察投诉，立案后 60 个工作日内查完，能责令限期支付，逾期还要加付 50% 到 100% 的赔偿金——2024 年全国靠这条给 65.4 万人追回 86.5 亿元。再不行申请劳动仲裁，45 天内结案，金额不超过当地月最低工资 12 倍的一裁终局，公司不能再起诉。但要分清「结案」和「到账」：公司没财产、老板跑路，赢了也可能执行不到。时效是 1 年，离职后一年内必须提。","gain":"第一步拨 12333 或去当地人社局劳动监察投诉，法定立案后 60 个工作日内查完（复杂案件可延 30 个工作日），可责令限期支付、逾期按应付金额 50% 到 100% 加付赔偿金，2024 年全国监察机构查处 13.7 万件、为 65.4 万人追回工资 86.5 亿元；有欠条或工资表、欠薪事实清楚的，可直接向基层法院申请支付令，受理后 15 日内发出；第二步申请仲裁，法定受理后 45 日内结案（可延 15 日），追索劳动报酬可申请先予执行，金额不超过当地月最低工资 12 倍的一裁终局、公司不能起诉，2024 年全国办理 425.7 万件、办结 415.6 万件、结案金额 934.7 亿元，调解成功率 79.6%、仲裁结案率 98.2%、仲裁终结率 73.7%；「半年一年」来自仲裁后进法院的那部分案子：一审 6 个月（简易程序 3 个月）加二审 3 个月，2024 年法院审结追索劳动报酬案 8.8 万件、追回 285.4 亿元，998 人因拒不支付劳动报酬罪获刑（全国）","grade":"A","src":"人力资源社会保障部 (2025). 2024 年度人力资源和社会保障事业发展统计公报. <https://www.mohrss.gov.cn/SYrlzyhshbzb/zwgk/szrs/tjgb/202506/W020250616518526345602.pdf>；最高人民法院 (2025). 最高人民法院工作报告. <https://www.gov.cn/yaowen/liebiao/202503/content_7013680.htm>；国务院 (2004). 劳动保障监察条例（国务院令第 423 号，第九、十七、二十六条）. <https://www.gov.cn/gongbao/content/2004/content_63042.htm>；全国人大常委会 (2007). 劳动争议调解仲裁法（主席令第八十号，第二十七、四十三、四十四、四十七、五十、五十三条）. <https://chinajob.mohrss.gov.cn/h5/c/2022-07-15/356212.shtml>；全国人大常委会 (2012 修正). 劳动合同法（第三十、八十五条）. <https://fgk.chinatax.gov.cn/zcfgk/c100009/c5193025/content.html>；全国人大常委会 (2023 修正). 民事诉讼法（第一百零九、一百五十二、一百六十四、一百八十三、二百二十五、二百二十七条）. <https://amr.guizhou.gov.cn/zwgk/xxgkml/jcxxgk/zcfg/fl/202401/t20240129_83645867.html>；全国人大常委会 (2011). 刑法修正案（八）第四十一条，即刑法第二百七十六条之一. <http://www.npc.gov.cn/cwhhdbdh/c6626/c14002/c14003/201905/t20190523_390477.html>；最高人民法院 (2013). 关于审理拒不支付劳动报酬刑事案件适用法律若干问题的解释（法释〔2013〕3 号，第三条）. <https://www.court.gov.cn/fabu/xiangqing/5041.html>；国务院 (2019). 保障农民工工资支付条例（国务院令第 724 号，第十、二十六、三十、三十一、三十二、四十一条）. <https://www.gov.cn/gongbao/content/2020/content_5469641.htm>；全国人大常委会 (2021). 法律援助法（第三十一、四十二条）. <https://www.beijing.gov.cn/zhengce/zhengcefagui/qtwj/202504/t20250402_4053713.html>","note":"有用，但要分清「结案」和「到账」：98.2% 的结案率说的是程序走完，公司没财产、老板跑路，裁决赢了也执行不到；最高法只公布执行到位总额（2024 年 2.3 万亿元）和「执行完毕率保持高位」，没有公布欠薪案实际到账比例，这一环没有官方数据。「仲裁终结率」公报未给定义，本条按「裁决后未再进法院」理解。欠一人 3 个月以上且 5000 到 2 万元以上、或欠 10 人以上累计 3 万到 10 万元以上，经责令仍不付即达刑事立案标准，投诉时直接提；工地农民工另有工资专用账户和总包先行清偿，找总包比找包工头管用；进城务工人员申请支付劳动报酬的法律援助免查经济困难。劳动合同法、民事诉讼法原文引自税务总局和贵州省市场监管局转载页（均为 gov.cn），中国人大网页面未能打开；刑法修正案（八）中国人大网页面 WebFetch 握手失败，改用 curl 打开核对","money":"0","time":"中","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"7.3","sec":7,"n":3,"title":"打不起官司就申请法律援助，讨薪、赡养费、工伤这类案子本来就在范围内","cost":"0 元，法律援助不向受援人收费","human":"讨薪、要赡养费、要社保待遇或低保待遇、见义勇为受损，本来就在免费法律援助的范围里，打 12348 或去当地法律援助中心。2022 年起不用再回原籍开经济困难证明，本人如实说明就行。可能判死刑的，以及盲、聋、哑和未成年被告人，不看经济状况一律指派律师。","gain":"行政法规列明的民事援助范围包括「依法请求国家赔偿的；请求给予社会保险待遇或者最低生活保障待遇的；请求发给抚恤金、救济金的；请求给付赡养费、抚养费、扶养费的；请求支付劳动报酬的；主张因见义勇为行为产生的民事权益的」；刑事方面，可能判处死刑的，以及盲、聋、哑和未成年被告人，不看经济状况一律指派律师","grade":"A","src":"国务院 (2003). 法律援助条例（国令第 385 号，第十条、第十一条、第十二条）. <https://www.gov.cn/zhengce/zhengceku/2008-03/28/content_6944.htm>；司法部有关负责人 (2021). 就贯彻实施法律援助法答记者问. <http://www.gov.cn/zhengce/2021-12/29/content_5665114.htm>","note":"2022 年 1 月 1 日起施行的法律援助法把「提交经济困难证明」改成了本人如实说明经济状况，不用再回原籍开证明。入口是各地法律援助中心、公共法律服务中心，或者打 12348","money":"0","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"极高"},{"id":"7.4","sec":7,"n":4,"title":"走投无路时去救助站，管吃住和返乡车票","cost":"0 元；到当地救助管理站求助（或告知民警、民政部门），如实登记姓名和随身物品","human":"管吃、管住、生病送医、帮着联系家人，没钱回家的发车票。一般不超过 10 天，自愿来、自愿走，不是收容，也不发现金。车票按户籍地或住所地开，所以去之前先想清楚要回哪儿。","gain":"救助站提供符合卫生要求的食物、住处、站内突发急病送医、帮联系亲属和单位，没有交通费返回户籍地或住所地的发乘车（船）凭证；救助期限一般不超过 10 天，等待接回、治疗、安置的可延长；公安和其他行政机关人员执行职务时发现流浪乞讨人员应告知其求助，对残疾人、未成年人、老年人和行动不便者要引导护送（全国，2003 年起）","grade":"A","src":"国务院 (2003). 城市生活无着的流浪乞讨人员救助管理办法（国务院令第 381 号，第五、六、七条）. <https://www.gov.cn/gongbao/content/2003/content_62246.htm>；民政部 (2003). 城市生活无着的流浪乞讨人员救助管理办法实施细则（民政部令第 24 号，第十一、十二条）. <https://www.gov.cn/gongbao/content/2003/content_62510.htm>","note":"自愿求助、自愿离站，不是收容。提供的是基本食宿，不发现金。乘车凭证按户籍地或住所地开，求助前想清楚要去哪。","money":"0","time":"少","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"7.5","sec":7,"n":5,"title":"急危重症先救治后付费，没钱也要拨 120","cost":"0 元电话；急救之后的治疗费另算","human":"急救中心和医院不得因为费用问题拒绝、推诿或者拖延急重危伤的救治，违反要被责令改正并处分责任人；身份不明或者确实付不起的急救费用，由疾病应急救助基金付。所以没钱也要打 120。基金只管急救那一段，后面的住院治疗费另算。","gain":"急救中心（站）和急救网络医院不得因费用问题拒绝或延误院前急救，违者责令改正并处分责任人；各级各类医疗机构不得以任何理由拒绝、推诿或拖延急重危伤患者救治；身份不明或无力支付的急救费用由疾病应急救助基金支付（全国，2013 年、2014 年起）","grade":"A","src":"国务院办公厅 (2013). 关于建立疾病应急救助制度的指导意见（国办发〔2013〕15 号）. <https://www.gov.cn/zhengce/zhengceku/2013-03/01/content_6069.htm>；国家卫生计生委 (2013). 院前医疗急救管理办法（国家卫生计生委令第 3 号，第二十五、三十七条）. <https://www.gov.cn/gongbao/content/2014/content_2580977.htm>","note":"基金只覆盖急救阶段的费用，后续住院和治疗费仍要自付或走医保、医疗救助（见第 11 条）；不要因为怕账单拖延急症。","money":"0","time":"少","will":"否","level":"大","lens":"死亡率","dispute":false,"todo":false,"ratio":"极高"},{"id":"7.6","sec":7,"n":6,"title":"找活先用免费的公共就业服务和零工市场，不找收费中介","cost":"0 元；到县级以上公共就业服务机构（就业服务中心、人力资源市场）或本地零工市场登记，或拨 12333 问地址","human":"公共就业服务机构（就业服务中心、人力资源市场）依法免费提供职业介绍、职业指导、政策咨询和就业失业登记，法律明文规定它们不得从事经营性活动；零工市场的信息登记发布也免费。顺手把失业登记办掉——领失业金、认定就业困难人员都要用它。","gain":"法定免费提供就业政策咨询、职业供求信息、职业指导和职业介绍、就业和失业登记、对就业困难人员的就业援助，机构不得从事经营性活动；零工求职招聘信息登记和发布免费向社会提供，纳入公共就业信息服务范围，对待工时间长、低收入家庭等困难零工人员加强帮扶（全国）","grade":"A","src":"全国人大常委会 (2007, 2015 修正). 就业促进法（第三十五条）. <https://www.gov.cn/guoqing/2021-10/29/content_5647636.htm>；人力资源社会保障部等五部门 (2022). 关于加强零工市场建设 完善求职招聘服务的意见（人社部发〔2022〕38 号）. <https://www.gov.cn/zhengce/zhengceku/2022-07/09/content_5700177.htm>","note":"失业登记是领失业保险金、认定就业困难人员的前置手续，顺手办掉。零工日结要当场核对工钱、留联系方式和记录。","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"7.7","sec":7,"n":7,"title":"突发变故先申请临时救助","cost":"0 元；向乡镇政府或街道办提出申请，说明变故（火灾、交通事故、家人突发重大疾病、生活必需支出骤增），经审核公示后由县级民政审批；材料按当地清单，通常跑 1 到 2 趟","human":"家里突然出事（火灾、车祸、家人突发重病）导致基本生活暂时严重困难的，可以向乡镇政府或街道办申请临时救助，不要求你已经是低保户。多为一次性发放，金额各地差别很大。","gain":"因意外事件、家庭成员突发重大疾病等导致基本生活暂时严重困难的家庭，以及生活必需支出突然增加超出承受能力的低保家庭，可获临时救助；具体事项和标准由县级以上地方政府确定并公布（全国制度，金额地方定，2014 年起）","grade":"B","src":"国务院 (2014, 2019 修订). 社会救助暂行办法（国务院令第 649 号，第四十七、四十八、四十九条）. <https://www.gov.cn/gongbao/content/2019/content_5468952.htm>","note":"不要求已经是低保户；多为一次性发放，金额各地差异大，以当地当年公布为准。","money":"0","time":"中","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"7.8","sec":7,"n":8,"title":"收入低于当地低保线就申请低保","cost":"0 元；由共同生活的家庭成员向户籍所在地乡镇政府或街道办书面申请，申请有困难可委托村委会、居委会代办；接受家庭收入和财产核查，通常跑 2 到 3 趟，需身份证、户口本和收入财产证明","human":"家庭人均收入低于当地低保线、财产也符合规定的可以申请。2024 年末全国城市低保平均 798.1 元每人每月、农村 593.9 元，分别保着 625 万人和 3361.5 万人。按户籍地申请，有房有车有存款、或者有赡养能力的子女，可能不符合。低保身份还连着医保资助参保、医疗救助、法律援助免核查。","gain":"家庭人均收入低于当地低保标准且财产符合规定的家庭可获保障；2024 年末全国城市低保平均标准 798.1 元/人·月、农村 593.9 元/人·月，分别保障 625.0 万人和 3361.5 万人；标准按当地上年度居民人均消费支出乘以量化比例确定并适时调整（全国平均，各地不同）","grade":"A","src":"国务院 (2014, 2019 修订). 社会救助暂行办法（国务院令第 649 号，第九、十、十一条）. <https://www.gov.cn/gongbao/content/2019/content_5468952.htm>；国家统计局 (2025). 社会事业向好发展 民生福祉不断增进——「十四五」以来社会民生统计报告. <https://www.gov.cn/lianbo/bumen/202509/content_7042627.htm>；民政部等四部门 (2024). 关于进一步做好最低生活保障标准确定调整工作的指导意见（民发〔2024〕16 号）. <https://www.gov.cn/zhengce/zhengceku/202403/content_7007237.htm>","note":"低保是兜底，按户籍地申请，家庭财产（房、车、存款）超标或有赡养能力的子女可能不符合；低保身份还联动医保资助参保、医疗救助、法律援助免核查等（见第 3、10、11 条）。","money":"0","time":"中","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"7.9","sec":7,"n":9,"title":"持残疾人证的去申请残疾人两项补贴","cost":"0 元；带证到街道或乡镇提交一次申请","human":"低保家庭里的残疾人可以领生活补贴，一级二级且需要长期照护的可以领护理补贴，两项能同时领。标准各省自己定，差别很大，具体问街道。带上二代残疾人证，去街道或乡镇办一次就行。","gain":"国务院建立的两项制度：困难残疾人生活补贴「对象为低保家庭中的残疾人，有条件的地方可逐步扩大到低收入残疾人及其他困难残疾人」；重度残疾人护理补贴「对象为残疾等级被评定为一级、二级且需要长期照护的重度残疾人」。两项可以同时享受","grade":"A","src":"国务院 (2015). 关于全面建立困难残疾人生活补贴和重度残疾人护理补贴制度的意见（国发〔2015〕52 号）. <https://www.gov.cn/zhengce/zhengceku/2015-09/25/content_10181.htm>","note":"标准由省级政府定，各地差别很大，几十元到几百元每月不等。申请要带第二代残疾人证，本人不便的可以委托家属代办","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"7.10","sec":7,"n":10,"title":"居民医保每年 400 元不要断，困难户可减免","cost":"个人缴费每人每年不低于 400 元（2024、2025 年国家标准，各地可高于此数），在集中缴费期缴纳；特困人员全额资助，低保对象定额资助","human":"个人一年交 400 元起，财政再按人头补 700 元上下；特困人员全额资助、低保对象定额资助。断缴的代价很实在：没在集中期参保或者没连续参保的，参保后有 3 个月固定等待期，每多断一年原则上再加 1 个月。","gain":"财政按人头补助每年不低于 670 元（2024 年）、700 元（2025 年，河北省文件转述的国家标准），2026 年政府工作报告再提高 24 元；低保对象、特困人员符合规定的医疗费经医保报销后可按不低于 70% 的比例医疗救助。断缴代价：未在集中期参保或未连续参保的，参保后固定待遇等待期 3 个月，每多断保 1 年原则上加 1 个月（2025 年起，全国）","grade":"A","src":"国家医保局 (2024). 《关于做好 2024 年城乡居民基本医疗保障有关工作的通知》政策解读（医保发〔2024〕19 号）. <https://www.nhsa.gov.cn/art/2024/8/26/art_105_13634.html>；河北省医疗保障局等 (2025). 关于做好 2025 年城乡居民基本医疗保障有关工作的通知（冀医保发〔2025〕6 号，地方文件）. <https://www.renqiu.gov.cn/renqiu/ybjbmwj/202510/6d90754638a248cba655e94ea518a3bb.shtml>；国务院办公厅 (2021). 关于健全重特大疾病医疗保险和救助制度的意见（国办发〔2021〕42 号）. <https://www.gov.cn/gongbao/content/2021/content_5659514.htm>；国务院办公厅 (2024). 关于健全基本医疗保险参保长效机制的指导意见（国办发〔2024〕38 号）. <https://www.gov.cn/zhengce/content/202408/content_6965741.htm>；国家医保局 (2026). 2026 年政府工作报告提到这些医保工作. <https://www.nhsa.gov.cn/art/2026/3/5/art_14_19809.html>","note":"国家医保局 2025 年通知（医保发〔2025〕22 号）原文页未能打开，700 元取自地方文件转述，待核实；领失业保险金期间职工医保由失业保险代缴，不必重复参保。","money":"少","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":true,"ratio":"高"},{"id":"7.11","sec":7,"n":11,"title":"得了重病先走医保、大病保险、医疗救助和异地备案，不碰网贷","cost":"0 元；顺序是：跨省住院前用「国家医保局」微信公众号里的「国家异地就医备案」小程序备案 → 出院直接结算 → 报销后自付仍过重的，向乡镇政府或街道办申请医疗救助 → 在职的按医疗期请病假、工伤的走工伤保险 → 还不上信用卡的主动找银行协商分期 → 实在不够再上民政部指定的个人求助平台；材料主要是诊断证明、费用清单、结算单，跑 2 到 4 趟","human":"顺序是固定的：跨省住院前先在「国家医保局」公众号里备案，出院直接结算，不用先垫全款；报销完自付还是太重的，向乡镇或街道申请医疗救助（低保对象、特困人员按不低于 70% 救助）；在职的按工龄享受 3 到 24 个月医疗期，这期间不得解除劳动合同、病假工资不得低于当地最低工资的 80%；工伤走停工留薪期，原工资照发；信用卡还不上就主动找银行协商，最长可分 5 年，签了协议银行必须停止催收。网贷和高息民间借款不要碰：超出法定上限的利息法院不支持（见本节第 16 条），但本金照还，病床上没精力去打这种官司。","gain":"国家把基本医保、大病保险、医疗救助合称「三重制度」综合保障，低保对象、特困人员符合规定的医疗费用按不低于 70% 救助，因病致贫重病患者可依申请救助；跨省备案后可直接结算，不必先垫全款再回参保地报；患病停工有 3 到 24 个月医疗期（按工龄定），期内不得解除劳动合同，病假工资不得低于当地最低工资的 80%；工伤职工停工留薪期原工资福利待遇不变、由单位按月发，一般不超过 12 个月；信用卡欠款超出还款能力且有还款意愿的，可与银行协商个性化分期，最长 5 年，签了协议银行须停止催收；个人求助平台须经国务院民政部门指定，平台须核验求助信息真实性，捐助资金只能打给求助人本人或其提供的账户（全国）","grade":"A","src":"国务院办公厅 (2021). 关于健全重特大疾病医疗保险和救助制度的意见（国办发〔2021〕42 号）. <https://www.gov.cn/gongbao/content/2021/content_5659514.htm>；国家医保局 (2025). 跨省异地就医如何直接报销？. <https://www.nhsa.gov.cn/art/2025/3/16/art_14_16010.html>；劳动部 (1994). 企业职工患病或非因工负伤医疗期规定（劳部发〔1994〕479 号，第二、三条）. <https://www.gov.cn/zhengce/2022-08/31/content_5711269.htm>；劳动部 (1995). 关于贯彻执行《劳动法》若干问题的意见（劳部发〔1995〕309 号，第 59 条）. <http://hrss.jl.gov.cn/ldgx/ldyggl/201608/t20160824_2401358.html>（吉林省人社厅转载）；国务院 (2010 修订). 工伤保险条例（国务院令第 586 号，第三十、三十三条）. <https://www.gov.cn/gongbao/content/2011/content_1778064.htm>；银监会 (2011). 商业银行信用卡业务监督管理办法（银监会令 2011 年第 2 号，第七十条）. <https://www.gov.cn/gongbao/content/2011/content_1893974.htm>；全国人大常委会 (2023). 关于修改慈善法的决定（第一百二十四条）. <https://www.gov.cn/yaowen/liebiao/202312/content_6923390.htm>；民政部等五部门 (2024). 个人求助网络服务平台管理办法（令第 75 号，第三、十一、十三、十七条）. <https://www.gov.cn/gongbao/2024/issue_11646/202410/content_6980857.html>","note":"医疗救助的具体比例和年度限额由各统筹地区定；医疗期按「实际工作年限」和「本单位工作年限」分六档，期满后可能被合法解约，提前看清自己在哪一档。急诊抢救人员也被列在需备案的人群里，医保局页面未说急诊是否视同备案，事后补备案是否可行问参保地。网贷和民间高息借款不要碰：司法保护上限是一年期 LPR 的 4 倍（见第 16 条，不借高利贷），超出部分不受保护但本金照还，病床上没有精力去打这种官司。劳部发〔1995〕309 号原文页在人社部官网未能打开，取自省人社厅转载。","money":"0","time":"中","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"7.12","sec":7,"n":12,"title":"身份证丢了立刻补办，急用先领临时身份证","cost":"证件工本费（法定收费，标准由国务院价格主管部门会同财政部门核定，以当地公示为准）；到常住户口所在地派出所申请，跑 1 趟","human":"补办从交表那天算起 60 天内发证；急用的当场申请临时身份证，3 天内发，有效期 3 个月。没有身份证，找工作、住宿、开户、领补贴全都办不成，它是所有手续的前提。","gain":"公安机关自提交《居民身份证申领登记表》之日起 60 日内发证；申领、换领、补领期间急用的可申请临时居民身份证，公安机关收到申请后 3 日内发放，有效期 3 个月（全国）","grade":"A","src":"全国人大常委会 (2003). 居民身份证法（主席令第四号，第十二、二十条）. <https://www.gov.cn/gongbao/content/2003/content_62254.htm>；公安部 (2005). 临时居民身份证管理办法（公安部令第 78 号，第二、七、九、十二、十七条）. <https://www.gov.cn/zhengce/2021-12/25/content_5712922.htm>","note":"没有身份证，找工作、住宿、开户、领补贴都办不了，这是所有手续的前置。身份证法 2011 年有修正，所引为 2003 年公布文本，条款以现行为准；异地办理是否可行以当地公安公告为准。","money":"少","time":"少","will":"否","level":"小","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"7.13","sec":7,"n":13,"title":"办失业登记后争取就业困难人员认定，拿社保补贴或公益性岗位","cost":"0 元；到街道或社区的公共就业服务机构申请认定，认定条件各地不同（大龄、长期失业、低保家庭、残疾、零就业家庭等），需失业登记在先","human":"认定下来之后，自己交社保能拿补贴，原则上不超过实际缴费的三分之二、最长 3 年；单位招用你或者公益性岗位安置的，单位那部分社保也有补贴，公益性岗位工资参照当地最低工资。这类岗位工资不高但带社保，适合过渡。注意社保补贴多是先缴后补，得先垫钱。","gain":"认定后灵活就业自缴社保可获补贴，标准原则上不超过实际缴费的 2/3，最长 3 年；单位招用或公益性岗位安置的，单位按实际缴纳的养老、医疗、失业保险费获补贴，公益性岗位补贴参照当地最低工资，政府开发的公益性岗位优先安排就业困难人员；低保家庭、零就业家庭、特困人员中的高校毕业生以及残疾、获国家助学贷款的高校毕业生，毕业学年有一次性求职补贴（全国框架，认定条件与金额地方定）","grade":"B","src":"财政部、人力资源社会保障部 (2023 修订). 就业补助资金管理办法（财社〔2017〕164 号，2023 年 12 月修订印发）. <https://www.gov.cn/zhengce/zhengceku/202401/content_6926462.htm>；全国人大常委会 (2007, 2015 修正). 就业促进法（第五十二、五十三条）. <https://www.gov.cn/guoqing/2021-10/29/content_5647636.htm>","note":"公益性岗位工资不高但有社保，适合过渡；社保补贴多是先缴后补，要先垫钱。具体条件问 12333 或街道。","money":"0","time":"中","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"7.14","sec":7,"n":14,"title":"失业期间去领职业培训补贴、就业见习补贴和社保补贴，别自费上培训班","cost":"0 元；培训本身要花时间","human":"培训不用自己掏钱：参加培训并拿到规定证书就有职业培训补贴，同一个人最多领 3 次；灵活就业的社保补贴最长 3 年；毕业两年内没就业的高校毕业生和 16 到 24 岁失业青年可以参加就业见习，领基本生活费。先去当地人社局官网查「职业培训补贴目录」，别自费报班。","gain":"财政部、人社部规章规定的就业补助资金项目：参加培训并取得符合规定证书的，给予职业培训补贴，同一人最多享受 3 次；就业困难人员灵活就业的社保补贴最长 3 年，距法定退休年龄不足 5 年的可延到退休；高校毕业生灵活就业的社保补贴最长 2 年，企业吸纳的最长 1 年；毕业 2 年内未就业的高校毕业生和 16 至 24 岁失业青年可参加就业见习，领基本生活费","grade":"A","src":"财政部、人力资源社会保障部 (2023). 就业补助资金管理办法（第五条、第七条、第十条）. <https://www.gov.cn/zhengce/zhengceku/202401/content_6926462.htm>","note":"具体补贴目录和金额由各省定，先在当地人社局官网查「职业培训补贴目录」。低保家庭、零就业家庭、有助学贷款或残疾的毕业年度高校毕业生还有一次性求职创业补贴","money":"0","time":"中","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"7.15","sec":7,"n":15,"title":"求职别只投简历，用系统方法：学技巧、定目标、找人帮","cost":"每天 1 到 2 小时，坚持数周；可用公共就业服务机构的免费职业指导替代付费课程","human":"47 项研究汇总：参加过结构化求职辅导的人，找到工作的几率是没参加的 2.67 倍。管用的成分是学具体的求职技巧、把自己讲清楚、定明确目标、主动出击，以及开口找人帮忙介绍——最后一条落到实处就是托熟人内推，别不好意思张嘴。公共就业服务机构的职业指导是免费的。","gain":"对 47 项实验或准实验评估的求职干预做荟萃分析，参加干预者获得就业的几率是对照组的 2.67 倍（OR 2.67）；有效成分是教求职技巧、改善自我呈现、提升自我效能、鼓励主动、设定目标、争取社会支持，同时含技能训练和动机提升的干预效果最大","grade":"A","src":"Liu S, Huang JL, Wang M (2014). Effectiveness of job search interventions: a meta-analytic review. Psychological Bulletin 140(4): 1009–1041. <https://doi.org/10.1037/a0035923>","note":"纳入研究多来自欧美，干预多为结构化小组课程，中国情境是外推；「争取社会支持」在实践中就是让熟人帮忙介绍和内推，别不好意思开口。","money":"0","time":"中","will":"是","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"7.16","sec":7,"n":16,"title":"不交押金、不押证件、不签「培训贷」、不进传销、不借高利贷","cost":"0 元；遇到「先交钱再上岗」「先培训再安排工作」「拉人头」当场拒绝，留好聊天记录和转账凭证","human":"用人单位不得扣押你的身份证，不得收押金或者变相收财物，违反的责令退还并按每人 500 到 2000 元罚款；中介介绍不成必须退中介费。「先交培训费再上岗」的培训贷、拉人头计酬的传销，都是官方点名的套路。民间借贷超过一年期 LPR 四倍的利息法院不支持——但本金照还，别以为借了能赖掉。越急着用钱越容易被这些盯上。","gain":"用人单位不得扣押身份证等证件、不得要求担保或以其他名义收取财物，违者责令退还并按每人 500 元以上 2000 元以下罚款；职业中介不得扣证件、收押金，介绍不成功须退中介费；以招聘为名诱导付费培训或贷款是人社部等五部门明确提示的「招转培」「培训贷」骗局；拉人头计酬、交费取得加入资格属传销，参加者可罚 2000 元以下；民间借贷利率超过合同成立时一年期 LPR 4 倍的部分法院不支持，替代了原 24%/36% 两线三区（全国，2020 年 8 月起）","grade":"A","src":"全国人大常委会 (2007). 劳动合同法（主席令第六十五号，第九、八十四条）. <https://www.gov.cn/gongbao/content/2007/content_711013.htm>；劳动保障部 (2007). 就业服务与就业管理规定（劳动保障部令第 28 号，第十四、五十五、五十八条）. <https://www.gov.cn/zhengce/2022-11/28/content_5711307.htm>；人力资源社会保障部等五部门 (2026). 警惕「招转培」「培训贷」等风险提示. <https://chinajob.mohrss.gov.cn/h5/c/2026-05-18/543038.shtml>；国务院 (2005). 禁止传销条例（国务院令第 444 号，第二、七、二十四条）. <https://www.gov.cn/gongbao/content/2005/content_80604.htm>；最高人民法院 (2020). 关于修改《关于审理民间借贷案件适用法律若干问题的规定》的决定（法释〔2020〕6 号，第二十六条）. <https://www.court.gov.cn/fabu/xiangqing/249031.html>；最高人民法院 (2020). 民间借贷利率司法保护上限调整为「一年期 LPR 的 4 倍」. <https://www.court.gov.cn/zixun/xiangqing/249051.html>","note":"4 倍 LPR 是司法保护上限，不等于借了不用还本金；该司法解释 2020 年 12 月再次修正，条文序号有变，以现行文本为准。越急着用钱越容易被这些套路盯上，先走第 1 到 7 条的正规渠道。","money":"0","time":"少","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"7.17","sec":7,"n":17,"title":"住房困难先排公租房","cost":"0 元申请费；向市、县住房保障部门提交材料，书面同意核实申报信息，材料不齐会一次性告知补正；轮候期一般不超过 5 年","human":"条件是三条：本地无房或住房面积低于标准、收入财产低于标准、外来务工的还要在本地稳定就业满规定年限。轮候期由当地公布——远水不解近渴，但排队不花钱，早报名早轮到。","gain":"符合三项条件即可申请：在本地无住房或住房面积低于规定标准、收入和财产低于规定标准、外来务工人员在本地稳定就业达规定年限；具体条件由直辖市和市、县住房保障部门定并公布，登记为轮候对象的应在轮候期内安排房源（全国框架，门槛和租金地方定，2012 年起）","grade":"B","src":"住房和城乡建设部 (2012). 公共租赁住房管理办法（住房和城乡建设部令第 11 号，第七、八、十条）. <https://www.gov.cn/gongbao/content/2012/content_2226147.htm>","note":"远水不解近渴，但排队不花钱，早报名早轮到；各地另有保障性租赁住房等类型，规则不同，去当地住建部门网站查。","money":"0","time":"中","will":"否","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"7.18","sec":7,"n":18,"title":"把住和吃压到最低：合租月租代替日租，自炊和助餐食堂代替外卖","cost":"找房 1 到 3 天，押金通常 1 个月（作者粗估）；自炊每天 30 到 60 分钟","human":"2025 年全国人均消费里，吃占 29.3%、住占 21.7%，两项加起来过半，所以压这两项最有效。按作者经验，日租房、钟点房按月折算比合租贵；自己做饭比外卖便宜。找工作时问清包不包吃住，包的岗位等于直接把这两大项抹掉。","gain":"2025 年全国居民人均消费支出 29476 元，其中食品烟酒 8631 元占 29.3%、居住 6397 元占 21.7%，两项过半，压这两项最有效；老年助餐服务（老年食堂、老年餐桌、助餐点）面向全体老年人开展，困难老人有差异化补贴；作参照，截至 2026 年 1 月 1 日各省第一档月最低工资在 2080 元（青海）到 2740 元（上海）之间（全国，2025 至 2026 年）","grade":"B","src":"国家统计局 (2026). 2025 年居民收入和消费支出情况. <https://www.stats.gov.cn/sj/zxfbhjd/202601/t20260119_1962321.html>；民政部等十一部门 (2023). 积极发展老年助餐服务行动方案（民发〔2023〕58 号）. <https://www.gov.cn/govweb/zhengce/zhengceku/202310/content_6911233.htm>；四川省人力资源和社会保障厅 (2026). 全国各省、自治区、直辖市最低工资标准情况（截至 2026 年 1 月 1 日，转载人社部官网表）. <https://rst.sc.gov.cn/rst/ylbxjwjgzxx/2026/7/10/89a8ef06cc264d29b282d7c62f362a6b.shtml>","note":"日租、钟点房按月算比合租贵得多，是经验判断，无官方数字；老年助餐点是否对非老年人开放、价格多少各地不同；找工作时问清是否包吃住，包吃住的岗位能直接抹掉这两大项。人社部原表页面未能打开，数字取自四川省人社厅转载页。","money":"0","time":"中","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"7.19","sec":7,"n":19,"title":"社保断缴不要慌：养老按累计算，医保按规则补","cost":"0 元；居民养老、居民医保可按年自缴，职工社保断缴期间不必为了「不断」去花钱挂靠","human":"养老金按累计年限算，不是按连续年限算，断了不清零：到退休年龄累计满 15 年就能按月领，不够可以续缴到满。职工医保累计够国家规定年限的，退休后不用再交。真正受影响的是各地跟连续缴费挂钩的资格（买房、落户、积分），那是地方规则，自己去核对。花钱找第三方挂靠代缴有资金和法律风险，不值。","gain":"基本养老保险按累计缴费年限计算，达到法定退休年龄累计满 15 年即可按月领养老金，不足的可续缴至满 15 年；跨统筹地区就业的养老关系随人转移、缴费年限累计；职工医保累计缴费达国家规定年限的退休后不再缴费；居民医保断缴的代价是等待期（见第 10 条）（全国）","grade":"A","src":"全国人大常委会 (2010, 2018 修正). 社会保险法（第十六、十九、二十七条）. <https://www.gov.cn/guoqing/2021-10/29/content_5647616.htm>；国务院办公厅 (2024). 关于健全基本医疗保险参保长效机制的指导意见（国办发〔2024〕38 号）. <https://www.gov.cn/zhengce/content/202408/content_6965741.htm>","note":"断缴影响的主要是各地与连续缴费挂钩的资格（购房、落户、积分等），那是地方规则，需自行核对；花钱找第三方「挂靠」缴社保有资金和法律风险，不建议。","money":"0","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"极高"},{"id":"7.20","sec":7,"n":20,"title":"坐过牢、破过产、上过失信名单，法律上都有重来的路，先把手续走完","cost":"0 元手续费；刑满释放后到户籍地或居住地司法所、街道报到并申请安置帮教；失信被执行人履行完义务后向执行法院申请删除；深圳参保满 3 年的个人可申请个人破产；每一步都要面对材料、面谈和 1 到 3 年的考察期","human":"刑满释放的人依法与其他公民享有平等权利，就业、就学、社保上不得歧视，生活困难的由政府帮助安置；犯罪时不满 18 岁、判 5 年以下的，记录封存，入伍就业不必报告。失信被执行人名单的纳入期限是 2 年，履行完毕的法院应当在 3 个工作日内删除。个人破产目前只有深圳有，宣告后考察期满 3 年可以免掉没还完的债。也不美化：成年人的前科不封存，法律要求入伍、就业时如实报告，公务员、法官、律师、教师这些职业有硬性限制。","gain":"刑满释放人员依法享有与其他公民平等的权利，在就业、就学和享受社会保障方面不受歧视，生活困难的由户籍地或居住地政府帮助安置、依法救助帮扶（监狱法 2026 年修订，11 月 1 日起施行）；中央 2010 年文件要求对其强化职业培训、符合条件的纳入低保、建立过渡性安置基地；犯罪时不满 18 岁且判刑 5 年以下的，犯罪记录封存，入伍、就业时免除报告义务，本人申请无犯罪记录证明的 3 个工作日内出具；失信名单纳入期限为 2 年，履行完毕、达成和解等情形下法院应在 3 个工作日内删除；深圳经济特区个人破产条例是目前唯一的个人破产法规，宣告破产后 3 年考察期满可免除未清偿债务；企业法人不能清偿到期债务且资不抵债的，可申请重整、和解或破产清算，债务随法人了结（全国，个人破产仅深圳）","grade":"A","src":"全国人大常委会 (2026). 监狱法（2026 年修订，第五十九、六十、六十二条）. <https://www.spp.gov.cn/spp/fl/202604/t20260430_726746.shtml>；中共中央办公厅、国务院办公厅 (2010). 转发《中央社会治安综合治理委员会关于进一步加强刑满释放解除劳教人员安置帮教工作的意见》的通知（中办发〔2010〕5 号）. <http://www.hnziyang.gov.cn/jc_zy/63/84/content_19460.html>（益阳市资阳区政府转载）；全国人大常委会 (2018). 刑事诉讼法（2018 年修正，第二百八十六条）. <https://www.spp.gov.cn/zdgz/201810/t20181027_396818.shtml>；最高人民法院、最高人民检察院、公安部、司法部 (2022). 关于未成年人犯罪记录封存的实施办法（第九、十五条）. <https://gat.hunan.gov.cn/gat/jwgk/zfxxgk/xxgkml/zcfgjjd/zcfg/202205/t20220531_24795836.html>（湖南省公安厅转载）；最高人民法院 (2017 修正). 关于公布失信被执行人名单信息的若干规定（第二、十条）. <https://www.court.gov.cn/fabu/xiangqing/37182.html>；深圳市人大常委会 (2020). 深圳经济特区个人破产条例（第二、二十三、九十五、九十七、一百零三条）. <https://sf.sz.gov.cn/xxgk/xxgkml/zcfg/content/post_8586018.html>；全国人大常委会 (2006). 企业破产法（主席令第五十四号，第二、七条）. <http://www.gov.cn/gongbao/content/2006/content_413952.htm>","note":"不美化：成年人的前科不封存，刑法第一百条规定入伍、就业时必须如实报告曾受刑事处罚，公务员、法官、律师、教师等职业和政审有法定限制，本条不改变这一点。监狱法 2026 年 11 月 1 日前的现行文本对应第三十七、三十八条，条号以生效文本为准；中办发〔2010〕5 号未在中央政府网找到原文页，取自区政府转载；个人破产考察期内限制乘坐飞机头等舱、高消费、买房等，因故意侵害人身产生的赔偿等 8 类债务不免除，欺诈取得的免责可被撤销。失信名单删除不等于征信修复，两套系统。","money":"0","time":"中","will":"是","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"7.21","sec":7,"n":21,"title":"大病之前，基本医保之外配一份一年期医疗险或重疾险，看清「保证续保」四个字","cost":"年轻人一年期费用补偿型医疗险每年几百元，重疾险每年几千元起（作者粗估，无官方数字）；投保前如实告知健康状况，一次性半小时","human":"这类保险补的是医保报完之后你自己要掏的那部分，以及停工的损失。买之前认准「保证续保」四个字：没有这四个字的，明年可能停售或涨价；有的话，到期时公司必须按原条款接着保。两份费用补偿型医疗险不能对同一笔费用重复报销，别叠着买。健康状况要如实告知，瞒了会被拒赔。先把基本医保交上，再考虑这条。","gain":"官方分类里，医疗保险按实际医疗费用补偿，疾病保险在确诊约定疾病时定额给付，两者补的是医保报完之后的自付和停工损失；保险期间一年及以下且不含保证续保条款的是短期健康险，超过一年或含保证续保条款的才是长期健康险，「保证续保」指到期续保时公司必须按原条款和约定费率承保；保险公司不得诱导为同一被保险人重复购买保障功能相同或类似的费用补偿型医疗险；重疾险的疾病定义有行业统一规范，28 种重度疾病和 3 种轻度疾病，恶性肿瘤、急性心肌梗死、脑中风后遗症是核心病种（全国，2019、2020 年起）","grade":"B","src":"银保监会 (2019). 健康保险管理办法（银保监会令 2019 年第 3 号，第二、四、四十一条）. <https://www.gov.cn/zhengce/zhengceku/2019-12/04/content_5458542.htm>；中国保险行业协会、中国医师协会 (2020). 重大疾病保险的疾病定义使用规范（2020 年修订版）答记者问. <https://www.iachina.cn/art/2020/11/5/art_8616_104705.html>；银保监会 (2020). 关于使用《中国人身保险业重大疾病经验发生率表（2020）》有关事项的通知（银保监发〔2020〕51 号）. <https://www.gov.cn/zhengce/zhengceku/2020-11/06/content_5557791.htm>","note":"B 级原因是官方只给定义和规则，没有「买了能省多少」的数字。「百万医疗险」是市场叫法，法律类别是短期健康险，不含保证续保的产品明年可能停售或涨价，买前看条款里有没有「保证续保」；两份费用补偿型医疗险不能重复报销同一笔费用，别叠着买。带病投保未如实告知会被拒赔，先把基本医保（第 10 条）交上，再考虑这条。疾病定义规范由行业协会发布、银保监会指导，非政府文件。","money":"少","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"7.22","sec":7,"n":22,"title":"实在没地方睡，24 小时营业场所只能应急一晚，优先去救助站","cost":"机场、火车站候车区通常 0 元，快餐店、网吧需要低消费；睡眠质量差，财物有被盗风险","human":"机场、火车站候车区能撑一夜，有厕所有电源，但没有任何官方数据说这样安全。财物贴身，不接陌生人递的吃喝，别去偏僻角落，桥洞、河边、工地夜里不能睡，极端天气露宿会出人命。救助站是免费管吃住的，优先去那儿。","gain":"能撑过一夜，有厕所和充电；没有官方数字","grade":"C","src":"作者经验，无官方文件","note":"安全风险真实存在：财物贴身，不接陌生人递的饮料食物，避开偏僻角落，夜间不要露宿桥洞、河边、工地；极端天气露宿会出人命。第 4 条的救助站免费管吃住，先去那里。部分场所会清场，不要与安保冲突。","money":"少","time":"少","will":"些","level":"小","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"}]},{"n":8,"title":"别把自己搭进去：法律与财产安全","intro":"本节口径是金钱与人身自由：法律规定的责任是什么、能避免多大的损失、你有哪些程序上的权利，不换算成寿命。条款号以核实过的官方原文为准，排序按「一次事故损失最大、做起来最省事」从高到低，需要提前安排的放中间，经验条目放最后。","entries":[{"id":"8.1","sec":8,"n":1,"title":"出了交通事故先停车、救人、报警，不要跑","cost":"0 元；停车、开双闪、救人、打电话报警，最多耗掉一两个小时等交警；没人受伤、对事实没争议的小事故，拍照记下对方姓名、电话、车牌、驾驶证号、保险凭证号和碰撞部位，双方签字后即可撤离现场自行协商","human":"逃了，事故就默认由你负全责，驾照吊销而且终生不得重考；构成交通肇事罪的，逃逸判 3 到 7 年，因逃逸致人死亡判 7 年以上。还有更现实的一层：车损险和三者险对逃逸一律不赔，几十万赔偿全部自己掏。留在现场救人、报警，最多耗掉一两个小时。","gain":"逃逸的一方承担事故全部责任，只有证明对方也有过错才可减轻；逃逸吊销驾驶证并终生不得重新取得；构成交通肇事罪的，逃逸判 3 到 7 年，因逃逸致人死亡判 7 年以上；商业车险的车损险和三者险对「交通肇事逃逸」「故意破坏、伪造现场、毁灭证据」一律不赔，几十万的赔偿全部自掏（全国）","grade":"A","src":"全国人大常委会 (2021). 道路交通安全法（2021 年修订，第七十、一百零一条）. <https://jtgl.beijing.gov.cn/jgj/jgxx/flfg/fl/205308/index.html>（北京市公安交通管理局转载）；国务院 (2017). 道路交通安全法实施条例（国务院令第 405 号，2017 年修订，第八十六、九十二条）. <http://xzfg.moj.gov.cn/front/law/detail?LawID=75>；全国人大 (1997). 刑法（第一百三十三条）. <https://www.spp.gov.cn/spp/fl/201802/t20180206_364975.shtml>；中国保险行业协会 (2020). 机动车商业保险示范条款（2020 版）（第九、二十二条）. <https://www.iachina.cn/art/2020/9/4/art_24_104621.html>","note":"有人受伤时先救人再报警，为救人挪动现场要标明位置。「撞了没感觉就走了」在事后认定里也可能算逃逸，拿不准就报警。示范条款是行业示范文本，各公司条款以自己的保单为准。","money":"0","time":"少","will":"否","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"极高"},{"id":"8.2","sec":8,"n":2,"title":"发现被骗，立刻打 110 或 96110 要求止付，别先自己查","cost":"0 元；一个电话，说清转账时间、金额、对方账号，把转账截图和聊天记录留好","human":"钱刚转出去的那一小段时间是唯一的窗口：警方可以紧急止付、快速冻结，银行必须配合；等钱被层层转走分散，就基本追不回来了。所以先打 110 或 96110，别自己先去查、先去问。96110 打进来的是警察在劝阻你，一定要接。","gain":"公安机关有权对涉案资金做即时查询、紧急止付、快速冻结，银行和支付机构必须配合，冻结住的钱按程序返还被害人；钱一旦被转走分散，追回概率大幅下降，止付越早越有效；96110 是全国统一的反诈预警热线，来电是警方在劝阻你，务必接（全国，2022 年 12 月起）","grade":"A","src":"全国人大常委会 (2022). 反电信网络诈骗法（第二十、三十四条）. <https://www.spp.gov.cn/spp/fl/202209/t20220902_575631.shtml>；福建省公安厅 (2023). 96110 来电，请务必接听. <http://gat.fujian.gov.cn/ztzl/fjjffpzxrx/spjq/202303/t20230306_6126156.htm>（省级公安机关页面）","note":"法律只规定「建立止付冻结制度」，能追回多少取决于报警时钱是否还在账上。「国家反诈中心」App 和 96110 的介绍引自福建省公安厅页面，公安部网站原文页未能打开。凡自称公检法要你转到「安全账户」的都是骗局。","money":"0","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"极高"},{"id":"8.3","sec":8,"n":3,"title":"记住反诈硬规则：来电不轻信、信息不透露、链接不点击、转账多核实","cost":"0 元；把「三不一多」记住，凡要你转账、共享屏幕、下载陌生 App、点链接、报验证码的，一律先挂断再打官方电话核实；装「国家反诈中心」App","human":"凡是让你转账、共享屏幕、下载陌生 App、点链接、报验证码的，先挂断，再用官方号码打回去核实。自称公检法、客服、领导、平台风控，让你「配合调查」「取消会员」「刷单返利」「投资内幕」的，都是同一套路换个皮。事前认出来，比事后追钱便宜得多。","gain":"法律要求政府和有关部门普及各类电信网络诈骗方式，公安机关会同金融、电信、网信部门建立预警劝阻系统，对预警发现的潜在被害人及时劝阻，96110 就是这条全国统一的预警劝阻热线，来电要接；事前识别比事后止付便宜得多，止付能追回多少取决于报警时钱是否还在账上（见第 2 条）（全国，2022 年 12 月起）","grade":"B","src":"全国人大常委会 (2022). 反电信网络诈骗法（第八、二十、三十四条）. <https://www.spp.gov.cn/spp/fl/202209/t20220902_575631.shtml>；福建省公安厅 (2023). 96110 来电，请务必接听. <http://gat.fujian.gov.cn/ztzl/fjjffpzxrx/spjq/202303/t20230306_6126156.htm>（省级公安机关页面，含「来电不轻信，信息不透露，链接不点击，转账多核实」口诀及「警惕 192 开头的诈骗电话」提示）","note":"B 级原因是口诀是官方宣传口径，没有「记住后少被骗多少」的数字。公安部官网（mps.gov.cn）在本次核实时无法打开，口诀取自省级公安厅页面，TODO（待核实：公安部或国家反诈中心的原文页）。自称公检法、客服、领导、平台风控要你「配合调查」「取消会员」「刷单返利」「投资内幕」的，全是同一套路的不同皮。","money":"0","time":"少","will":"些","level":"大","lens":"金钱","dispute":false,"todo":true,"ratio":"高"},{"id":"8.4","sec":8,"n":4,"title":"视频里看见脸、电话里听见声音都不算核实，涉及转账先挂断，用自己通讯录里的旧号码打回去","cost":"0 元；多打一个电话、多等几分钟；少在公开账号上发正脸视频和长段语音","human":"看见脸、听见声音都不算核实。公安部网安局给的办法：让对方做一个连贯的转头动作，或者用手掌完全遮住脸再快速移开，现在的换脸在这种遮挡和光影变化上容易卡顿、变形。但最稳的一招是挂断，用你自己通讯录里存的旧号码打回去，或者找共同认识的人侧面问一句。对方以「信号不好」「在开会」为由拒绝当面视频、拒绝做指定动作的，直接当骗局处理。另外，合规平台要给 AI 内容打标识，骗子不会打——所以「没看到 AI 标识」不能反过来当成对方是真人的证据。","gain":"公安部网安局给的三条办法：动作验证法（请对方做一个连贯的转头动作，或用手掌完全遮住脸再快速移开，「目前的 AI 技术在模拟这些复杂的面部遮挡和光影变化时，容易出现卡顿、模糊或扭曲」）；声音细节（「AI 生成的语音有时会缺乏自然的呼吸停顿、情感起伏，或者带有轻微的机械感、背景杂音异常」）；多渠道核实是「最核心的一招」，「挂断后直接拨打对方常用且你熟悉的电话号码（不要回拨可疑来电号码），或者通过你们共同认识的第三人进行侧面核实」，口诀是「视频语音莫轻信，动作验证多核实」；换脸换声在法律上早已被禁止用于诈骗，人脸生成、人脸替换、合成人声、仿声这几类服务平台必须做显著标识，任何组织和个人不得恶意删除、篡改、伪造、隐匿标识——但守规矩的是平台，骗子不会加，所以「没看到 AI 标识」不能反过来当成对方是真人的证据；公安部刑侦局公布的一起案件里，14 人团伙被查获合成动态人脸视频 5 万多条、公民个人信息 50 多万条，扣押云服务器 60 台（全国，标识义务自 2025 年 9 月 1 日起）","grade":"B","src":"公安部网安局 (2025). 眼见≠为实，警惕 AI 新型诈骗！<http://gat.fujian.gov.cn/ztzl/fjjffpzxrx/spjq/202509/t20250922_7013008.htm>（福建省公安厅转载）；国家互联网信息办公室、工业和信息化部、公安部 (2022). 互联网信息服务深度合成管理规定（第六、十六、十七条，2023 年 1 月 10 日施行）. <https://www.gov.cn/zhengce/zhengceku/2022-12/12/content_5731431.htm>；国家互联网信息办公室、工业和信息化部、公安部、国家广播电视总局 (2025). 人工智能生成合成内容标识办法（第十条，2025 年 9 月 1 日施行）. <https://www.cac.gov.cn/2025-03/14/c_1743654684782215.htm>；公安部刑侦局、央视新闻 (2026). 警方查获 5 万多条合成动态人脸视频 谁在「复制」你的脸？<http://gat.fujian.gov.cn/ztzl/fjjffpzxrx/spjq/202603/t20260330_7117146.htm>（福建省公安厅转载）","note":"B 级原因是官方给的是识别口径和案例，没有「按这个方法核实后被骗率下降多少」的数字。回拨要用自己通讯录里存的旧号码，不要回拨来电显示的号码，也不要用对方在聊天里发来的新号码；对方以「信号不好」「在开会」为由拒绝当面视频或拒绝做指定动作的，直接当骗局处理。动作验证法只是辅助，模型一直在变好，唯一稳的是第三条核实。已经转了钱见本节第 2 条（立刻打 110 要求止付），防止人脸和声音被采集见第 14 节。公安部官网（mps.gov.cn）本次仍全站 521，公安部网安局与刑侦局的原文取自福建省公安厅转载页。","money":"0","time":"少","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"8.5","sec":8,"n":5,"title":"被指控或被传唤，先请律师，不私了、不删记录","cost":"律师费从几千元起；经济困难可以向法律援助机构申请免费律师；讯问时只回答与本案有关的问题，其余交给律师","human":"从第一次讯问或者被采取强制措施起，你就有权请律师；律师提出会见，看守所最迟 48 小时内安排，会见不被监听。与本案无关的问题有权不答，也没有人能强迫你证实自己有罪。一次传唤最长 12 小时（特别重大复杂的 24 小时），不得连着传唤变相关人。别私下接触对方，任何「私了」都可能被当成认罪；聊天记录、通话、行程是你自证的材料，删掉只会让自己少一份证据。","gain":"从第一次讯问或被采取强制措施起就有权委托律师，侦查阶段只能委托律师；律师提出会见，看守所最迟 48 小时内安排，会见不被监听；不得强迫任何人证实自己有罪，与本案无关的问题有权拒绝回答；传唤、拘传一次最长 12 小时，特别重大复杂的最长 24 小时，不得连续传唤变相拘禁；捏造事实诬告他人使其受刑事追究的，判 3 年以下，造成严重后果判 3 到 10 年；被拘留、逮捕后撤案、不起诉或判无罪的，可申请国家赔偿，每天按上年度全国职工日平均工资计算（全国）","grade":"A","src":"全国人大常委会 (2018). 刑事诉讼法（2018 年修正，第三十四、三十五、三十九、五十二、一百一十九、一百二十条）. <https://www.spp.gov.cn/zdgz/201810/t20181027_396818.shtml>；全国人大 (1997). 刑法（第二百四十三条）. <https://www.spp.gov.cn/spp/fl/201802/t20180206_364975.shtml>；全国人大常委会 (2012). 国家赔偿法（2012 年修正，第十七、三十三条）. <https://www.stats.gov.cn/gk/tjfg/xgfxfg/202503/t20250306_1958899.html>（国家统计局转载）","note":"不要私下接触对方或其家属，任何「私了」都可能被解读为承认；聊天记录、通话记录、行程记录是你自证的材料，删掉只会失去证据。诬告陷害罪不适用于错告或检举失实。本条对被指控者性别不做区分。展开的三条见本节第 31 条（追究捏造事实的一方）、第 32 条（证据不足应当判无罪与申诉再审）、第 33 条（羁押后的国家赔偿按天算）。","money":"多","time":"中","will":"些","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"一般"},{"id":"8.6","sec":8,"n":6,"title":"喝了酒就不碰方向盘，包括电动车和「挪一下车」","cost":"代驾或打车几十元；朋友聚会前说好谁不喝","human":"酒后驾车扣证 6 个月加罚一两千，再犯拘留并吊销；醉驾直接吊销、5 年内不得重考，还要按危险驾驶罪追刑责，留案底影响政审和部分职业。开营运车的更重：醉驾 10 年禁驾且终生不得再开营运车。商业车险对饮酒、吸毒后驾车一律不赔。「就挪一下车」也算驾驶。","gain":"酒后驾车暂扣驾驶证 6 个月并罚 1000 到 2000 元，再犯拘留 10 日以下并吊销；醉驾直接吊销驾驶证、5 年内不得重考，并按危险驾驶罪追究刑事责任（拘役并处罚金）；开营运车的酒驾拘留 15 日、罚 5000 元、5 年禁驾，醉驾 10 年禁驾且终生不得再开营运车；酒后或醉驾造成重大事故构成犯罪的终生禁驾；商业车险对饮酒、吸毒后驾车一律不赔（全国）","grade":"A","src":"全国人大常委会 (2021). 道路交通安全法（2021 年修订，第九十一条）. <https://jtgl.beijing.gov.cn/jgj/jgxx/flfg/fl/205308/index.html>（北京市公安交通管理局转载）；全国人大常委会 (2015). 刑法修正案（九）（第八条，即刑法第一百三十三条之一）. <https://www.spp.gov.cn/spp/fl/201802/t20180205_364562.shtml>；中国保险行业协会 (2020). 机动车商业保险示范条款（2020 版）（第九、二十二条）. <https://www.iachina.cn/art/2020/9/4/art_24_104621.html>","note":"醉驾是刑事犯罪，会留案底，影响本人政审和部分职业资格。「饮酒」和「醉酒」的血液酒精含量界线由国家标准规定，本节未核实具体数值，不要靠感觉估算。","money":"少","time":"少","will":"些","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"8.7","sec":8,"n":7,"title":"不把银行卡、手机卡、支付账号借给任何人，「跑分」不是兼职","cost":"0 元；拒绝「借卡走个账给你几百块」这类请求","human":"把银行卡、手机卡、支付账号租借卖给别人，这件事本身就违法：罚违法所得 1 到 10 倍，没有所得的最高罚 20 万元，情节严重的拘留 15 日，还会被记入信用记录、限制账户功能。要是明知对方拿去犯罪还提供支付结算帮助，就是帮信罪，判 3 年以下。实务里「明知」常按客观情况推定——收了好处费、交易量明显不正常，都可能算。","gain":"出租、出借、买卖电话卡、银行账户、支付账户、互联网账号本身就是违法，没收违法所得并罚 1 到 10 倍，没有所得的最高罚 20 万元，情节严重的拘留 15 日以下，还可能被记入信用记录、限制账户功能、停非柜面业务；明知他人用网络实施犯罪仍提供支付结算等帮助、情节严重的，构成帮助信息网络犯罪活动罪，判 3 年以下并处罚金（全国）","grade":"A","src":"全国人大常委会 (2022). 反电信网络诈骗法（第三十一、四十四条）. <https://www.spp.gov.cn/spp/fl/202209/t20220902_575631.shtml>；全国人大常委会 (2015). 刑法修正案（九）（第二十九条，即刑法第二百八十七条之二）. <https://www.spp.gov.cn/spp/fl/201802/t20180205_364562.shtml>","note":"「明知」在实务中常按客观情况推定，收了好处费、明显不合常理的交易量都可能被认定为明知。卡被别人用来收赃款，即使不构成犯罪，账户也会被冻结、本人被惩戒。","money":"0","time":"少","will":"否","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"极高"},{"id":"8.8","sec":8,"n":8,"title":"每年免费查两次自己的征信报告，看有没有不是自己办的贷款和卡","cost":"0 元；网上查十分钟","human":"法规给了你每年两次免费查自己信用报告的权利，网上十分钟。身份证被冒用去网贷、办卡，人往往是买房贷款被拒时才发现，那时已经拖了好几年。不良记录从行为终止起留 5 年，超过应当删除；有异议可以提，20 天内必须书面答复。查就用人民银行征信中心官网或手机银行，别用第三方「查征信」App——那类 App 本身就在收集你的信息。","gain":"行政法规规定「个人信息主体有权每年两次免费获取本人的信用报告」；不良信息「自不良行为或者事件终止之日起为 5 年；超过 5 年的，应当予以删除」；对报告有异议的可以提出，征信机构或信息提供者应当在收到异议之日起 20 日内书面答复","grade":"A","src":"国务院 (2013). 征信业管理条例（国令第 631 号，第十六条、第十七条、第二十五条）. <https://www.gov.cn/zhengce/zhengceku/2013-01/29/content_2303.htm>","note":"身份证被冒用去网贷、办卡，本人往往是买房贷款被拒时才发现，那时已经拖了几年。入口是中国人民银行征信中心官网或手机银行，别用第三方「查征信」App，那类 App 本身就在收集你的信息","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"8.9","sec":8,"n":9,"title":"起了冲突先报警不动手，先动手的那个几乎一定吃亏","cost":"0 元；忍住不还嘴不推搡，退到人多处报警，让对方的行为留在监控里","human":"打人拘留 5 到 10 日加罚五百到一千；结伙打、打老人孕妇孩子残疾人、多次打或一次打多人，拘留 10 到 15 日加罚一两千；打成轻伤就是刑事案件，判 3 年以下，重伤 3 到 10 年。互殴不算正当防卫——所以先动手的那个几乎一定吃亏。退到人多的地方报警、让对方的动作留在监控里，比还手管用。对方已经倒地或者跑了还追打，就不再算防卫。","gain":"殴打他人或故意伤害的，拘留 5 到 10 日并罚 500 到 1000 元；结伙、打老人孕妇儿童残疾人、多次打人或一次打多人的，拘留 10 到 15 日并罚 1000 到 2000 元；结伙斗殴按寻衅滋事最高拘留 15 日并罚 2000 元；故意伤害他人身体构成犯罪的判 3 年以下，致重伤 3 到 10 年；相互斗殴不算正当防卫，但对方先动手且手段明显过激、或你努力避免冲突对方仍继续侵害时，还击一般认定为防卫；防卫过当要同时满足「明显超过必要限度」和「造成重大损害」，即使过当也应减轻或免除处罚（全国，治安管理处罚法 2026 年 1 月 1 日起施行）","grade":"A","src":"全国人大常委会 (2025). 治安管理处罚法（2025 年修订，第三十、五十一条）. <https://www.spp.gov.cn/spp/fl/202506/t20250627_699863.shtml>；全国人大 (1997). 刑法（第二十、二百三十四条）. <https://www.spp.gov.cn/spp/fl/201802/t20180206_364975.shtml>；最高人民法院、最高人民检察院、公安部 (2020). 关于依法适用正当防卫制度的指导意见（法发〔2020〕31 号，第 6、9、11、14 条）. <https://www.court.gov.cn/zixun/xiangqing/251611.html>","note":"治安管理处罚法 2025 年修订后条款号全变，殴打他人由旧法第四十三条改为第五十一条，引用旧条号的资料已过时。「轻伤即入刑」的伤情标准由鉴定标准规定，本节未核实。对方已倒地或逃跑后再追打，不法侵害已结束，不再是防卫。","money":"0","time":"少","will":"些","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"8.10","sec":8,"n":10,"title":"跟谁结了怨——被欠薪、被开除、被坑了钱——走投诉、仲裁、起诉，别去找人算账","cost":"0 元；投诉和仲裁都不收费，跑一两趟、等几个月，难的是这几个月里忍住不动手","human":"法定路径最坏的结果是钱要不回来；报复的结果是钱照样要不回来，外加自己抵命。无锡那起案子：徐某金因为没拿到毕业证、又不满实习报酬，持刀行凶致 8 死 17 伤，判死刑并已执行——他不满的是学校和那笔钱，捅的是同学，钱一分没到手。欠薪走投诉和仲裁，2024 年全国靠这条给 65.4 万人追回了 86.5 亿元。","gain":"法定路径有官方数字：2024 年全国劳动监察查处 13.7 万件、为 65.4 万人追回工资 86.5 亿元，998 人因拒不支付劳动报酬罪获刑，怎么走见第 7 节第 2 条；报复路径的价目写在刑法第二百三十二条：「故意杀人的，处死刑、无期徒刑或者十年以上有期徒刑；情节较轻的，处三年以上十年以下有期徒刑」。官方案例：徐某金因考试不合格未拿到毕业证书以及对实习报酬不满，2024 年 11 月 16 日回无锡工艺职业技术学院持刀行凶，致 8 人死亡、17 人受伤，一审以故意杀人罪判处死刑、剥夺政治权利终身，2025 年 1 月 20 日经最高人民法院核准执行——他不满的是学校和那笔报酬，捅的是同学，那笔钱一分没到手（全国）","grade":"A","src":"全国人大 (1997). 刑法（第二百三十二条）. <https://www.spp.gov.cn/spp/fl/201802/t20180206_364975.shtml>；新华社 (2024). 江苏宜兴一校园发生持刀伤人事件致 8 死 17 伤. <http://www.news.cn/20241117/65a18fddb453469ebe91c78eda669893/c.html>（转宜兴警方通报，含伤亡人数与动机原话）；最高人民检察院 (2025). 无锡校园持刀伤人案罪犯徐加金被执行死刑. <https://www.spp.gov.cn/spp/zdgz/202501/t20250120_680197.shtml>；人力资源社会保障部 (2025). 2024 年度人力资源和社会保障事业发展统计公报. <https://www.mohrss.gov.cn/SYrlzyhshbzb/zwgk/szrs/tjgb/202506/W020250616518526345602.pdf>；最高人民法院 (2025). 最高人民法院工作报告（「对驾车冲撞行人的樊维秋、校园持刀行凶的徐加金等判处死刑」）. <https://www.gov.cn/yaowen/liebiao/202503/content_7013680.htm>","note":"在校生实习一般不认定劳动关系，实习报酬争议走学校协调或民事起诉，和劳动仲裁不是同一条路；被欠工资的具体走法见第 7 节第 2 条，讨债的红线见第 9 节第 15 条（要债不扣人、不关人）。法定路径最坏的结果是钱要不回来（结案不等于到账），报复的结果是钱照样要不回来，外加自己抵命。","money":"0","time":"中","will":"是","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"一般"},{"id":"8.11","sec":8,"n":11,"title":"再恨也别对不相干的人下手：驾车冲撞人群、在公共场所行凶按以危险方法危害公共安全定罪，起刑三年，死了人就是死刑","cost":"0 元","human":"驾车冲撞人群、在公共场所行凶，按以危险方法危害公共安全定罪：一个人都没伤着也是三年起；死了人就是十年以上、无期或者死刑。珠海那起：樊维秋不满离婚财产分割，开车冲进体育中心正在锻炼的人群，致 35 死 43 伤，判死刑并已执行——他不满的是离婚判决，撞的是不认识的跑步者。「反正我也不想活了」在量刑上不是折扣。连扬言都已经违法：扬言放火、爆炸扰乱公共秩序的，拘留 5 到 10 日并可罚款。","gain":"刑法第一百一十四条：「放火、决水、爆炸以及投放毒害性、放射性、传染病病原体等物质或者以其他危险方法危害公共安全，尚未造成严重后果的，处三年以上十年以下有期徒刑」——一个人没伤着也是三年起；第一百一十五条：致人重伤、死亡或者使公私财产遭受重大损失的，处十年以上有期徒刑、无期徒刑或者死刑。官方案例：樊维秋因婚姻破裂、生活失意且不满离婚财产分割结果，「决意通过驾车冲撞人群方式发泄私愤」，2024 年 11 月 11 日晚驾车冲入珠海市体育中心正在锻炼的人群，致 35 人死亡、43 人受伤，一审以以危险方法危害公共安全罪判处死刑、剥夺政治权利终身，2025 年 1 月 20 日经最高人民法院核准执行——他不满的是离婚判决，撞的是不认识的跑步者（全国）","grade":"A","src":"全国人大 (1997). 刑法（第一百一十四、一百一十五条）. <https://www.spp.gov.cn/spp/fl/201802/t20180206_364975.shtml>；新华社 (2024). 广东珠海驾车撞人事件造成 35 人死亡 43 人受伤. <http://www.news.cn/20241112/29c6af4f6ee4455b92832f3c2b13a93a/c.html>（转珠海市公安局通报）；最高人民检察院 (2024). 樊维秋以危险方法危害公共安全案一审宣判，判处死刑，剥夺政治权利终身. <https://www.spp.gov.cn/spp/zdgz/202412/t20241227_677757.shtml>；最高人民检察院 (2025). 珠海驾车撞人案罪犯樊维秋被执行死刑. <https://www.spp.gov.cn/spp/zdgz/202501/t20250120_680196.shtml>；全国人大常委会 (2025). 治安管理处罚法（2025 年修订，第二十九、五十条）. <https://www.spp.gov.cn/spp/fl/202506/t20250627_699863.shtml>","note":"「反正我也不想活了」在量刑上不是折扣，最高人民法院 2025 年工作报告对这类案件的口径是「对挑战法律和道德底线的罪大恶极者，坚决依法从严从重从快惩处」。扬言也已经违法：扬言实施放火、爆炸、投放危险物质等危害公共安全犯罪行为扰乱公共秩序的，拘留 5 到 10 日并可罚 1000 元以下；写恐吓信或者以其他方法威胁他人人身安全的，拘留 5 日以下或罚 1000 元以下（治安管理处罚法 2026 年 1 月 1 日起施行）。念头已经到这一步的，看下一条。","money":"0","time":"少","will":"些","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"8.12","sec":8,"n":12,"title":"冒出「拉个垫背的」「同归于尽」这种念头，当急症处理：离开现场，把车钥匙和刀交给别人，打 12356","cost":"0 元；难的是承认自己此刻不正常，以及把东西交到别人手上","human":"这类念头从冒出来到动手的窗口很短——82 名自杀未遂者里，47.6% 说从第一次起念到实施不超过 10 分钟。所以要做的不是「想通」，而是先把方向盘、刀、燃气阀、绳子和自己隔开一步，把这十分钟熬过去：管控镇痛药之后相关自杀降了 43%，跳楼热点装上防护后降了 86%。然后打 12356。状态不对的时候别开车、别值那种要替别人安全负责的班。","gain":"这类念头到动手的窗口很短——82 名自杀未遂者入院三天内的访谈里，47.6% 说从第一次冒出念头到实施不超过 10 分钟；10 年系统综述认为限制致死手段的证据持续增强，镇痛药管控相关自杀下降 43%，跳楼热点加防护后下降 86%（79% 到 91%）。把方向盘、刀、燃气阀、绳子隔开一步，等的就是这十分钟过去。12356 是全国统一心理援助热线，每日接听不少于 18 小时（全国，2025 年 5 月 1 日起）","grade":"B","src":"Deisenhammer EA 等 (2009). The duration of the suicidal process: how much time is left for intervention between consideration and accomplishment of a suicide attempt? Journal of Clinical Psychiatry. <https://doi.org/10.4088/JCP.07m03904>；Zalsman G 等 (2016). Suicide prevention strategies revisited: 10-year systematic review. Lancet Psychiatry. <https://doi.org/10.1016/S2215-0366(16)30030-X>；国家卫生健康委 (2024). 关于应用「12356」全国统一心理援助热线电话号码的通知（国卫医政函〔2024〕259 号）. <https://www.gov.cn/zhengce/zhengceku/202412/content_6994470.htm>","note":"B 级的原因是这两项证据都出自自杀研究，往「想伤害别人的冲动」上外推没有直接文献，Deisenhammer 那项还只有 82 人、单中心。状态不对的时候别开车、别值那种要替别人的安全负责的班，先交班再说。想伤害自己这一侧见第 1 节第 25 条（有自杀念头时打 12356），情绪低落时先做什么见第 3 节第 19 条。","money":"0","time":"少","will":"些","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"8.13","sec":8,"n":13,"title":"身边人说出「谁也别想好过」「带着孩子一起走」，别当气话：近亲属可以直接送诊，公安接到报警也必须管","cost":"挂号和诊查费几十到几百元；陪着跑一趟医院，半天到一天","human":"近亲属、单位和公安发现有人可能伤害自己或者危害他人，应当立即制止并送医；医院接到这样的送诊不得拒绝诊断，还要留院、立即指派精神科医生看并及时出结论。已经发生危害他人行为、或者有这种危险的严重精神障碍患者，住院不以本人同意为前提。这条针对的是真实的危险信号，不是吵架的气话，也不能拿来处理不听话的家人——诊断不成立的，医院不得留院。分不清就先打 12356，或者报 110 让警察到场。德翼 9525 那次的调查结论写得很直白：没有任何人——医生、同事、家属——把情况告诉过当局，机上 150 人全部遇难。替他瞒着不算帮他。","gain":"精神卫生法第二十八条第二款：「疑似精神障碍患者发生伤害自身、危害他人安全的行为，或者有伤害自身、危害他人安全的危险的，其近亲属、所在单位、当地公安机关应当立即采取措施予以制止，并将其送往医疗机构进行精神障碍诊断」，同条还规定「医疗机构接到送诊的疑似精神障碍患者，不得拒绝为其作出诊断」；第二十九条要求医院把这类送诊者留院、立即指派精神科执业医师诊断并及时出具结论；第三十条规定住院治疗以自愿为原则，但诊断结论表明是严重精神障碍患者且「已经发生危害他人安全的行为，或者有危害他人安全的危险的」，应当对其实施住院治疗——这一类不以本人同意为前提。扬言伤人本身可以直接报 110，罚则见上一条（全国）","grade":"A","src":"全国人大常委会 (2012，2018 修正). 精神卫生法（第二十八、二十九、三十、三十五条）. <https://www.gov.cn/guoqing/2021-10/29/content_5647635.htm>；法国航空事故调查局 BEA (2016). Final Report BEA2015-0125.en: Accident on 24 March 2015 at Prads-Haute-Bléone to the Airbus A320-211 registered D-AIPX operated by Germanwings. <https://bea.aero/uploads/tx_elydbrapports/BEA2015-0125.en-LR.pdf>","note":"按受益人口径，这条算的是同住的配偶、父母、子女——「谁也别想好过」里通常就包括你，而且法律把送诊权给的正是近亲属，外人想管也管不了，只能报警。这条针对的是真实的危险信号，不是吵架时的气话，更不是拿来把不听话的家人送进医院——同一部法律规定再次诊断或者鉴定不能确定为严重精神障碍患者的，医疗机构不得对其实施住院治疗（第三十五条）。分不清就先打 12356 问，或者报 110 让警察到场。德翼 9525 航班的调查结论是：当局和雇主无法采取任何措施阻止副驾驶当天飞行，因为「无论是他本人，还是任何其他人——医生、同事或者家属——都没有告知他们」，机上 150 人（2 名飞行员、4 名乘务员、144 名乘客）全部遇难。替他瞒着不算帮他。","money":"少","time":"中","will":"些","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"一般"},{"id":"8.14","sec":8,"n":14,"title":"网上不骂人、不造谣、不转发没核实的事；被网暴先留证再报警","cost":"0 元；发之前多想十秒；被攻击时截图、录屏、保存链接和账号 ID，向平台投诉，再报警","human":"公开骂人或者造谣诽谤，拘留 5 日以下或罚 1000 元以下，情节较重的拘留 5 到 10 日；散布谣言扰乱公共秩序拘留 5 到 10 日；情节严重就构成侮辱罪、诽谤罪，判 3 年以下。转发不免责，明知是假还散布同样算。反过来，你被网暴时要知道：侮辱诽谤原则上「告诉才处理」，公安一般不主动立案，得自己去法院起诉——所以截图、录屏、存链接和账号 ID 只能靠你自己。","gain":"公然侮辱或捏造事实诽谤他人的，拘留 5 日以下或罚 1000 元以下，情节较重拘留 5 到 10 日；多次发送侮辱恐吓信息、滋扰纠缠跟踪、偷拍散布隐私同罚；故意散布谣言扰乱公共秩序的拘留 5 到 10 日；情节严重的构成侮辱罪、诽谤罪，判 3 年以下，通过网络诽谤的，受害人取证困难可请法院要求公安协助（全国，治安管理处罚法 2026 年 1 月 1 日起施行）","grade":"A","src":"全国人大常委会 (2025). 治安管理处罚法（2025 年修订，第二十九、五十条）. <https://www.spp.gov.cn/spp/fl/202506/t20250627_699863.shtml>；全国人大 (1997). 刑法（第二百四十六条）. <https://www.spp.gov.cn/spp/fl/201802/t20180206_364975.shtml>；全国人大常委会 (2015). 刑法修正案（九）（第十六条，增加刑法第二百四十六条第三款）. <https://www.spp.gov.cn/spp/fl/201802/t20180205_364562.shtml>；全国人大常委会 (2015). 刑法修正案（九）（第二百四十六条新增第三款）. 国家信访局转载全文 <https://www.gjxfj.gov.cn/gjxfj/fgwj/flfg/webinfo/2017/03/1601761496614423.htm>","note":"侮辱、诽谤罪原则上「告诉的才处理」，即要自己去法院起诉，公安一般不主动立案，所以证据只能靠自己留；但有两个口子别漏掉：「严重危害社会秩序和国家利益的除外」，这种公安可以直接办（刑法第二百四十六条第二款），以及通过信息网络诽谤、被害人举证确有困难的，法院可以要求公安机关提供协助（同条第三款，刑法修正案九新增）。转发不等于免责，「捏造事实」包括明知是假仍散布。自己被网暴之后怎么处置见本节第 35 条。侮辱诽谤由旧法第四十二条改为新法第五十条。","money":"0","time":"少","will":"些","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"8.15","sec":8,"n":15,"title":"签字前把纸看完，不替人签字，不在空白纸上签","cost":"0 元；多花几分钟把合同、借条、担保书、入职文件从头读到尾，看不懂的当场问、拍照留底","human":"签了就算数，「没看清」「以为是别的」在法庭上基本站不住。所以多花几分钟从头读到尾，看不懂的当场问、拍照留底；不替别人签，不在空白纸上签，身份证复印件写清用途。电子签和人脸识别确认同样算签字。","gain":"依法成立的合同受法律保护、对当事人有约束力，签了就要按约定全面履行，「没看清」「以为是别的」在法庭上很难成立；不签就不会背上不属于自己的债务和责任（全国）","grade":"A","src":"全国人大 (2020). 民法典（第四百六十五、五百零九条）. <https://www.spp.gov.cn/spp/fl/202006/t20200602_463888.shtml>","note":"「不替人签字、不签空白纸、身份证复印件加注用途」是经验做法，没有单独的官方文件，但目的都是避免被伪造成一份「依法成立的合同」。电子签、人脸识别确认同样算签字。","money":"0","time":"少","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"8.16","sec":8,"n":16,"title":"借钱写清借条，替人担保前先想清楚自己愿不愿意替他还","cost":"0 元；一张纸写清出借人、借款人、金额、利率、期限、还款方式，双方签名；转账留痕，不给现金","human":"借条要写全出借人、借款人、金额、利率、期限、还款方式，双方签名，钱走转账不给现金——写全了才好起诉。替人担保时看清「连带」两个字：一般保证是等债权人先告了借款人、执行不到钱才轮到你；写了连带责任保证，债权人可以直接找你要。签之前先问自己一句：愿不愿意替他还。","gain":"借款合同应当采用书面形式，内容一般包括借款种类、币种、用途、数额、利率、期限和还款方式，写全了才好起诉；担保合同没有约定保证方式或约定不明的，按一般保证承担责任，一般保证人在债权人先起诉或仲裁并强制执行债务人财产仍不能清偿之前有权拒绝代偿；反过来，签了「连带责任保证」就没有这层保护，债权人可以直接找你（全国）","grade":"A","src":"全国人大 (2020). 民法典（第六百六十八、六百八十一、六百八十六、六百八十七条）. <https://www.spp.gov.cn/spp/fl/202006/t20200602_463888.shtml>","note":"借出去的钱利息超过 4 倍 LPR 的部分法院不保护，见第 7 节。借条上写身份证号、注明「借款」是经验做法。担保书上的「连带」两个字决定你是第二顺位还是和借款人并排，签前务必看清。","money":"0","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"极高"},{"id":"8.17","sec":8,"n":17,"title":"维权有期限：民事诉讼时效 3 年，劳动仲裁 1 年，过了对方一句「超过时效」就够","cost":"0 元；催款别只在心里催，用微信、短信、邮件或者挂号信留下痕迹","human":"这大概是全书最便宜的一条。民事诉讼时效 3 年，从你知道权利受损那天算起；过了期法院不主动管，但对方一句「超过时效」就够——钱还在，只是要不回来了。而一条留了痕迹的催款消息（微信、短信、挂号信）就能让这 3 年从头重算。劳动争议是另一套：仲裁时效 1 年，在职期间被拖欠工资不受这一年限制，但劳动关系一终止，就得在一年内提出。","gain":"民法典规定「向人民法院请求保护民事权利的诉讼时效期间为三年」，从「权利人知道或者应当知道权利受到损害以及义务人之日起计算」，最长自权利受到损害之日起 20 年。期间届满的，「义务人可以提出不履行义务的抗辩」——法院不主动适用时效，但对方一提就有效，钱还在、只是要不回来。中断事由有四种，一中断就从头重新计算 3 年：权利人向义务人提出履行请求、义务人同意履行义务、权利人提起诉讼或者申请仲裁、与之具有同等效力的其他情形。约定分期履行的，从最后一期履行期限届满之日起算。四类请求权不适用时效：请求停止侵害、排除妨碍、消除危险；不动产物权和已登记动产物权的返还；抚养费、赡养费、扶养费；法律规定的其他。劳动争议是另一套：仲裁时效 1 年，从知道或者应当知道权利被侵害之日起算，但「劳动关系存续期间因拖欠劳动报酬发生争议的，劳动者申请仲裁不受本条第一款规定的仲裁时效期间的限制；但是，劳动关系终止的，应当自劳动关系终止之日起一年内提出」（全国）","grade":"A","src":"全国人大 (2020). 民法典（第一百八十八、一百八十九、一百九十二、一百九十三、一百九十五、一百九十六、一百九十七条）. <https://www.spp.gov.cn/spp/fl/202006/t20200602_463888.shtml>；全国人大常委会 (2007). 劳动争议调解仲裁法（第二十七条）. <https://rsj.ankang.gov.cn/Content-2150407.html>（安康市人力资源和社会保障局转载）","note":"这大概是全书最便宜的一条：一条留了痕迹的催款消息就能把 3 年重新起算，什么都不做就可能白白丧失胜诉权。预先放弃时效利益无效，双方约定改变时效期间也无效。反过来，对方在时效届满后同意履行的不得再以时效抗辩，已经自愿履行的不得请求返还。借条和担保见第 16 条，被执行阶段见第 18 条；加班费和未休年休假工资走劳动仲裁那一套，见第 19 节第 1、2 条。","money":"0","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"极高"},{"id":"8.18","sec":8,"n":18,"title":"被起诉、被执行了，如实报财产、能还多少还多少，别把房和钱转给亲友或公司","cost":"0 元；按法院的要求报告当前以及收到执行通知之日前一年的财产，能还的先还，还不上就和申请执行人谈和解、谈分期","human":"把房子挂到公司名下、把钱转给亲友，不是什么「操作」，正好落在拒执罪列举的情形里：拒执罪判 3 年以下，情节特别严重的 3 到 7 年；帮着藏钱过户的亲友和公司按共犯算，财产该追缴的照样追缴。拒绝报告或者虚报财产，个人可罚 10 万元以下、拘留 15 日。反过来，真没钱不构成这个罪——认定「有能力执行」要先扣掉本人和被扶养家属的生活必需费用；起诉前履行了义务且情节轻微的可以不起诉，一审宣判前履行的可以从轻或者免罚。","gain":"转移财产不是「操作」，它本身就是入罪的情形：全国人大常委会对刑法第三百一十三条的解释，把「被执行人隐藏、转移、故意毁损财产或者无偿转让财产、以明显不合理的低价转让财产，致使判决、裁定无法执行」直接列为「有能力执行而拒不执行，情节严重」；两高 2024 年的解释又补了十项，包括以虚假和解、虚假转让等方式处分财产权益，以及以明显不合理的高价受让他人财产、为他人的债务提供担保这类恶意减损责任财产的行为。拒执罪判 3 年以下，情节特别严重的（虚假诉讼、虚假仲裁、虚假公证妨害执行，聚众冲击执行现场，围攻扣押殴打执行人员，因拒不执行致使申请执行人自杀自残）判 3 到 7 年并处罚金；案外人明知而与其通谋、帮着藏钱过户的，按拒执罪的共犯论处；被违法处置的财产应当依法追缴或者责令退赔；在被告收到应诉通知之后、判决生效之前就动手转移的，同样算。民事这一侧，无偿转让和明显不合理低价转让，债权人可以请求法院撤销；拒绝报告或者虚假报告财产，法院可以罚款（对个人 10 万元以下）、拘留（15 日以下）（全国，两高解释 2024 年 12 月起）","grade":"A","src":"全国人大常委会 (2002). 关于《中华人民共和国刑法》第三百一十三条的解释. <https://www.gov.cn/gongbao/content/2002/content_61738.htm>；最高人民法院、最高人民检察院 (2024). 关于办理拒不执行判决、裁定刑事案件适用法律若干问题的解释（法释〔2024〕13 号，第三、四、五、六、八、十一、十二条）. 最高法发布页，全文核对自广东省广州监狱转载. <https://www.court.gov.cn/fabu/xiangqing/447931.html>、<http://gzjy.gd.gov.cn/zxxx/content/post_4608108.html>；全国人大常委会 (2015). 刑法修正案（九）（第三十九条，修改刑法第三百一十三条）. <https://www.spp.gov.cn/spp/fl/201802/t20180205_364562.shtml>；全国人大 (2020). 民法典（第五百三十八、五百三十九、五百四十条）. <https://www.spp.gov.cn/spp/fl/202006/t20200602_463888.shtml>；全国人大常委会 (2023 修正). 民事诉讼法（第一百一十四、一百一十八、二百五十二条）. 贵州省市场监管局转载：<https://amr.guizhou.gov.cn/zwgk/xxgkml/jcxxgk/zcfg/fl/202401/t20240129_83645867.html>","note":"网上流传的「把房子挂到公司名下当员工宿舍、钱全转给亲属」不是漏洞，正好落在解释列举的无偿处分和虚假转让里，帮着操作的亲友和公司按共犯算，财产该追缴的照样追缴。反过来，真没钱不构成这个罪：认定「有能力执行」要扣除本人及所扶养家属的生活必需费用；提起公诉前履行全部或者部分义务且情节轻微的可以不起诉，一审宣判前履行的可以从轻或者免除处罚。被列入名单、被限制消费之后怎么办见下一条，履行完之后怎么恢复见第 7 节第 20 条。","money":"0","time":"中","will":"些","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"8.19","sec":8,"n":19,"title":"被限制消费或者被列入失信名单，先查清是按哪一条纳入的，能纠正的申请纠正","cost":"0 元；去执行法院查按哪一项纳入，准备履行凭证或者担保材料；生活、经营必需的那笔消费要一次一申请","human":"先弄清自己是被限制消费还是被列入失信名单——这是两件事，可能只中一样，而且都不等于征信记录。失信名单只有六种情形能纳入，期限 2 年；已经履行完毕等七种情形，法院应当在 3 个工作日内删除，积极履行的还能提前删。限高禁的是拿被执行人的钱做八类消费（飞机、软卧、星级宾馆、买房、旅游、子女读高收费私立学校等）；因为生活或者经营必需要做其中一项，可以一次一申请；提供确实有效的担保或者申请执行人同意，法院可以解除。","gain":"纳入失信名单只有六种情形——有履行能力而拒不履行、以伪造证据或者暴力威胁妨碍抗拒执行、以虚假诉讼虚假仲裁或者隐匿转移财产规避执行、违反财产报告制度、违反限制消费令、无正当理由拒不履行执行和解协议；提供了充分有效担保或者已被查封扣押冻结的财产足以清偿的，法院不得按第一项纳入，被执行人是未成年人的不得纳入。纳入期限 2 年，以暴力威胁妨碍抗拒执行情节严重或者有多项失信行为的可延长 1 到 3 年；已履行完毕、和解协议已履行完毕、法院裁定终结执行等七种情形，法院应当在 3 个工作日内删除，积极履行或者主动纠正失信行为的还可以提前删除。限制消费令禁止的是用自己的财产做八类消费：坐飞机、列车软卧、轮船二等以上舱位，在星级以上宾馆酒店夜总会高尔夫球场高消费，买不动产或者新建扩建高档装修房屋，租高档写字楼宾馆公寓办公，买非经营必需车辆，旅游度假，子女就读高收费私立学校，支付高额保费买保险理财产品；因生活或者经营必需要做其中一项的，应当向法院申请，获批准才能做；提供确实有效担保或者经申请执行人同意的，法院可以解除限高（全国）","grade":"A","src":"最高人民法院 (2017 修正). 关于公布失信被执行人名单信息的若干规定（第一、二、三、四、十条）. <https://www.court.gov.cn/fabu/xiangqing/37182.html>；最高人民法院 (2010). 关于限制被执行人高消费的若干规定（第三、八、九条）. <https://www.court.gov.cn/shenpan/xiangqing/1650.html>","note":"限高规定 2015 年经法释〔2015〕17 号修改，名称改为《……及有关消费的若干规定》，本条按最高法官网能逐字核对的 2010 年文本引用，修改后文本 TODO（待核实：最高法公报页在本机返回 502）。失信名单和限制消费是两件事，可能只中一样；两者也都不等于征信记录，删除名单不改征信，见第 7 节第 20 条。限制的是花被执行人的钱，配偶、子女花自己的钱不在此列，但用被执行人的钱供子女读高收费私立学校在禁止之列。","money":"0","time":"中","will":"些","level":"中","lens":"金钱","dispute":false,"todo":true,"ratio":"一般"},{"id":"8.20","sec":8,"n":20,"title":"网购、二手交易被骗，先平台投诉，再报警，再算值不值得起诉","cost":"平台投诉和报警 0 元；起诉标的 1 万元以内受理费 50 元，简易程序、调解或撤诉再减半；立案、开庭、执行至少各占半天到一天，网上立案可省跑腿；保存订单、聊天记录、转账记录、物流单","human":"先找平台——平台有保证金和处罚规则，处理最快；再报警，被骗 3000 元以上就够诈骗罪的立案线（各省在 3000 到 1 万元之间定各自的标准），不够刑事标准的按治安处罚，拘留 5 到 10 日。要打官司的话，网购纠纷可以在收货地法院起诉，不必跑到卖家所在地；金额小的走小额诉讼，一审终审、2 个月内审结，网上就能立案开庭。值不值得打，用自己的税后时薪乘以预计耗时，加上受理费，跟标的额比一比。","gain":"诈骗 3000 元至 1 万元以上（各省在此幅度内定本地标准）构成诈骗罪「数额较大」，判 3 年以下并处或单处罚金；不够刑事标准的按治安管理处罚，拘留 5 到 10 日或罚 2000 元以下，情节较重拘留 10 到 15 日并可罚 3000 元以下；民事上，网购合同纠纷可在收货地法院起诉，不必去卖家所在地；标的额在本省上年度就业人员年平均工资 50% 以下的适用小额诉讼，一审终审，立案后 2 个月内审结，简易程序 3 个月；民事诉讼可经信息网络平台在线进行，与线下同等效力（全国，民诉法 2024 年 1 月起，治安管理处罚法 2026 年 1 月起）","grade":"A","src":"最高人民法院、最高人民检察院 (2011). 关于办理诈骗刑事案件具体应用法律若干问题的解释（法释〔2011〕7 号，第一条）. <https://www.spp.gov.cn/spp/sfjs/201802/t20180201_363736.shtml>；全国人大 (1997). 刑法（第二百六十六条）. <https://www.spp.gov.cn/spp/fl/201802/t20180206_364975.shtml>；全国人大常委会 (2025). 治安管理处罚法（2025 年修订，第五十八条）. <https://www.spp.gov.cn/spp/fl/202506/t20250627_699863.shtml>；全国人大常委会 (2023 修正). 民事诉讼法（第十六、一百六十四、一百六十五、一百六十八条）. <https://fgw.sh.gov.cn/ys-syjf-zc-2.4.1-h5/20240408/073febdb2b04464390546232d4089f51.html>（上海市发展改革委转载）；最高人民法院 (2022 修正). 关于适用《民事诉讼法》的解释（第二十条）. <https://www.court.gov.cn/zixun/xiangqing/353651.html>；国务院 (2006). 诉讼费用交纳办法（国务院令第 481 号，第十三、十五、十六条）. <https://www.gov.cn/zhengce/zhengceku/2008-03/28/content_6929.htm>","note":"值不值的算法：用自己的税后时薪 × 预计耗时（立案、开庭、可能的执行，各按半天到一天算）+ 受理费，和标的额比，再打个折扣估胜诉后能否执行到钱；只给方法不给结论。治安管理处罚法 2025 年修订后条号全变，盗窃诈骗由旧法第四十九条改为第五十八条；民诉法 2023 年修正后小额诉讼在第一百六十五条，两者都别抄旧资料。「平台投诉优先」是经验：平台有保证金和处罚规则，处理最快。法释〔2011〕7 号在检察院官网页面未标文号，文号待与最高法原文页核对。","money":"少","time":"中","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"8.21","sec":8,"n":21,"title":"恋爱和婚内的大额赠与，交付之前想清楚，交付之后原则上要不回","cost":"0 元；大额转账前想一下这是借还是送，是借就写借条、备注「借款」","human":"钱一交出去，原则上就要不回来了：赠与只有在财产权利转移之前才能随便撤销，转移之后只有对方严重侵害你或你的近亲属、不履行扶养义务、不履行约定义务这三种情形才撤得掉。所以大额转账之前先想清楚这是借还是送——是借就写借条、转账备注「借款」，聊天记录里的一句「这钱我先借你」，比事后争论有用得多。","gain":"赠与在财产权利转移之前可以撤销，转移之后只有受赠人严重侵害赠与人或其近亲属、不履行扶养义务、不履行赠与合同约定义务三种情形才能撤销；节日、生日等有纪念意义时点给的价值不大的礼物礼金、为表达或增进感情的日常消费支出，不属于彩礼，分手时不按彩礼返还（全国）","grade":"A","src":"全国人大 (2020). 民法典（第六百五十八、六百六十三条）. <https://www.spp.gov.cn/spp/fl/202006/t20200602_463888.shtml>；最高人民法院 (2024). 关于审理涉彩礼纠纷案件适用法律若干问题的规定（法释〔2024〕1 号，第三条）. <https://www.court.gov.cn/fabu/xiangqing/423442.html>","note":"「520、1314 这类特殊数额通常认定为赠与」是实务中常见说法，本节未找到最高法官方原文，不作为结论。经过公证的赠与不能任意撤销。转账性质是借还是赠，最终看证据，聊天记录里的一句「这钱我先借你」比事后争论有用得多。","money":"0","time":"少","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"8.22","sec":8,"n":22,"title":"彩礼走转账并备注，聊天记录留好；借婚姻要钱可以要回","cost":"0 元；彩礼、三金、改口费走转账并备注用途，口头约定用聊天记录或家人在场确认","human":"借婚姻索取财物是法律禁止的，法院支持返还。没登记的、登记了但确实没共同生活的、婚前给付导致给付人生活困难的，可以要求返还；已登记又共同生活的一般不返还，但共同生活时间短、彩礼数额又过高的，法院会按实际怎么花的、有没有嫁妆、有没有孕育、双方过错来定返还比例。所以彩礼、三金、改口费都走转账并备注用途——谁给的钱谁留证据，男女一样。","gain":"禁止借婚姻索取财物，一方以彩礼为名借婚姻索取财物的，另一方要求返还法院支持；没办结婚登记、办了登记但确未共同生活、婚前给付导致给付人生活困难的，可以要求返还；已登记且共同生活的一般不返还，但共同生活时间短且彩礼数额过高的，法院按实际使用、嫁妆、孕育、双方过错等确定返还比例；没登记但已同居的同样按比例处理（全国，2024 年 2 月起）","grade":"A","src":"全国人大 (2020). 民法典（第一千零四十二条）. <https://www.spp.gov.cn/spp/fl/202006/t20200602_463888.shtml>；最高人民法院 (2024). 关于审理涉彩礼纠纷案件适用法律若干问题的规定（法释〔2024〕1 号，第二、五、六条）. <https://www.court.gov.cn/fabu/xiangqing/423442.html>；最高人民法院 (2020). 关于适用《民法典》婚姻家庭编的解释（一）（法释〔2020〕22 号，第五条）. <https://www.court.gov.cn/fabu/xiangqing/282071.html>","note":"「数额过高」按给付方所在地人均可支配收入和家庭情况判断，没有全国统一数字；返还比例由法官个案裁量。本条对给付方和接收方一视同仁，谁给的钱谁留证据。","money":"0","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"极高"},{"id":"8.23","sec":8,"n":23,"title":"婚前财产不用怕，房子加名和父母出资先写清楚","cost":"书面财产协议 0 元，公证另收费；父母出资时一句书面说明；一次性几小时","human":"婚前的财产是你个人的，不会因为结婚年头长就变成共同财产。夫妻可以书面约定婚前婚后的财产各归各的，这个约定对双方都有约束力。婚前父母出资买房算给自己孩子的，除非明确说是给两个人；婚后出资没约定的按共同财产处理。要留意一点：说好把房子加对方的名，在变更登记之前还能反悔，登记完就是对方的了。离婚时藏钱、转移、挥霍或者伪造债务的一方，可以少分或者不分。","gain":"婚前财产是个人财产，不因结婚年头长而变成共同财产；夫妻可以书面约定婚前财产和婚后所得归各自、共同或部分共同，约定对双方有约束力；婚前父母出资购房视为对自己子女的赠与，除非明确表示给双方；婚后父母出资按约定处理，没有约定的按共同财产原则处理；婚前或婚内约定把一方房产赠与另一方或共有的，变更登记之前赠与方可以撤销，登记之后就是对方的；离婚时隐藏、转移、变卖、挥霍共同财产或伪造债务的一方可以少分或不分（全国）","grade":"A","src":"全国人大 (2020). 民法典（第一千零六十三、一千零六十五、一千零九十二条）. <https://www.spp.gov.cn/spp/fl/202006/t20200602_463888.shtml>；最高人民法院 (2020). 关于适用《民法典》婚姻家庭编的解释（一）（法释〔2020〕22 号，第二十九、三十一、三十二条）. <https://www.court.gov.cn/fabu/xiangqing/282071.html>","note":"财产协议对男女双方同样有效，不是某一方的「防身术」。协议对夫妻一方对外债务的效力以债权人知道该约定为前提。公证不是协议生效的条件，但能减少事后对签名和时间的争议。","money":"少","time":"中","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"8.24","sec":8,"n":24,"title":"结婚前核对对方婚姻状况，以结婚为幌子骗钱的按诈骗罪追究","cost":"0 元；登记前看对方身份证、户口簿上的婚姻状况，大额财物往来留转账和聊天记录","human":"重婚的婚姻无效；有配偶还去结婚、或者明知对方有配偶还跟他结婚的，判 2 年以下。以结婚为幌子骗钱的按诈骗罪追究：数额较大判 3 年以下，巨大 3 到 10 年，特别巨大 10 年以上或者无期。登记前看一眼对方身份证和户口簿上的婚姻状况，大额财物往来留转账和聊天记录。被骗的不分男女，骗彩礼和骗嫁妆的案子都有。","gain":"重婚的婚姻无效；有配偶而重婚、或明知对方有配偶仍与之结婚的，判 2 年以下；诈骗公私财物数额较大判 3 年以下并处罚金，数额巨大 3 到 10 年，数额特别巨大 10 年以上或无期，并处罚金或没收财产（全国）","grade":"A","src":"全国人大 (2020). 民法典（第一千零五十一条）. <https://www.spp.gov.cn/spp/fl/202006/t20200602_463888.shtml>；全国人大 (1997). 刑法（第二百五十八、二百六十六条）. <https://www.spp.gov.cn/spp/fl/201802/t20180206_364975.shtml>","note":"「骗婚」不是独立罪名，能否按诈骗罪处理看是否以非法占有为目的、用虚构事实骗取财物，需要公安立案侦查。「数额较大」的具体金额由司法解释规定并可按地区调整，本节未核实。骗婚的受害者不分性别，男女都有被骗彩礼和被骗嫁妆的案例。","money":"0","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"极高"},{"id":"8.25","sec":8,"n":25,"title":"上门维修、验车、装修，先问价再动手，全程在旁边看着","cost":"0 元；动手前问清收费标准和要换的件，报价拍照或让对方发文字，修完要维修凭证和发票，旧件留下；站在旁边看一两个小时","human":"家电维修必须明示收费标准、给维修凭证和发票，不得虚列夸大维修项目、不得虚报故障部件或者故意换掉性能正常的零件，情节严重罚 3 万元以下；所有经营者都必须明码标价，不得在标价之外加价、不得收未予标明的费用。所以动手前问清价钱和要换的件（让对方发文字或者拍照），修完要凭证和发票、把旧件留下，全程在旁边看着。被多收了先打 12315，处罚由市场监管部门做，不用自己打官司。","gain":"家电维修经营者须明示服务项目和配件的收费标准、质量规范、质保期限、投诉电话，须向消费者提供维修服务凭证和收费发票并如实填写维修项目和详情，不得虚列、夸大、伪造维修项目，不得虚报故障部件、故意替换性能正常的部件，情节严重的处 3 万元以下罚款；所有经营者须明码标价，不得在标价之外加价、不得收取任何未予标明的费用，低价诱骗高价结算、虚假折价属价格欺诈；经营者须以显著方式标明服务的项目、内容、价格和计价方法，不得作虚假或引人误解的宣传（全国）","grade":"B","src":"商务部 (2012). 家电维修服务业管理办法（商务部令 2012 年第 7 号，第五、七、九、十四条）. <http://www.gov.cn/gongbao/content/2012/content_2231695.htm>；市场监管总局 (2022). 明码标价和禁止价格欺诈规定（市场监管总局令第 56 号，第五、八、十九条）. <http://www.gov.cn/gongbao/content/2022/content_5699926.htm>；国务院 (2024). 消费者权益保护法实施条例（国务院令第 778 号，第九、十条）. <https://www.gov.cn/zhengce/zhengceku/202403/content_6940159.htm>","note":"B 级原因是规则是官方的，「在旁边看着能少花多少」没有数字，主要是经验。警惕不等于以貌取人，看的是流程不是人：问价、留凭证、留旧件，对谁都一样做。家电办法只管家电维修，验车、装修参照明码标价规定和实施条例；消费者权益保护法本身（第八、十条知情权和公平交易权）的官方原文页未能打开，TODO（待核实），暂以实施条例替代。被多收了先打 12315，处罚由商务、市场监管部门做，不用自己打官司。","money":"0","time":"少","will":"些","level":"中","lens":"金钱","dispute":false,"todo":true,"ratio":"一般"},{"id":"8.26","sec":8,"n":26,"title":"别当「挂名法人」，别把身份证借给人注册公司","cost":"0 元；拒绝「挂个名不用管事」的请求","human":"法律预设法定代表人就是那个管事的人，「我只是挂个名、什么都不知道」不是免责事由。法定代表人执行职务给别人造成损害，公司先赔，赔完可以回头找有过错的你追偿；董事高管有故意或者重大过失的，自己也要赔。已经挂了名的，公司法允许辞任，公司须在 30 日内确定新的法定代表人。","gain":"法定代表人由实际执行公司事务的董事或经理担任，法律预设你就是管事的人；法定代表人执行职务造成他人损害的公司先赔，赔完可以向有过错的法定代表人追偿；董事、高管对公司负忠实和勤勉义务，执行职务给他人造成损害且有故意或重大过失的，本人也要承担赔偿责任；「不知情」在法律上不是免责事由（全国，2024 年 7 月起）","grade":"B","src":"全国人大常委会 (2023). 公司法（2023 年修订，第十、十一、一百八十、一百九十一条）. <https://www.gov.cn/yaowen/liebiao/202312/content_6923395.htm>","note":"公司法原文只给出责任原则，挂名法人在实务中更常见的后果（公司被执行时法定代表人被限制高消费、税务和行政处罚牵连）出自其他法律和执行规定，本节未核实原文，故定 B 级。已经挂名的，公司法允许辞任，公司须在 30 日内确定新的法定代表人。","money":"0","time":"少","will":"否","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"极高"},{"id":"8.27","sec":8,"n":27,"title":"出入境不帮陌生人带东西，不代收来路不明的包裹","cost":"0 元；拒绝就行","human":"外交部领事司给出国公民的建议是：务必不要替别人携带行李物品，特别是违禁品或者你并不了解的东西。行李里真查出毒品或走私品，「我不知道里面装的什么」要你自己举证。国内代收快递同理，尤其是让你先垫钱再退款的。","gain":"外交部领事司给出国公民的建议是「请务必避免为他人携带行李物品，特别是违禁物品或不了解的物品」，目的是避免在不知情中替人携带违禁品而承担法律责任；行李里查出毒品或走私品时，「不知道里面是什么」需要你自己举证","grade":"B","src":"外交部领事司 (2023). 对准备出国的中国公民有哪些建议. <https://cs.mfa.gov.cn/gyls/lscs/201106/t20110615_876383.shtml>","note":"海关总署和公安部关于此事的官方提示页面未能打开，本条只引外交部领事司页面，且原文只给原则不给法条，故定 B 级。国内代收快递同理，尤其是让你先垫付再退款的。","money":"0","time":"少","will":"否","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"极高"},{"id":"8.28","sec":8,"n":28,"title":"养狗必须牵绳：不牵绳出了事是无过错责任，赔到底","cost":"一根绳几十元；难的是每次都牵","human":"狗伤了人，原则上不管你有没有过错都要赔，只有能证明是对方故意或者重大过失才可能减免；而如果你违反规定没牵绳，就只剩「被侵权人故意」这一条能减轻——不牵绳等于把唯一的退路也堵死。禁养的烈性犬伤人则没有任何免责事由。一次赔偿含医疗费、误工费、狂犬疫苗和免疫球蛋白，上万很常见。丢弃不管也不脱责：遗弃、逃逸期间伤人，还算原饲养人的。","gain":"饲养的动物造成他人损害，饲养人或者管理人应当承担侵权责任，只有能证明损害是被侵权人故意或者重大过失造成的才可以减免；而违反管理规定未采取安全措施的，只有「被侵权人故意」才能减轻——不牵绳等于把这条唯一的减责通道也堵死；禁止饲养的烈性犬伤人则没有任何免责事由","grade":"A","src":"全国人大 (2020). 民法典. 最高人民检察院转载全文. <https://www.spp.gov.cn/spp/fl/202006/t20200602_463888.shtml> 第一千二百四十五条：「饲养的动物造成他人损害的，动物饲养人或者管理人应当承担侵权责任；但是，能够证明损害是因被侵权人故意或者重大过失造成的，可以不承担或者减轻责任。」第一千二百四十六条：「违反管理规定，未对动物采取安全措施造成他人损害的，动物饲养人或者管理人应当承担侵权责任；但是，能够证明损害是因被侵权人故意造成的，可以减轻责任。」第一千二百四十七条：「禁止饲养的烈性犬等危险动物造成他人损害的，动物饲养人或者管理人应当承担侵权责任。」第一千二百四十九条：遗弃、逃逸的动物在此期间造成损害，由原饲养人或者管理人承担责任","note":"狗咬人的赔偿包含医疗费、误工费、狂犬疫苗和免疫球蛋白，一次上万很常见，重伤或者伤到小孩的量级还要高。丢弃不管也不脱责：遗弃、逃逸期间伤人仍然算原饲养人的。被咬之后怎么处置见第 13 节。","money":"0","time":"少","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"8.29","sec":8,"n":29,"title":"对方喝到意识不清、睡着，或者可能不满 14 岁，就不要发生关系","cost":"0，代价是当时把事情停下来","human":"法条写的是「以暴力、胁迫或者其他手段」，不是只有动手才算。对方喝到意识不清、睡着、被下了药，或者可能不满 14 周岁，这几种情形事后你几乎无法证明「当时是同意的」——法律上她本来也没有能力表示同意。基本刑是 3 年以上 10 年以下，对不满 14 周岁的以强奸论并从重，情节恶劣或者多人的可以到 10 年以上直至死刑。所以这些情形下唯一可靠的做法是不发生关系，酒局散场把人交给她自己的朋友或家人，别单独送回住处。","gain":"《刑法》第二百三十六条：以暴力、胁迫或者其他手段强奸妇女的，处三年以上十年以下有期徒刑；奸淫不满十四周岁的幼女的，以强奸论，从重处罚；强奸妇女、奸淫幼女情节恶劣的，强奸妇女、奸淫幼女多人的等情形，处十年以上有期徒刑、无期徒刑或者死刑（全国）","grade":"B","src":"全国人大 (1997). 刑法（第二百三十六条）. <https://www.spp.gov.cn/spp/fl/201802/t20180206_364975.shtml>","note":"给 B 是因为法条只写了「其他手段」四个字，「醉酒或者昏睡状态下无法有效同意」是司法通说，本节未取得可逐字核对的现行公开解释。年龄这一侧的认定标准很严，见第 9 节第 18 条：不满 12 周岁一律认定「应当知道」。本条对性别不作区分，男性同样可能是被害人。你自己喝到断片时，被指控和被敲诈两种风险同时存在，见本节第 30 条（对方拿把柄来要钱就报警）。","money":"0","time":"少","will":"些","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"8.30","sec":8,"n":30,"title":"对方拿报警、发照片、告诉你单位来要钱，一分钱不给，直接报警","cost":"0，截图留证，带手机去派出所","human":"以「我去报警」「我把照片发给你单位」相要挟索要财物，是敲诈勒索，不是私事。价值 2000 到 5000 元以上就够「数额较大」，判 3 年以下；3 万到 10 万以上是数额巨大，3 到 10 年；30 万到 50 万以上是数额特别巨大，10 年以上。两年内敲诈三次以上，每次金额不大也算「多次」。做法和裸聊敲诈完全一样：一分钱不给、一条记录不删。","gain":"《刑法》第二百七十四条：敲诈勒索公私财物，数额较大或者多次敲诈勒索的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；数额巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑，并处罚金。两高《关于办理敲诈勒索刑事案件适用法律若干问题的解释》（法释〔2013〕10 号，2013 年 4 月 27 日起施行）第一条：敲诈勒索公私财物价值二千元至五千元以上、三万元至十万元以上、三十万元至五十万元以上的，应当分别认定为「数额较大」「数额巨大」「数额特别巨大」；第三条：二年内敲诈勒索三次以上的，应当认定为「多次敲诈勒索」（全国）","grade":"A","src":"全国人大 (2020 年修正). 刑法（第二百七十四条）. <https://jtgl.beijing.gov.cn/jgj/jgxx/flfg/fl/11033925/index.html>（北京市公安交管局转载整合文本）；最高人民法院、最高人民检察院 (2013). 关于办理敲诈勒索刑事案件适用法律若干问题的解释（法释〔2013〕10 号）. <https://www.court.gov.cn/zixun/xiangqing/5310.html>","note":"三档金额由各省在上述幅度内定具体数额，以当地标准为准。给了第一笔就会有第二笔，这一点和第 13 节的裸聊敲诈一样。别自己删聊天记录、注销账号、拉黑了事——那是把自己的证据也删了，见本节第 5 条。真被立案调查的，这些记录同时是你自证的材料。这条讲的是对方拿把柄向你索财；反过来，你自己是受害人去向侵权方索赔是另一回事，金额高也不等于敲诈，见本节第 34 条。","money":"0","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"极高"},{"id":"8.31","sec":8,"n":31,"title":"被人捏造事实举报，可以要求追究：够治安处罚的拘留 5 日起，够罪的判 3 年以下","cost":"0，向公安机关报案并说明对方是捏造","human":"捏造事实诬告陷害他人、企图使他人受刑事追究或者治安处罚的，本身就是治安违法：处 5 日以下拘留或者 1000 元以下罚款，情节较重的 5 日以上 10 日以下拘留，可以并处 1000 元以下罚款。够得上犯罪的是诬告陷害罪，情节严重判 3 年以下，造成严重后果判 3 到 10 年，国家机关工作人员从重。但法律自己划了一条线：不是有意诬陷，而是错告或者检举失实的，这两款都不适用——要追究对方，得证明他是有意诬陷，不是记错或者告错。","gain":"《治安管理处罚法》（2025 年 6 月 27 日修订，2026 年 1 月 1 日起施行）第五十条：捏造事实诬告陷害他人，企图使他人受到刑事追究或者受到治安管理处罚的，处五日以下拘留或者一千元以下罚款；情节较重的，处五日以上十日以下拘留，可以并处一千元以下罚款。《刑法》第二百四十三条：捏造事实诬告陷害他人，意图使他人受刑事追究，情节严重的，处三年以下有期徒刑、拘役或者管制；造成严重后果的，处三年以上十年以下有期徒刑；国家机关工作人员犯前款罪的，从重处罚；不是有意诬陷，而是错告，或者检举失实的，不适用前两款的规定（全国）","grade":"A","src":"全国人大常委会 (2025). 治安管理处罚法（2025 年修订，第五十条）. <https://gaj.beijing.gov.cn/wsgs/2024zcwj/zcfg/202506/t20250630_4134266.html>（北京市公安局转载全文）；全国人大 (1997). 刑法（第二百四十三条）. <https://www.spp.gov.cn/spp/fl/201802/t20180206_364975.shtml>","note":"要追究对方，需要证明的是「捏造事实」加「有意诬陷」，而不是「我没做过」，这两件事的举证难度差很远，别把追究当成必然结果。全国范围内没有公开的诬告立案与处理统计，本书查不到，因此不写发生率，也不写性别分布。自己这一侧的举证与救济见本节第 32、33 条（证据不足应判无罪、国家赔偿）。","money":"0","time":"少","will":"些","level":"中","lens":"自由","dispute":false,"todo":false,"ratio":"一般"},{"id":"8.32","sec":8,"n":32,"title":"证据不足本来就应当判无罪，逼出来的口供应当排除；判了还有申诉和再审","cost":"0；申诉和再审耗时间，通常要请律师，费用见本节第 5 条","human":"定罪的门槛写在刑事诉讼法里：定案的证据要经法定程序查证属实，还要综合全案证据排除合理怀疑；做不到就属于「证据不足、指控的犯罪不能成立」，应当判无罪。刑讯逼供等非法方法取得的供述、暴力威胁取得的证言和被害人陈述应当排除，侦查、审查起诉、审判任一阶段发现了都要排除，不得作为起诉意见、起诉决定和判决的依据。判决生效之后，当事人和他的法定代理人、近亲属还可以向法院或者检察院申诉，符合法定情形的法院应当重新审判。","gain":"《刑事诉讼法》第五十五条：证据确实、充分应当符合据以定案的证据均经法定程序查证属实、综合全案证据对所认定事实已排除合理怀疑等条件；第五十六条：采用刑讯逼供等非法方法收集的犯罪嫌疑人、被告人供述和采用暴力、威胁等非法方法收集的证人证言、被害人陈述，应当予以排除，在侦查、审查起诉、审判时发现有应当排除的证据的，应当依法予以排除，不得作为起诉意见、起诉决定和判决的依据；第二百条第（三）项：证据不足，不能认定被告人有罪的，应当作出证据不足、指控的犯罪不能成立的无罪判决；第二百五十二条：当事人及其法定代理人、近亲属对已经发生法律效力的判决、裁定，可以向人民法院或者人民检察院提出申诉，但是不能停止判决、裁定的执行；第二百五十三条列举了人民法院应当重新审判的情形（全国）","grade":"A","src":"全国人大常委会 (2018). 刑事诉讼法（2018 年修正，第五十五、五十六、二百、二百五十二、二百五十三条）. <https://www.spp.gov.cn/zdgz/201810/t20181027_396818.shtml>","note":"这些是制度写明的底线，不是结果保证。本书没有中国刑事案件无罪率、申诉改判率的可核对官方数据，所以不写比例，也不评价个案。自己能做的三件事：第一次讯问后就委托律师（本节第 5 条）、笔录逐字看完再签、别为了「早点出去」认下没做过的事——认罪认罚是从宽情节，不是免责。","money":"0","time":"中","will":"些","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"8.33","sec":8,"n":33,"title":"被羁押后撤案、不起诉或者判无罪的，去申请国家赔偿，按天算钱","cost":"0，向作出拘留、逮捕、起诉或者判决的机关提出赔偿申请","human":"被拘留、逮捕之后又撤案、不起诉或者判无罪的，可以申请国家赔偿。人身自由这一项按天算：最高检的通知是自 2026 年 5 月 18 日起每日 495.94 元（上一年度是 475.52 元），关一年就是 18 万元上下。除了这笔钱，还可以要求在侵权行为影响的范围内消除影响、恢复名誉、赔礼道歉，造成严重后果的支付精神损害抚慰金。有一种情况国家不赔：自己故意作虚伪供述，或者伪造有罪证据导致被羁押的。","gain":"《国家赔偿法》第十七条：违反刑事诉讼法规定对公民采取拘留措施，或者依法拘留但超过法定时限，其后决定撤销案件、不起诉或者判决宣告无罪终止追究刑事责任的；对公民采取逮捕措施后决定撤销案件、不起诉或者判决宣告无罪终止追究刑事责任的；依照审判监督程序再审改判无罪、原判刑罚已经执行的，受害人有取得赔偿的权利。第三十三条：侵犯公民人身自由的，每日赔偿金按照国家上年度职工日平均工资计算。第三十五条：致人精神损害的，应当在侵权行为影响的范围内为受害人消除影响、恢复名誉、赔礼道歉，造成严重后果的应当支付相应的精神损害抚慰金。第十九条：因公民自己故意作虚伪供述，或者伪造其他有罪证据被羁押或者被判处刑罚的，国家不承担赔偿责任。最高人民检察院 2026 年 5 月通知：国家统计局 2026 年 5 月 15 日公布 2025 年全国城镇非私营单位就业人员年平均工资为 129441 元，据此日平均工资为 495.94 元，各级检察院自 2026 年 5 月 18 日起作出国家赔偿决定时，对侵犯公民人身自由的赔偿金按每日 495.94 元计算（2025 年 5 月起的标准为每日 475.52 元）（全国）","grade":"A","src":"全国人大常委会 (2012 年修正). 国家赔偿法（第十七、十九、三十三、三十五条）. <https://www.stats.gov.cn/gk/tjfg/xgfxfg/202503/t20250306_1958899.html>（国家统计局转载）；最高人民检察院 (2026). 最高人民检察院公布最新侵犯公民人身自由的赔偿金标准. <https://www.spp.gov.cn/xwfbh/wsfbh/202605/t20260519_727675.shtml>","note":"这个日标准每年 5 月随国家统计局公布的上年度城镇非私营单位年平均工资更新，用的时候查当年的数字，别直接套本条这个。精神损害抚慰金由办案机关按后果确定，没有统一公式，本条不给金额。赔偿义务机关是作出错误羁押决定的那个机关（公安、检察院或法院），先向它提出，对处理不服的可以按国家赔偿法规定的程序往上申请。实际算法可以看本节第 34 条那个案子的决定书：郭利被羁押 1826 天，按作出决定时适用的 2016 年度全国职工日平均工资 258.89 元计算，人身自由赔偿金 472733.14 元，另支付精神损害抚慰金 165450 元——注意用的是作决定时的标准，不是羁押当年的标准；他申请的十年精神损害抚慰金 8888 万元，超出部分不予支持。也要知道赔不了什么：那份决定书把误工费、生命健康权赔偿、财产损失、律师费、看守所生活费补贴等一并认定为不属于国家赔偿的法定范围。","money":"0","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"极高"},{"id":"8.34","sec":8,"n":34,"title":"自己是受害人去索赔，走 12315、起诉或者律师，别单独赴对方的约，别把「给钱」和「我不曝光」绑成一句话","cost":"0，通过 12315、法院起诉或者委托律师提出；见面谈判全程录音","human":"自己是受害人，向侵权方索赔——包括金额提得很高、包括向媒体曝光——本身有法律依据，不会因为「要价高」就自动变成敲诈勒索。郭利案的检察机关意见写得很直白：现有证据不足以证实他主观上有非法占有的目的，他作为女儿的法定监护人有权利向奶粉生产厂家索赔，消费者也有权通过媒体揭露、批评。但这个案子同时说明代价可能有多大：他先被以敲诈勒索罪判了五年，被羁押 1826 天，到 2017 年 4 月 7 日才由广东省高级人民法院再审宣告无罪。所以三件事要做到：走留痕的渠道；别单独去对方指定的地方谈；别把「给钱」和「我就不曝光、不举报」绑成一个条件说出口。","gain":"官方案例：2008 年有关部门公布部分批次「施恩」牌奶粉含三聚氰胺后，郭利之女的检查结果为「双肾中央集合系统内可见数个点状强回声」，郭利多次向销售商和施恩公司索赔并向媒体曝光；2009 年 6 月双方达成协议，施恩公司补偿 40 万元，郭利出具书面材料表示不再追诉并放弃赔偿要求；此后公司报案，郭利被潮安县人民法院以敲诈勒索罪判处有期徒刑五年。广东省人民检察院的再审建议认为「现有证据不足以证实郭利主观上具有非法占有的目的」，郭利作为法定监护人「有权利向奶粉的生产厂家索赔，其索赔行为有法律依据」，且「消费者对损害其合法权益的行为，有权通过大众传播媒介予以揭露、批评」。2017 年 4 月 7 日，广东省高级人民法院再审宣告郭利无罪，理由是「原审认定郭利以非法占有为目的，使用威胁、要挟的方法，强行索取财物行为的事实不清，证据不足，郭利的行为性质未超出民事纠纷的范畴」。郭利自 2009 年 7 月 23 日至 2014 年 7 月 22 日被羁押 1826 天（广东，2017 年再审改判）","grade":"B","src":"广东省人民检察院 (2017). 广东省检察院再审建议对郭利案改判无罪. <https://jcy.heyuan.gov.cn/node/142>（河源市人民检察院转载）；广东省高级人民法院赔偿委员会 (2018). 郭利以再审无罪为由申请、广东省潮州市中级人民法院赔偿的国家赔偿案件（（2018）粤委赔 11 号）. <https://www.gdcourts.gov.cn/caipanwenshuxuandeng/caipanwenshuxuandeng/content/post_1045709.html>","note":"给 B 是因为这是单个案例，不是可推广的比例——它同时证明了两件事：索赔本身合法，以及仍然可能被立案。风险最低的路径是把索赔交给律师或者直接起诉，自己不与对方单独接触；对方约你去他所在地「面谈解决」时尤其要留意，报案和立案通常发生在对方所在地。和解协议签了就照协议走，签完再另起一笔高额索赔最容易被解读成「要挟」。被立案之后的处置见本节第 5、32、33 条（先请律师、证据不足应判无罪、国家赔偿）；对方拿把柄向你索财是相反的一侧，见本节第 30 条。","money":"0","time":"少","will":"些","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"8.35","sec":8,"n":35,"title":"被网暴了：先开防护、先固证，再在平台、禁令、报警三条路里挑","cost":"0 元；当场十几分钟做防护和取证；走到申请禁令或者自诉，要跑法院，可能要请律师","human":"先做三件当场的事——把平台的防护设置全打开（屏蔽陌生用户或特定用户、限制自己发布内容的可见范围、禁止转载或评论、只收好友私信甚至拒收所有私信），用平台的快捷取证功能把内容固定下来，再从显著位置的快捷入口举报。然后三条路：正在发生、不及时制止会造成难以弥补损害的，可以向法院申请人格权侵害禁令，让他先停；侮辱诽谤原则上要你自己去法院告，取证确有困难的，法院可以要求公安协助查明是谁、收集传播和影响的证据，协助之后够条件的法院应当立案；到了「严重危害社会秩序」那一档转公诉，不用你自己举证。人肉搜索把你的个人信息发出去，情节严重的按侵犯公民个人信息罪办。","gain":"法发〔2023〕14 号第 15 条：权利人有证据证明行为人正在实施或者即将实施侵害其人格权的违法行为，不及时制止将使其合法权益受到难以弥补的损害，依据民法典第九百九十七条申请的，人民法院可以依法作出人格权侵害禁令；第 11 条：自诉案件「被害人提供证据确有困难的，可以要求公安机关提供协助」，公安机关应当及时查明行为主体、收集传播扩散情况及影响等证据材料，网络服务提供者应当提供必要的技术支持，「经公安机关协助取证，达到自诉案件受理条件的，人民法院应当决定立案」，无法收集的应当书面说明；第 12 条列了五种应认定为刑法第二百四十六条第二款「严重危害社会秩序」的情形：造成被害人或者其近亲属精神失常、自杀等严重后果且社会影响恶劣；随意以普通公众为侵害对象、信息大范围传播引发大量低俗恶意评论且社会影响恶劣；侮辱诽谤多人或者多次散布且社会影响恶劣；组织、指使人员在多个平台大量散布且社会影响恶劣；其他。该解释第 4 条：组织「人肉搜索」，违法收集并向不特定多数人发布公民个人信息，情节严重的以侵犯公民个人信息罪定罪处罚。《网络暴力信息治理规定》第二十三条要求平台提供屏蔽陌生用户或特定用户、限制本人发布信息可见范围、禁止转载或评论、仅接收好友私信或拒绝接收所有私信等防护选项，第二十五条要求提供快捷取证功能，第二十六条要求在显著位置设快捷投诉举报入口，第十五条要求平台发现涉嫌违法犯罪及时向公安机关报案","grade":"A","src":"最高人民法院、最高人民检察院、公安部 (2023). 关于依法惩治网络暴力违法犯罪的指导意见（法发〔2023〕14 号，第 4、11、12、15 条）. <https://www.court.gov.cn/zixun/xiangqing/412992.html>；全国人大 (2020). 民法典（第九百九十七条）. 最高人民检察院转载全文 <https://www.spp.gov.cn/spp/fl/202006/t20200602_463888.shtml>；国家互联网信息办公室、公安部、文化和旅游部、国家广播电视总局 (2024). 网络暴力信息治理规定（第十五、二十三、二十五、二十六条，2024 年 8 月 1 日施行）. 国务院公报 <https://www.gov.cn/gongbao/2024/issue_11526/202408/content_6969181.html>","note":"顺序按「快且便宜」排：平台最快、成本最低，先固证先举报；法院最慢最贵，最后再定要不要打。三条路的过程成本都得自己扛——禁令要向法院申请，自诉要自己立案举证，转公诉得够该解释第 12 条那五种情形之一，够不上就只能自诉。两件别做的事：不对骂（骂回去会把你自己变成本节第 14 条（网上不骂人、不造谣）里被处罚的那个），不删自己账号里的内容（那是证据）。扛不住时打 12356，见第 1 节第 25 条；要求平台删除你的个人信息见第 14 节第 8 条；因为帮了陌生人被拍被传上网的那条路径见 [docs/遇到陌生人出事该不该停.md](../docs/遇到陌生人出事该不该停.md)。","money":"0","time":"中","will":"些","level":"中","lens":"自由","dispute":false,"todo":false,"ratio":"一般"},{"id":"8.36","sec":8,"n":36,"title":"「先给人买保险再动手」这条路法律上从头堵死：钱一分拿不到，罪按故意杀人加保险诈骗数罪并罚","cost":"0 元","human":"四道门都是关着的。第一道，背着家人给他买以死亡为给付条件的保险，没有本人同意并认可保险金额，合同无效；投保人指定受益人也要被保险人同意（父母给未成年子女投保不受此限）。第二道，投保人故意造成被保险人死亡的，保险公司不承担给付责任；受益人故意造成被保险人死亡、甚至故意杀害未遂的，直接丧失受益权。第三道，保险金退回遗产这条路也没有：故意杀害被继承人的，丧失继承权。第四道，刑法把「投保人、受益人故意造成被保险人死亡、伤残或者疾病，骗取保险金」单列一项，并且写明同时构成其他犯罪的数罪并罚——故意杀人罪另算，最高死刑。至于「查不到」：安徽宣城那起伪造车辆落水案，事发前不到半个月给妻子买了 4 份各 100 万元的保险、7 天后被抓，最后以故意杀人罪和保险诈骗罪数罪并罚判死缓并处罚金 5 万元。","gain":"保险法第三十四条：以死亡为给付保险金条件的合同，未经被保险人同意并认可保险金额的，合同无效（父母为未成年子女投保不受限制）；第三十九条：投保人指定受益人时须经被保险人同意；第四十三条：投保人故意造成被保险人死亡、伤残或者疾病的，保险人不承担给付保险金的责任，投保人已交足二年以上保险费的向其他权利人退还现金价值，受益人故意造成被保险人死亡、伤残、疾病的或者故意杀害被保险人未遂的，该受益人丧失受益权；第二十七条第二款：投保人、被保险人故意制造保险事故的，保险人有权解除合同、不承担赔偿或给付责任，除第四十三条规定外不退还保险费。民法典第一千一百二十五条：故意杀害被继承人的，丧失继承权。刑法第一百九十八条第一款第五项把「投保人、受益人故意造成被保险人死亡、伤残或者疾病，骗取保险金」列为保险诈骗，数额较大处 5 年以下并处 1 万至 10 万元罚金、数额巨大处 5 至 10 年、特别巨大处 10 年以上；第二款：有该项行为同时构成其他犯罪的，依照数罪并罚的规定处罚；第二百三十二条：故意杀人的，处死刑、无期徒刑或者十年以上有期徒刑。案例：安徽宣城张某松案，2016 年 7 月 18 日凌晨驾车冲入池塘致妻子溺亡，事发前不到半个月为妻子投保 4 份、每份 100 万元，7 月 25 日被抓获，以故意杀人罪、保险诈骗罪数罪并罚判处死缓并处罚金 5 万元","grade":"A","src":"全国人大常委会 (2015 修正). 中华人民共和国保险法第二十七、三十四、三十九、四十三条. <https://flk.npc.gov.cn/detail?id=2c909fdd678bf17901678bf7c4060811>；全国人大 (2020). 中华人民共和国民法典第一千一百二十五条. <https://flk.npc.gov.cn/detail?id=ff808081729d1efe01729d50b5c500bf>；全国人大常委会. 中华人民共和国刑法（经刑法修正案十一修正的整合文本）第一百九十八条、第二百三十二条. <https://flk.npc.gov.cn/detail?id=ff808181796a636a0179822a19640c92>；安徽省人民检察院转载《法制日报》(2020-01-13). 杀妻骗保牵出案中案（安徽省人民检察院民事虚假诉讼监督典型案例）. <http://www.ah.jcy.gov.cn/jczt/jjslhyqkjc/mtjj/202001/t20200113_2758841.shtml>","note":"这条的受益人是自己——避免的是死刑或者无期。案例的伤亡与判决取自检察机关公布的典型案例原文，正文不写侦查手段之外的细节。伪造事故、夸大损失这类不涉及人命的骗保同样是犯罪，连帮忙作证的人一起算，见第 9 节第 21 条；给家人买保险本身是正常的，这条针对的是「买了保险再动手」这个念头，想伤害家人的冲动按急症处理见本节第 12、13 条（自己冒出念头、身边人说出狠话）","money":"0","time":"少","will":"否","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"极高"},{"id":"8.37","sec":8,"n":37,"title":"报警当场要受案回执，不立案要书面通知：7 日内可申请复议，再 7 日可申请复核，检察院能通知公安立案","cost":"0 元；当场多问一句要回执，之后按日期追问","human":"报警和立案是两件事。公安机关接受案件时应当制作受案登记表和受案回执，把回执交给报案人、控告人、举报人——这张纸是你「报过案」的唯一凭据，当场就要，别嫌麻烦。治安案件（打架、小偷小摸这类）的办案期限自受理之日起不超过 30 日，案情重大复杂的经上一级公安机关批准可以再延 30 日，做鉴定的时间不计入。刑事那条线上，接案后要迅速审查，认为有犯罪事实需要追究刑事责任的才立案；决定不立案且有控告人的，应当制作不予立案通知书并在 3 日以内送达。不服不是只能忍：收到通知书后 7 日以内向作出决定的公安机关申请复议，公安机关 30 日以内作出决定；对复议结果仍不服，7 日以内向上一级公安机关申请复核，上一级 30 日以内作出决定，重大复杂的可延长但不超过 30 日并且要书面告知你。还有一条独立的路：被害人认为公安机关该立案而不立案，可以向人民检察院提出，检察院应当要求公安机关说明理由，认为理由不成立的应当通知立案，公安机关接到通知后应当立案。民警办案中的违法违纪行为走督察机构投诉，和案子本身分开走。","gain":"《公安机关办理刑事案件程序规定》（公安部令第 159 号修正后）第一百七十一条：「公安机关接受案件时，应当制作受案登记表和受案回执，并将受案回执交扭送人、报案人、控告人、举报人」；第一百七十四条：「对接受的案件，或者发现的犯罪线索，公安机关应当迅速进行审查」；第一百七十八条：接受案件后经审查认为有犯罪事实需要追究刑事责任且属于自己管辖的，经县级以上公安机关负责人批准予以立案，「对有控告人的案件，决定不予立案的，公安机关应当制作不予立案通知书，并在三日以内送达控告人」；第一百七十九条：「控告人对不予立案决定不服的，可以在收到不予立案通知书后七日以内向作出决定的公安机关申请复议；公安机关应当在收到复议申请后三十日以内作出决定」「控告人对不予立案的复议决定不服的，可以在收到复议决定书后七日以内向上一级公安机关申请复核；上一级公安机关应当在收到复核申请后三十日以内作出决定。对上级公安机关撤销不予立案决定的，下级公安机关应当执行」，案情重大、复杂的可延长复议复核时限但「不得超过三十日，并书面告知申请人」。刑事诉讼法第一百一十二条：认为有犯罪事实需要追究刑事责任的应当立案，不予立案的「将不立案的原因通知控告人。控告人如果不服，可以申请复议」；第一百一十三条：「被害人认为公安机关对应当立案侦查的案件而不立案侦查，向人民检察院提出的，人民检察院应当要求公安机关说明不立案的理由。人民检察院认为公安机关不立案理由不能成立的，应当通知公安机关立案，公安机关接到通知后应当立案」。《公安机关办理行政案件程序规定》第六十一条：属于本单位管辖的案件「应当立即调查处理，制作受案登记表和受案回执，并将受案回执交报案人、控告人、举报人、扭送人」；办理治安案件的期限「自受理之日起不得超过 30 日；案情重大、复杂的，经上一级公安机关批准，可以延长 30 日」，鉴定期间不计入办案期限。《公安机关督察条例》第九条：「督察机构对群众投诉的正在发生的公安机关及其人民警察违法违纪行为，应当及时出警，按照规定给予现场处置，并将处理结果及时反馈投诉人」（全国）","grade":"A","src":"全国人大 (2018). 刑事诉讼法（2018 年修正，第一百一十二、一百一十三条）. <https://flk.npc.gov.cn/detail?id=ff8080816f135f46016f1d1b81b01351>；公安部 (2020). 关于修改《公安机关办理刑事案件程序规定》的决定（公安部令第 159 号）及修正后全文. <http://www.gov.cn/gongbao/content/2020/content_5549884.htm>；公安部 (2013/2019 修正). 公安机关办理行政案件程序规定（公安部令第 125 号，第 149 号修改决定）. <http://www.gov.cn/gongbao/content/2013/content_2321117.htm>、<http://www.gov.cn/zhengce/zhengceku/2018-12/31/content_5428593.htm>；国务院 (2011). 公安机关督察条例（国务院令第 603 号，第九条）. <https://www.gov.cn/zhengce/zhengceku/2011-09/08/content_6138.htm>","note":"受益人是你自己。这条解决的是「我以为报了警就一定会处理」——处理与否、多久处理，都有明文的标准和期限，而不是看接警的人当天心情。三个动作按顺序记：① 当场拿受案回执，把案件编号和受理单位记下来；② 到期没结果就按上面的期限去问进度，问的是「案子在哪个环节」，不是「为什么不管我」；③ 收到不予立案通知书先看理由，7 日内复议、再 7 日复核，同时可以向人民检察院提出立案监督，三条路不冲突。接待态度差和案子办不办是两件事，前者走督察投诉，别让它把你从后者的流程上带偏。捡到失物、邻里纠纷这类本来就不是刑事案件，公安机关按行政案件或者调解处理，甚至只是登记备案，别按「报案没人管」理解。诈骗被骗的止付流程见本节第 2 条，网暴见本节第 35 条","money":"0","time":"少","will":"些","level":"中","lens":"自由","dispute":false,"todo":false,"ratio":"一般"},{"id":"8.38","sec":8,"n":38,"title":"别给办案、执法的人送钱送卡：行贿自己也判，对监察、执法、司法人员行贿还要从重","cost":"0 元，只是不去做","human":"「花点钱把事摆平」在刑法里是独立的罪，被抓的不只是收钱那个人。行贿罪的定义是为谋取不正当利益给国家工作人员财物；2024 年 3 月 1 日起施行的刑法修正案十二把量刑改成三档：3 年以下并处罚金，因行贿谋取不正当利益情节严重或使国家利益遭受重大损失的 3 到 10 年，特别严重的 10 年以上或者无期，并处罚金或者没收财产。同时列了七种从重情形，其中两条正好对着这类场景：「对监察、行政执法、司法工作人员行贿的」，以及在教育、医疗、社会保障、食品药品、安全生产等领域行贿并实施违法犯罪活动的。法律也留了两个口子：因被勒索给予财物、没有获得不正当利益的，不是行贿；在被追诉前主动交待行贿行为的，可以从轻或者减轻处罚，犯罪较轻且对侦破重大案件起关键作用的，可以减轻或者免除处罚。","gain":"刑法第三百八十九条：「为谋取不正当利益，给予国家工作人员以财物的，是行贿罪」「在经济往来中，违反国家规定，给予国家工作人员以财物，数额较大的，或者违反国家规定，给予国家工作人员以各种名义的回扣、手续费的，以行贿论处」「因被勒索给予国家工作人员以财物，没有获得不正当利益的，不是行贿」。刑法第三百九十条（刑法修正案十二修改，2024 年 3 月 1 日起施行）：「对犯行贿罪的，处三年以下有期徒刑或者拘役，并处罚金；因行贿谋取不正当利益，情节严重的，或者使国家利益遭受重大损失的，处三年以上十年以下有期徒刑，并处罚金；情节特别严重的，或者使国家利益遭受特别重大损失的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产」；七种从重情形为「（一）多次行贿或者向多人行贿的；（二）国家工作人员行贿的；（三）在国家重点工程、重大项目中行贿的；（四）为谋取职务、职级晋升、调整行贿的；（五）对监察、行政执法、司法工作人员行贿的；（六）在生态环境、财政金融、安全生产、食品药品、防灾救灾、社会保障、教育、医疗等领域行贿，实施违法犯罪活动的；（七）将违法所得用于行贿的」；末款：「行贿人在被追诉前主动交待行贿行为的，可以从轻或者减轻处罚。其中，犯罪较轻的，对调查突破、侦破重大案件起关键作用的，或者有重大立功表现的，可以减轻或者免除处罚」（全国）","grade":"A","src":"全国人大常委会. 中华人民共和国刑法（经刑法修正案十一修正的整合文本）第三百八十九条. <https://flk.npc.gov.cn/detail?id=ff808181796a636a0179822a19640c92>；全国人大常委会 (2023). 中华人民共和国刑法修正案（十二）（第五项，修改刑法第三百九十条；自 2024 年 3 月 1 日起施行）. <https://flk.npc.gov.cn/detail?id=ff8081818c3ce31f018cb6a6bc412f55>","note":"受益人是你自己。这条对着的是「贿赂一下就能免除惩罚」这种想法：对方有同事、有台账、有监控和督察，你送出去的东西是他被查时的证据，也是你自己的罪证，而且这一类行贿是明文从重的那一档。真遇到对方索要好处，正确动作是按前一条的渠道走——留下受案回执和文书、向督察机构或者纪检监察机关反映；刑法第三百八十九条第三款给的免责条件是「被勒索且没有获得不正当利益」，一旦你借此拿到了本来拿不到的东西，这个条件就不成立。医院里的红包属于另一套规则，见第 24 节第 12 条","money":"0","time":"少","will":"否","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"极高"}]},{"n":9,"title":"普通人容易踩的法律红线","intro":"本节口径是人身自由与金钱：下面这些事普通人常以为「没什么」，实际会被拘留、罚款或判刑，每条给出法条里的具体数字和官方渠道公布的案例。治安管理处罚法引用的是 2025 年修订版（2026 年 1 月 1 日起施行，条款号与旧法不同），刑法引用北京市公安交管局转载的「根据刑法修正案（十一）修正」整合文本并注明对应修正案；排序按「最容易无意中踩到 × 后果最重」从高到低。","entries":[{"id":"9.1","sec":9,"n":1,"title":"群里不转发不知真假的灾情、疫情、警情消息，不 P 图、不用 AI 造现场图","cost":"0 元；转发前看一眼是不是官方通报，拿不准就不转、不改图、不加「据说」","human":"明知是假还转一条灾情、疫情、警情消息，就算不是你编的，也能拘留 5 到 10 日、罚 1000 元；把社会秩序搅乱了判 3 年以下，造成严重后果 3 到 7 年。P 图和 AI 生成的假现场图，和自己编是同一回事。","gain":"故意散布谣言，谎报险情、疫情、灾情、警情扰乱公共秩序的，拘留 5 到 10 日并可罚 1000 元以下，情节较轻拘留 5 日以下或罚 1000 元以下；编造虚假险情、疫情、灾情、警情在网上传播，或明知是假仍故意传播，严重扰乱社会秩序的，判 3 年以下，造成严重后果判 3 到 7 年（全国）","grade":"A","src":"全国人大常委会 (2025). 治安管理处罚法（2025 年修订，第二十九条）. <https://www.spp.gov.cn/spp/fl/202506/t20250627_699863.shtml>；全国人大常委会 (2015). 刑法修正案（九）（第三十二条，即刑法第二百九十一条之一第二款）. <https://www.spp.gov.cn/spp/fl/201802/t20180205_364562.shtml>；全国人大 (2020). 刑法（根据刑法修正案（十一）修正，第二百九十一条之一）. <https://jtgl.beijing.gov.cn/jgj/jgxx/flfg/fl/11033925/index.html>（北京市公安交通管理局转载）","note":"「明知是假仍转发」和「自己编」用的是同一条，转发不等于免责；P 图、AI 生成的假现场图同样是编造。公安部 2025 年公布过多批涉灾情、险情网络谣言典型案例，本节写作时其网站无法打开，未引用具体案例。","money":"0","time":"少","will":"些","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"9.2","sec":9,"n":2,"title":"不发、不转侮辱英烈的图片、表情包和评论，不拿国旗国歌开玩笑","cost":"0 元；涉及英烈、国旗、国徽、国歌的内容不评论、不改图、不转","human":"拿英烈、国旗、国歌开玩笑，轻的拘留 5 到 10 日或罚一到三千元，情节较重拘留 10 到 15 日，构成犯罪判 3 年以下。有人在 499 人的村民群里发了两条诋毁袁隆平的话，判管制 6 个月；另一人用 250 多万粉丝的微博发 2 条歪曲戍边官兵事迹的内容，判 8 个月，还要在全国性媒体上公开道歉。","gain":"以侮辱、诽谤或其他方式侵害英雄烈士姓名、肖像、名誉、荣誉损害公共利益的，或亵渎、否定英烈事迹精神，制作传播美化侵略战争的言论、图片、音视频扰乱公共秩序的，拘留 5 到 10 日或罚 1000 到 3000 元，情节较重拘留 10 到 15 日并可罚 5000 元以下；情节严重的构成犯罪，判 3 年以下；公共场合侮辱国旗国徽，或篡改国歌歌词曲谱、以歪曲贬损方式奏唱国歌情节严重的，判 3 年以下；官方案例：肖某在 499 人的村民微信群发 2 条信息诋毁侮辱袁隆平，判管制 6 个月；仇某用 250 余万粉丝的微博发 2 条歪曲卫国戍边官兵事迹，判 8 个月并在全国性媒体公开道歉（全国）","grade":"A","src":"全国人大常委会 (2025). 治安管理处罚法（2025 年修订，第三十五条）. <https://www.spp.gov.cn/spp/fl/202506/t20250627_699863.shtml>；全国人大常委会 (2018). 英雄烈士保护法（第二十二、二十六条）. <https://www.spp.gov.cn/spp/gyssshmhsh/201912/t20191202_440079.shtml>；全国人大常委会 (2020). 刑法修正案（十一）（第三十五条，即刑法第二百九十九条之一）. <https://www.spp.gov.cn/zdgz/202012/t20201227_503682.shtml>；全国人大 (2020). 刑法（根据刑法修正案（十一）修正，第二百九十九条、第二百九十九条之一）. <https://jtgl.beijing.gov.cn/jgj/jgxx/flfg/fl/11033925/index.html>；最高人民法院 (2022). 涉英烈权益保护十大典型案例（案例二、案例三）. <https://www.court.gov.cn/zixun/xiangqing/382301.html>","note":"治安法这一条 2025 年修订才加进来，之前只能靠刑法和民事公益诉讼；几百人的微信群在法院眼里就是公开场合。","money":"0","time":"少","will":"些","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"9.3","sec":9,"n":3,"title":"境外网站上的东西看完就关，不截图、不转发、不搬进群里，也不在评论区跟着说","cost":"0 元；页面关掉这件事就结束，不存档、不转发、不搬到境内平台，不用能对上自己身份的账号在境外平台长期发政治内容，也不接境外机构、组织、个人给的稿费和资助","human":"法律罚的是往外传，不是看——只有一类例外，宣扬恐怖主义、极端主义的书、音视频和物品，明知而存在自己手里、情节严重的，光持有就够定罪，判 3 年以下。其余的：转发、搬进群、跟着在评论区说，认定上都算传播。到煽动颠覆、煽动分裂这一档，判 5 年以下，首要分子或罪行重大的 5 年以上，还要附加剥夺政治权利 1 到 5 年、可以并处没收财产；给境外机构提供国家秘密或情报是 5 到 10 年起。转出去换不回任何东西。","gain":"以造谣、诽谤或者其他方式煽动颠覆国家政权、推翻社会主义制度的，判 5 年以下，首要分子或者罪行重大的判 5 年以上（有期徒刑上限 15 年）；煽动分裂国家、破坏国家统一的是同一档；与境外机构、组织、个人相勾结实施这两条的从重处罚；境内外机构、组织或者个人资助他人实施的，对直接责任人员判 5 年以下，情节严重的 5 年以上；为境外的机构、组织、人员窃取、刺探、收买、非法提供国家秘密或者情报的，判 5 到 10 年，情节特别严重的 10 年以上或者无期，情节较轻的 5 年以下；危害国家安全的犯罪一律附加剥夺政治权利 1 到 5 年，还可以并处没收财产；行政层面，任何个人和组织不得利用网络从事危害国家安全、荣誉和利益，煽动颠覆国家政权、推翻社会主义制度，煽动分裂国家、破坏国家统一等活动，发布或者传输这类信息的按有关法律、行政法规处罚（全国）；另有一类不必传播就成立：明知是宣扬恐怖主义、极端主义的图书、音频视频资料或者其他物品而非法持有，情节严重的，处 3 年以下有期徒刑、拘役或者管制，并处或者单处罚金（刑法第一百二十条之六，刑法修正案九新增）","grade":"A","src":"全国人大 (1997). 刑法（第四十五、五十五、五十六、一百零三、一百零五、一百零六、一百零七、一百一十一、一百一十三条，这几条未经修正案修改）. <https://www.spp.gov.cn/spp/fl/201802/t20180206_364975.shtml>；全国人大常委会 (2025). 网络安全法（2025 年修正，2026 年 1 月 1 日施行，第十三条第二款、第七十一条第一项）. <https://www.cac.gov.cn/2025-12/29/c_1768735112911946.htm>；全国人大常委会 (2015). 刑法修正案（九）（新增第一百二十条之六）. 国家信访局转载全文 <https://www.gjxfj.gov.cn/gjxfj/fgwj/flfg/webinfo/2017/03/1601761496614423.htm>","note":"本条引的那几条罚的是「煽动」「传播」「提供」，不是「看」，但别把这句推广到所有内容：恐怖主义、极端主义材料是明文的例外，「存下来」本身就能定罪（第一百二十条之六），所以「不存档」对这一类不是谨慎建议而是硬线。看到了就到此为止：不截图存档、不转发、不加评论、不拉人一起转。转发和跟帖在认定上都算传播，「我只是转了一下」不是免责理由，内容出自境外平台还可能构成从重情节；拿不准真假的更不要跟着转，同本节第 1 条。翻墙工具本身的处罚见第 11 节第 11 条。算一笔账：这类内容转出去换不回任何实质收益，代价是刑期加剥夺政治权利加没收财产。公开可查的同类案件（一名长期在境外平台发政治评论的博主 2023 年被判 7 年）只见于境外媒体和家属公布的文书，本书未取得官方渠道可核对的判决书，故条目按法条写、未附案例。","money":"0","time":"少","will":"些","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"9.4","sec":9,"n":4,"title":"黄色视频自己看归自己，别往群里发、别卖「资源」、别建群","cost":"0 元；不转、不存进群文件、不当这种群的群主群管","human":"自己看不在处罚条款里，往群里发一次就是向全群传播：拘留 10 到 15 日、罚 5000 元以下，情节严重判 2 年以下。靠卖「资源」挣钱的判 3 年以下，情节严重 3 到 10 年，特别严重 10 年以上直到无期。建一个 30 人以上的传播群，建群的、当管理员的、主要发的都按传播淫秽物品罪算。","gain":"利用信息网络传播淫秽信息的，拘留 10 到 15 日并可罚 5000 元以下，情节较轻拘留 5 日以下或罚 1000 到 3000 元，内容涉及未成年人从重；传播淫秽物品情节严重的判 2 年以下；以牟利为目的贩卖、传播的判 3 年以下并处罚金，情节严重 3 到 10 年，特别严重 10 年以上或无期；建立主要用于传播淫秽电子信息的群，成员 30 人以上或造成严重后果的，建立者、管理者和主要传播者按传播淫秽物品罪定罪（全国）","grade":"A","src":"全国人大常委会 (2025). 治安管理处罚法（2025 年修订，第八十条）. <https://www.spp.gov.cn/spp/fl/202506/t20250627_699863.shtml>；全国人大 (2020). 刑法（根据刑法修正案（十一）修正，第三百六十三、三百六十四条）. <https://jtgl.beijing.gov.cn/jgj/jgxx/flfg/fl/11033925/index.html>；最高人民法院、最高人民检察院 (2010). 关于办理利用互联网、移动通讯终端、声讯台制作、复制、出版、贩卖、传播淫秽电子信息刑事案件具体应用法律若干问题的解释（二）（第三条）. <https://www.spp.gov.cn/zdgz/201002/t20100204_25001.shtml>","note":"两部法律罚的都是「传播」，私下观看不在条款里；往群里发一次就是向全群传播。「情节严重」的数量标准由司法解释规定，本节未核实具体数字。","money":"0","time":"少","will":"否","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"极高"},{"id":"9.5","sec":9,"n":5,"title":"「兼职」要你用自己的卡收钱、取现、转账，不管给多少好处费都不做","cost":"0 元；放弃这类「日结几百、带卡去银行」的活","human":"这类兼职挣的是几百块，代价是案底。有人带着身份证和 1 张银行卡到指定地点配合转账取款，挣了 500 多元，检察院虽然没起诉，公安还是拘了 10 日、罚 1000 元；另一人把自己和他人的银行卡、手机卡交给团伙收款取现，判 2 年 3 个月、罚 2.2 万元。","gain":"明知是犯罪所得仍代为转移、收购、销售或以其他方法掩饰隐瞒的，判 3 年以下并处或单处罚金；官方案例：王某某按指示带身份证和 1 张银行卡到指定地点配合转账取款，获利 500 余元，检察院不起诉，公安按反电信网络诈骗法拘留 10 日并罚 1000 元；满某某把自己和他人的银行卡、手机卡交给团伙收款、转账、取现，判 2 年 3 个月并罚 2.2 万元（全国）","grade":"A","src":"全国人大 (2020). 刑法（根据刑法修正案（十一）修正，第三百一十二条）. <https://jtgl.beijing.gov.cn/jgj/jgxx/flfg/fl/11033925/index.html>；最高人民检察院 (2023). 检察机关依法惩治电信网络诈骗及其关联犯罪典型案例（案例九）. <https://www.spp.gov.cn/xwfbh/wsfbt/202311/t20231130_635188.shtml>；最高人民法院、最高人民检察院 (2025). 依法惩治掩饰、隐瞒犯罪所得、犯罪所得收益犯罪典型案例（案例五）. <https://www.spp.gov.cn/xwfbh/wsfbt/202508/t20250825_704514.shtml>","note":"借卡、跑分见第 8 节第 7 条，本条讲的是自己动手取现转账；「不知道钱哪来的」在实务中按报酬明显过高、要求刷脸配合、交易不合常理等推定明知。最轻的结果也是拘留 10 日加案底。","money":"0","time":"少","will":"否","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"极高"},{"id":"9.6","sec":9,"n":6,"title":"有人拉你去「包装材料」贷款、按贷款额分你好处费，一个都不做","cost":"0 元；拒绝，不出借身份证和自己的征信记录，不签没看过的贷款合同，不替人去银行面签","human":"帮人「包装材料」贷款拿分成，按诈骗办。一个 126 人的团伙把无业人员包装成「优质客户」在 80 多家银行骗贷 3000 多万元，出面签字的按贷款额拿三成好处费，已判的 80 人里 76 人判 1 年 4 个月到 6 年 6 个月。「本来是想还的」没被采纳：查明这些人没工作没资产，根本还不上。钱贷在谁名下，债和征信记录就是谁的。","gain":"以欺骗手段取得银行或者其他金融机构贷款、票据承兑、信用证、保函等，给银行或者其他金融机构造成重大损失的判 3 年以下并处或者单处罚金，造成特别重大损失或者有其他特别严重情节的判 3 到 7 年并处罚金，立案追诉线是直接经济损失 50 万元以上；本来就没打算还，用编造的引进资金项目理由、虚假的经济合同、虚假的证明文件或者虚假的产权证明骗贷款的，是贷款诈骗罪，数额 5 万元即立案，判 5 年以下并处 2 万到 20 万元罚金，数额巨大或者有其他严重情节判 5 到 10 年，特别巨大判 10 年以上直至无期；伪造、变造、买卖国家机关的公文、证件、印章判 3 年以下，情节严重判 3 到 10 年；官方案例：一个 126 人团伙在 16 个省市把无业人员包装成「优质客户」，在 80 多家银行网点骗贷 3000 余万元，出面贷款的「白户」按贷款金额三成拿好处费，检察院追诉 105 名「白户」，2026 年一审已判的 80 人里，76 人以贷款诈骗罪判 1 年 4 个月到 6 年 6 个月并处罚金，另有 4 人因替团伙取现被以贷款诈骗罪、洗钱罪数罪并罚，判 2 年 4 个月到 7 年 6 个月（全国，骗取贷款罪按刑法修正案（十一）2021 年 3 月起的文本）","grade":"A","src":"全国人大常委会 (2020). 刑法修正案（十一）（第十一条，修改刑法第一百七十五条之一）. <https://www.spp.gov.cn/spp/fl/202012/t20201227_503700.shtml>；全国人大 (1997). 刑法（第八十八、一百九十三、二百八十条）. <https://www.spp.gov.cn/spp/fl/201802/t20180206_364975.shtml>；最高人民检察院、公安部 (2022). 关于公安机关管辖的刑事案件立案追诉标准的规定（二）（第二十二、四十五条）. <https://www.spp.gov.cn/spp/xwfbh/wsfbt/202204/t20220429_555906.shtml>；最高人民检察院 (2026). 骗贷流水线背后藏洗钱黑手（检察日报）. <https://www.spp.gov.cn/spp/zdgz/202604/t20260428_726494.shtml>；全国人大常委会 (2012). 出境入境管理法（第十二条）. <https://www.nia.gov.cn/n741440/n741547/c1013311/content.html>（国家移民管理局）；全国人大常委会 (2023 修正). 民事诉讼法（第二百六十六条）. <https://amr.guizhou.gov.cn/zwgk/xxgkml/jcxxgk/zcfg/fl/202401/t20240129_83645867.html>（贵州省市场监管局转载）","note":"「我当时是想还的」在那个案子里没被采纳：检察机关查明这些人无工作、无固定资产，根本无力还款，分成又都花掉了，据此认定有非法占有目的；替团伙把钱取出来，还可能另外构成洗钱罪。钱贷在谁名下、合同谁签的字，谁就是借款人，就算不构成犯罪，债和征信记录也是自己的。拿了钱跑到境外一样不了结：立案侦查后逃避侦查或者审判的不受追诉期限限制；被判处刑罚尚未执行完毕、身为犯罪嫌疑人或被告人的不准出境，有未了结的民事案件法院可以决定不准出境，被执行人不履行的法院可以采取或者通知有关单位协助采取限制出境。替人取现转账见本节第 5 条（「兼职」要你用自己的卡），被冒名贷款怎么发现见第 8 节第 8 条。","money":"0","time":"少","will":"否","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"极高"},{"id":"9.7","sec":9,"n":7,"title":"捡到银行卡不取钱，捡到手机、钱包联系失主或交给警察，不揣走","cost":"0 元；打个电话或送到派出所","human":"捡到东西占为己有、数额较大又拒不交出，判 2 年以下，数额巨大 2 到 5 年。捡到的银行卡去 ATM 取钱更重，算冒用他人信用卡，数额较大判 5 年以下并罚 2 万到 20 万元，数额巨大 5 到 10 年并罚 5 万到 50 万元；而且这一种是警察直接立案的，不用失主自己去起诉。","gain":"拾得遗失物应当返还权利人，及时通知领取或送交公安等部门；把他人遗忘物占为己有、数额较大拒不交出的构成侵占罪，判 2 年以下，数额巨大 2 到 5 年；拾得他人信用卡在 ATM 上使用属于「冒用他人信用卡」，构成犯罪的按信用卡诈骗罪处理，数额较大判 5 年以下并罚 2 万到 20 万元，数额巨大或有其他严重情节 5 到 10 年并罚 5 万到 50 万元（全国）","grade":"A","src":"全国人大 (2020). 民法典（第三百一十四条）. <https://www.spp.gov.cn/spp/fl/202006/t20200602_463888.shtml>；全国人大 (2020). 刑法（根据刑法修正案（十一）修正，第一百九十六、二百七十条）. <https://jtgl.beijing.gov.cn/jgj/jgxx/flfg/fl/11033925/index.html>；最高人民检察院 (2008). 关于拾得他人信用卡并在自动柜员机（ATM 机）上使用的行为如何定性问题的批复. <https://www.spp.gov.cn/spp/flfg/sfjs/201208/t20120830_47871.shtml>","note":"侵占罪「告诉的才处理」，要失主自己去法院起诉，但拿捡来的卡取钱是公诉案件，警察会直接立案；「数额较大」的具体金额由司法解释规定，本节未核实。捡到的东西送交后，失主领取时要付保管费用（民法典第三百一十七条）。","money":"0","time":"少","will":"否","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"极高"},{"id":"9.8","sec":9,"n":8,"title":"优惠用自己的真实身份领，不买虚拟号批量注册小号，不靠漏洞重复领","cost":"0 元；放弃「羊毛任务群」里的活，发现平台漏洞就不碰，别把优惠当成可以批量复制的收入","human":"正常参加活动、用自己的号领一次券不在处罚范围里；为了多领而批量注册假用户、自己下单自己接单，按诈骗办——骗到 3000 元就够判 3 年以下，3 万元起判 3 到 10 年，50 万元以上 10 年起步，刷到 9 万余元就落在 3 到 10 年这一档。外卖骑手用 0.1 元一个的虚拟号注册新用户，领满 29 减 15 的券下单再把商品倒卖套现，刷到 9 万余元，同案 12 人判了 3 年 6 个月到拘役 3 个月。「是他系统有漏洞」不管用：有人靠退款和回收虚拟抽奖币的时间差白拿 224 件手办、24.9 万元，判 3 年缓 4 年，退赃加罚金交了 33 万。人多也不等于法不责众，网约车刷单那批起诉的 163 人全部判刑，34 个情节轻微没起诉的也被移送行政处罚。","gain":"诈骗公私财物数额较大的判 3 年以下并处或单处罚金，数额巨大或有其他严重情节 3 到 10 年并处罚金，特别巨大或有其他特别严重情节 10 年以上或无期并处罚金或没收财产；数额较大、巨大、特别巨大分别是 3000 元至 1 万元以上、3 万元至 10 万元以上、50 万元以上，各省在这个幅度内定本地标准；把方法教给别人、卖「教程」的按传授犯罪方法罪判 5 年以下，情节严重 5 到 10 年，特别严重 10 年以上或无期；买卖手机号、验证码的上下游按侵犯公民个人信息罪判 3 年以下，特别严重 3 到 7 年；使用批量账号、网络地址自动切换系统和批量接收短信验证的接码平台，本身就在反电信网络诈骗法第十四条的禁止之列，非法买卖、出租、出借电话卡和互联网账号、提供实名核验帮助在第三十一条之列，违反前者没收违法所得并处 1 到 10 倍罚款、没有违法所得或不足 5 万元的处 50 万元以下罚款、情节严重并处 15 日以下拘留，违反后者罚款同为 1 到 10 倍、没有违法所得或不足 2 万元的处 20 万元以下罚款、情节严重并处 15 日以下拘留；参与电信网络诈骗尚不构成犯罪的，拘留 10 到 15 日，没收违法所得并处 1 到 10 倍罚款，没有违法所得或不足 1 万元的处 10 万元以下罚款；官方案例：外卖骑手刘某某以 0.1 元一个买虚拟手机号注册某平台新用户，领取满 29 减 15 的新人券下单后把商品倒卖给小商铺套现，又用虚拟号互相邀请领 2 元至 20 元奖励金，与骑手谭某某分别骗得 9 万余元和 7 万余元，上海杨浦区检察院以诈骗罪起诉 12 人，法院判 3 年 6 个月至拘役 3 个月；王某利用网店退款与回收虚拟抽奖币的时间差，退款 1156 笔、提走手办 224 件、金额 24.9 万余元并在二手平台变现，以诈骗罪判 3 年缓 4 年并处罚金 3 万元（审理期间退赃并预缴罚金共 33 万元）；某网约车平台的新用户优惠券和司机补贴被「自己打车自己接单」的虚假跑单骗取，涉及 19 省 70 余市、金额 200 余万元，辽宁朝阳龙城区检察院起诉 163 人全部被判有罪，主犯黄某、蔡某以诈骗罪、侵犯公民个人信息罪、传授犯罪方法罪数罪并罚各判 3 年 6 个月，另有 34 名情节轻微的从犯相对不起诉、仍被移送公安作行政处罚（全国）","grade":"A","src":"全国人大 (2020). 刑法（根据刑法修正案（十一）修正，第二百五十三条之一、第二百六十六条、第二百九十五条）. <https://jtgl.beijing.gov.cn/jgj/jgxx/flfg/fl/11033925/index.html>（北京市公安交通管理局转载）；最高人民法院、最高人民检察院 (2011). 关于办理诈骗刑事案件具体应用法律若干问题的解释（法释〔2011〕7 号，第一条）. <https://www.spp.gov.cn/spp/sfjs/201802/t20180201_363736.shtml>；全国人大常委会 (2022). 反电信网络诈骗法（第十四、三十一、三十八、四十二、四十四条）. <https://www.spp.gov.cn/spp/fl/202209/t20220902_575631.shtml>；全国人大 (2020). 民法典（第九百八十五条）. <https://www.spp.gov.cn/spp/fl/202006/t20200602_463888.shtml>；最高人民检察院 (2021). 剑指电信网络诈骗｜不法分子盯上了电商经济的漏洞（检察日报）. <https://www.spp.gov.cn/spp/zdgz/202106/t20210607_520557.shtml>；最高人民检察院 (2025). 如此「薅羊毛」涉嫌诈骗（检察日报）. <https://www.spp.gov.cn/spp/zdgz/202508/t20250826_704625.shtml>；最高人民检察院 (2024). 辽宁朝阳龙城区：办理系列电信网络诈骗案（法治日报）. <https://www.spp.gov.cn/spp/zdgz/202401/t20240124_641099.shtml>","note":"界线不在「薅了多少」，在有没有虚构——用自己的真实身份参加活动、一个号领一次、券用在自己身上，那是平台给的优惠；为了多领去注册假用户、虚构交易、隐瞒已经退款的事实，就是让对方基于错误认识交付财物，按诈骗认定，金额只决定判多久。金额不够刑事标准的也不是白玩：平台可以封号、扣回优惠，并按不当得利要求返还，参与电诈未达犯罪程度的还有拘留和罚款那一档。「群里有人带、按单给我钱」不改变自己这一份的定性，把方法教给别人、倒卖账号和手机号是另外的罪名，还会数罪并罚。受益人是你自己。写脚本、卖脚本见第 11 节第 3 条，卖卡卖账号见第 8 节第 7 条和本节第 16 条（身份证不借人）。","money":"0","time":"少","will":"些","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"9.9","sec":9,"n":9,"title":"阳台、窗户不往外扔任何东西，烟头、垃圾袋、酒瓶都算","cost":"0 元","human":"往楼下扔东西，没砸到人也能拘留 5 日、罚 1000 元，情节严重拘留 10 到 15 日，构成高空抛物罪判 1 年以下。砸到人就换罪名了：有人在 21 楼酒后把空酒瓶、玻璃杯扔到楼下操场，砸中 13 岁学生致重伤，判 10 年；还有人从 32 楼扔 8 块砖头砸死 1 人，2024 年被核准死刑。","gain":"从建筑物或其他高空抛掷物品，有危害他人人身、财产或公共安全危险的，拘留 5 日以下或罚 1000 元以下，情节严重拘留 10 到 15 日并可罚 1000 元以下；情节严重的构成高空抛物罪，判 1 年以下并处或单处罚金；砸伤砸死人的按更重的罪名处理，官方案例：李某晨在 21 楼酒后把空酒瓶、玻璃杯扔到楼下操场，砸中 13 岁学生致重伤二级，以危险方法危害公共安全罪判 10 年；周某从 32 楼向人群投掷 8 块砖头砸死 1 人，2024 年最高法核准死刑（全国）","grade":"A","src":"全国人大常委会 (2025). 治安管理处罚法（2025 年修订，第四十三条）. <https://www.spp.gov.cn/spp/fl/202506/t20250627_699863.shtml>；全国人大常委会 (2020). 刑法修正案（十一）（第三十三条，即刑法第二百九十一条之二）. <https://www.spp.gov.cn/zdgz/202012/t20201227_503682.shtml>；全国人大 (2020). 刑法（根据刑法修正案（十一）修正，第二百九十一条之二）. <https://jtgl.beijing.gov.cn/jgj/jgxx/flfg/fl/11033925/index.html>；最高人民法院 (2024). 依法惩治危害公共安全犯罪典型案例（案例一）. <https://www.court.gov.cn/zixun/xiangqing/429522.html>；最高人民法院 (2025). 专访最高法副院长李勇：让高空抛物行为人都能被处罚. <https://www.court.gov.cn/zixun/xiangqing/458381.html>","note":"没砸到人也能拘留，条文只要求「有危险」。民法典对高空抛物另有民事赔偿条款（第一千二百五十四条），本节未能打开原文，未引用。","money":"0","time":"少","will":"否","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"极高"},{"id":"9.10","sec":9,"n":10,"title":"不网购仿真枪、钢珠枪、气枪，不买来路不明的「玩具枪」","cost":"0 元；想打枪去正规射击馆","human":"网购的钢珠枪、气枪只要枪口比动能到 1.8 焦耳/平方厘米就按枪支认定，非法持有判 3 年以下，情节严重 3 到 7 年。有对夫妇在集贸市场卖「玩具枪」，起获 43 支里 18 支经鉴定符合枪支标准，因为拿不出充分证据证明他们知道是枪才存疑不起诉——成年人特意上网买这种枪，事后说不知道很难成立。","gain":"非法持有、私藏枪支的判 3 年以下，情节严重 3 到 7 年；不能发射制式弹药的非制式枪支，枪口比动能大于等于 1.8 焦耳/平方厘米一律认定为枪支，不少网购的钢珠枪、气枪超过这个数；2018 年起两高要求对低比动能气枪综合外观、材质、价格、用途、主观认知等评估再定罪，官方案例：赵某某夫妇在集贸市场卖「玩具枪」，起获 43 支，18 支经鉴定符合枪支标准，因无充分证据证明其明知是枪支，存疑不起诉（全国）","grade":"A","src":"全国人大 (2020). 刑法（根据刑法修正案（十一）修正，第一百二十八条）. <https://jtgl.beijing.gov.cn/jgj/jgxx/flfg/fl/11033925/index.html>；最高人民法院、最高人民检察院 (2018). 关于涉以压缩气体为动力的枪支、气枪铅弹刑事案件定罪量刑问题的批复（法释〔2018〕8 号）. <https://www.spp.gov.cn/xwfbh/wsfbt/201803/t20180328_372604.shtml>；最高人民法院 (2018). 《批复》的理解与适用. <https://www.court.gov.cn/zixun/xiangqing/88472.html>","note":"不起诉的关键是「不明知」，成年人特意网购钢珠枪、气枪再说不知道是枪，很难成立。弩和管制刀具的管理规定本节未核实原文，未写。","money":"0","time":"少","will":"否","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"极高"},{"id":"9.11","sec":9,"n":11,"title":"买了无人机先实名登记，机场、军事区和城市管制空域不飞，不破解限高","cost":"登记 0 元，几分钟；每次起飞前用官方渠道查一下空域","human":"不实名登记就飞罚 200 元以下，情节严重罚 2000 到 2 万元；未经批准在管制空域飞罚 500 元以下，情节严重没收无人机并罚 1000 到 1 万元，情节较重还能拘留 5 到 10 日。有人付费破解限高把无人机飞到近 3000 米拍云层并发到网上，拘留 5 日；替人破解限高和禁飞区 20 多台次、挣 1.5 万多的，判 6 个月缓 1 年并处罚金。","gain":"未实名登记就飞的，责令改正并可罚 200 元以下，情节严重罚 2000 到 2 万元；未经批准在管制空域飞微型、轻型、小型无人机的，责令停止飞行并可罚 500 元以下，情节严重没收无人机并罚 1000 到 1 万元；违反空域管理规定飞行情节较重的拘留 5 到 10 日；官方案例：李某某付费破解限高后把无人机飞到近 3000 米拍云层并发布，拘留 5 日；张某某替人破解限高和禁飞区限制 20 余台次、获利 1.5 万余元，以提供侵入、非法控制计算机信息系统程序、工具罪判 6 个月缓刑 1 年并处罚金（全国，2024 年 1 月起）","grade":"A","src":"国务院、中央军委 (2023). 无人驾驶航空器飞行管理暂行条例（国令第 761 号，第十、十九、四十七、五十一条）. <https://www.gov.cn/zhengce/content/202306/content_6888799.htm>；全国人大常委会 (2025). 治安管理处罚法（2025 年修订，第四十六条）. <https://www.spp.gov.cn/spp/fl/202506/t20250627_699863.shtml>；湖北省公安厅 (2026). 公安部公布依法打击无人机「黑飞」违法犯罪八起典型案例（转载人民公安报）. <http://gat.hubei.gov.cn/bmdt/gayw/202602/t20260205_5870949.shtml>","note":"微型（空机重量小于 0.25 千克）、轻型无人机在适飞空域不需要批准，但适飞空域是「管制空域以外」，机场、军事设施、政府机关周边多属管制空域。公安部原文页面本节写作时无法打开，引用的是湖北省公安厅转载页。","money":"0","time":"少","will":"否","level":"中","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"9.12","sec":9,"n":12,"title":"不偷拍别人，不在出租屋、民宿、酒店房间装摄像头","cost":"0 元","human":"偷窥、偷拍、散布他人隐私，拘留 5 日以下或罚 1000 元以下，情节较重拘留 5 到 10 日；用专门的窃照器材造成严重后果判 2 年以下。有两人网购窃照器材装进三家酒店的多个房间远程偷拍，分别判 1 年 3 个月和 1 年；偷拍的东西再拿去卖或传播是另外的罪名。自己家装监控不算，装在别人使用的房间里就算。","gain":"偷窥、偷拍、窃听、散布他人隐私的，拘留 5 日以下或罚 1000 元以下，情节较重拘留 5 到 10 日并可罚 1000 元以下；非法使用窃听、窃照专用器材造成严重后果的，判 2 年以下；官方案例：颜某平、颜某建网购窃照器材装进三家酒店多个房间远程偷拍，分别判 1 年 3 个月和 1 年（全国）","grade":"A","src":"全国人大常委会 (2025). 治安管理处罚法（2025 年修订，第五十条）. <https://www.spp.gov.cn/spp/fl/202506/t20250627_699863.shtml>；全国人大 (2020). 刑法（根据刑法修正案（十一）修正，第二百八十四条）. <https://jtgl.beijing.gov.cn/jgj/jgxx/flfg/fl/11033925/index.html>；最高人民法院 (2024). 依法惩治非法生产、销售、使用窃听、窃照设备犯罪典型案例（案例二）. <https://www.court.gov.cn/shenpan/xiangqing/449581.html>","note":"偷拍内容一旦贩卖或传播，另按制作、贩卖淫秽物品牟利等罪处理，同批案例里有判 10 年的。自己家装监控不算，装在别人使用的房间就是。","money":"0","time":"少","will":"否","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"极高"},{"id":"9.13","sec":9,"n":13,"title":"麻将、扑克可以打，不抽头、不当庄、不组局收钱，不玩网络赌博","cost":"0 元；亲友之间小额娱乐可以，不从局里抽成","human":"亲友小额打牌不管，从局里抽头、当庄、组局收钱就变了性质：参与赌博赌资较大拘留 5 日以下或罚 1000 元以下，情节严重拘留 10 到 15 日并罚 1000 到 5000 元；聚众赌博或以赌博为业判 3 年以下，开赌场判 5 年以下，情节严重 5 到 10 年。多少算「赌资较大」各地自己掌握，没有全国统一数字。","gain":"以营利为目的为赌博提供条件，或参与赌博赌资较大的，拘留 5 日以下或罚 1000 元以下，情节严重拘留 10 到 15 日并罚 1000 到 5000 元；以营利为目的聚众赌博或以赌博为业的判 3 年以下并处罚金；开设赌场判 5 年以下并处罚金，情节严重 5 到 10 年（全国）","grade":"B","src":"全国人大常委会 (2025). 治安管理处罚法（2025 年修订，第八十二条）. <https://www.spp.gov.cn/spp/fl/202506/t20250627_699863.shtml>；全国人大 (2020). 刑法（根据刑法修正案（十一）修正，第三百零三条）. <https://jtgl.beijing.gov.cn/jgj/jgxx/flfg/fl/11033925/index.html>；全国人大常委会 (2020). 刑法修正案（十一）（第三十六条，开设赌场刑期提高到五年以下、五年以上十年以下）. <https://www.spp.gov.cn/zdgz/202012/t20201227_503682.shtml>","note":"「赌资较大」没有全国统一数字，由各地掌握，故定 B 级；抽头、替网络赌博平台代收投注在实务中常按开设赌场处理，相关司法解释原文本节未核实。未找到官方案例。","money":"0","time":"少","will":"些","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"9.14","sec":9,"n":14,"title":"不吃野味，不买卖、不养保护动物当宠物","cost":"0 元；宠物只买有合法来源、人工繁育的品种","human":"吃国家重点保护动物，东西没收再罚它价值的 2 到 20 倍；收购、运输、出售珍贵濒危动物判 5 年以下，情节严重 5 到 10 年，特别严重 10 年以上。人工繁育的宠物另说：3 个养殖户卖了 40 多只人工繁育的费氏牡丹鹦鹉、总价不到 400 元，检察院不起诉。野外抓的、来路不明的不适用。","gain":"食用或为食用购买国家重点保护野生动物的，没收并罚价值 2 到 20 倍；无许可证繁育国家重点保护野生动物的，没收并罚 1 到 10 倍；非法收购、运输、出售国家重点保护的珍贵、濒危野生动物及其制品的判 5 年以下并处罚金，情节严重 5 到 10 年，特别严重 10 年以上；以食用为目的猎捕、收购、运输、出售其他陆生野生动物情节严重的判 3 年以下；官方案例：养殖户王某等 3 人卖 40 余只人工繁育的费氏牡丹鹦鹉（国家二级保护），总价不到 400 元，2021 年检察院不起诉；2022 年起两高明确人工繁育技术成熟、已成规模、作为宠物买卖运输的一般不作为犯罪处理（全国）","grade":"A","src":"全国人大常委会 (2022). 野生动物保护法（2022 年修订，第三十一、五十一、五十三条）. <https://www.mee.gov.cn/ywgz/fgbz/fl/202302/t20230220_1016885.shtml>（生态环境部转载）；全国人大 (2020). 刑法（根据刑法修正案（十一）修正，第三百四十一条）. <https://jtgl.beijing.gov.cn/jgj/jgxx/flfg/fl/11033925/index.html>；全国人大常委会 (2020). 刑法修正案（十一）（第四十一条，即刑法第三百四十一条第三款）. <https://www.spp.gov.cn/zdgz/202012/t20201227_503682.shtml>；最高人民法院、最高人民检察院 (2022). 关于办理破坏野生动物资源刑事案件适用法律若干问题的解释（法释〔2022〕12 号，第十三条）. <https://www.spp.gov.cn/spp/xwfbh/wsfbt/202204/t20220407_553506.shtml>；最高人民检察院 (2023). 鹦鹉小案 民生大案. <https://www.spp.gov.cn/spp/zdgz/202302/t20230211_601023.shtml>","note":"「一般不作为犯罪」只针对人工繁育、宠物类，野外抓的、来路不明的不适用；哪些算国家重点保护动物以名录为准，买之前查名录比事后解释便宜。","money":"0","time":"少","will":"否","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"极高"},{"id":"9.15","sec":9,"n":15,"title":"要债不扣人、不关人、不跟到家里赖着不让走","cost":"0 元；欠钱不还去法院起诉，借条怎么写见第 8 节第 16 条","human":"钱是真欠你的也不行，法条专门写了「为索取债务」扣人、关人照样按非法拘禁办。行政上拘留 10 到 15 日并罚 1000 到 2000 元；构成非法拘禁罪判 3 年以下，把人弄成重伤 3 到 10 年，出了人命 10 年以上。要债去法院起诉。","gain":"非法限制他人人身自由、非法侵入他人住宅或非法搜查他人身体的，拘留 10 到 15 日并罚 1000 到 2000 元，情节较轻拘留 5 到 10 日并罚 1000 元以下；非法拘禁判 3 年以下、拘役、管制或剥夺政治权利，致人重伤 3 到 10 年，致人死亡 10 年以上；为索取债务扣押、拘禁他人的按同样规定处罚，债是真的也一样（全国）","grade":"A","src":"全国人大常委会 (2025). 治安管理处罚法（2025 年修订，第四十七条）. <https://www.spp.gov.cn/spp/fl/202506/t20250627_699863.shtml>；全国人大 (2020). 刑法（根据刑法修正案（十一）修正，第二百三十八条）. <https://jtgl.beijing.gov.cn/jgj/jgxx/flfg/fl/11033925/index.html>","note":"「他欠我钱」在这条里不是抗辩理由，法条专门写了「为索取债务」也按非法拘禁处理。中国法院网上有多起讨合法债务把人关起来被判 7 个月到 1 年的案例，本节写作时该站无法打开，未引用。","money":"0","time":"少","will":"些","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"9.16","sec":9,"n":16,"title":"身份证不借人，不用别人的身份证，也不拿别人的证件登记、开卡、买票","cost":"0 元；拒绝就行，需要复印件的写明用途","human":"把身份证出租、出借、转让，警告并罚 200 元以下；冒用别人的身份证或用骗领的身份证，罚 200 到 1000 元或者拘留 10 日以内；在必须实名的场合用伪造、变造或者盗用别人的身份证、护照、社保卡、驾驶证，情节严重的判拘役或管制还要罚钱。用别人的证件买火车票、住店，就属于这类场合。","gain":"出租、出借、转让居民身份证的，警告并罚 200 元以下；冒用他人身份证或使用骗领的身份证，购买、出售、使用伪造变造身份证的，罚 200 到 1000 元或拘留 10 日以下；在按国家规定应当提供身份证明的活动中使用伪造、变造或盗用他人的身份证、护照、社保卡、驾驶证等，情节严重的判拘役或管制并处或单处罚金（全国）","grade":"A","src":"全国人大常委会 (2011). 居民身份证法（2011 年修正，第十六、十七条）. <https://jtgl.beijing.gov.cn/jgj/jgxx/flfg/fl/203777/index.html>（北京市公安交通管理局转载）；全国人大 (2020). 刑法（根据刑法修正案（十一）修正，第二百八十条之一）. <https://jtgl.beijing.gov.cn/jgj/jgxx/flfg/fl/11033925/index.html>","note":"身份证借出去被拿去注册公司、办卡的后果见第 8 节第 26、7 条（别当挂名法人、不把银行卡借给人）。用别人身份证买火车票、住店属于「应当提供身份证明的活动」。未找到官方案例。","money":"0","time":"少","will":"否","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"极高"},{"id":"9.17","sec":9,"n":17,"title":"被警察拦下或带走时配合，不推、不打、不抢执法记录仪，喝了酒更要忍","cost":"0 元；有异议事后投诉、复议、起诉，现场不动手","human":"现场阻碍执法，警告或罚 500 元以下，情节严重拘留 5 到 10 日。对警察动手是另一档：撕咬、掌掴、踢打、抱摔、扔东西造成轻微伤以上就算暴力袭警，判 3 年以下，用枪支、管制刀具或开车撞的判 3 到 7 年；甩手、挣脱这类一般抗拒不算。推搡、拉扯、抢执法记录仪这些动作都可能被认定成暴力袭警。","gain":"阻碍国家机关工作人员依法执行职务的，警告或罚 500 元以下，情节严重拘留 5 到 10 日并可罚 1000 元以下，阻碍人民警察的从重；暴力袭击正在依法执行职务的人民警察判 3 年以下，用枪支、管制刀具或驾车撞击等严重危及其人身安全的判 3 到 7 年；撕咬、掌掴、踢打、抱摔、投掷物品造成轻微伤以上的就算「暴力袭击」，甩手、挣脱、蹬腿等一般性抗拒不算（全国）","grade":"A","src":"全国人大常委会 (2025). 治安管理处罚法（2025 年修订，第六十一条）. <https://www.spp.gov.cn/spp/fl/202506/t20250627_699863.shtml>；全国人大常委会 (2020). 刑法修正案（十一）（第三十一条，即刑法第二百七十七条第五款）. <https://www.spp.gov.cn/zdgz/202012/t20201227_503682.shtml>；全国人大 (2020). 刑法（根据刑法修正案（十一）修正，第二百七十七条）. <https://jtgl.beijing.gov.cn/jgj/jgxx/flfg/fl/11033925/index.html>；最高人民法院、最高人民检察院 (2025). 关于办理袭警刑事案件适用法律若干问题的解释（高检发释字〔2025〕1 号，第一、八、十二条）. <https://www.spp.gov.cn/xwfbh/wsfbt/202501/t20250116_679579.shtml>；最高人民检察院 (2021). 袭警罪入刑一月 检察机关批捕 405 人. <https://www.spp.gov.cn/xwfbh/wsfbh/202105/t20210517_518308.shtml>","note":"最高检 2021 年通报，袭警罪入刑一个月批捕 405 人，江苏 42 件里酒后滋事引发的占 47.6%，湖北 16 件里 12 件是拳打脚踢、撕咬等轻微暴力；对辅警动手按妨害公务罪处理。未找到写明个人案情的官方案例。","money":"0","time":"少","will":"些","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"9.18","sec":9,"n":18,"title":"对方不满 14 岁就不能发生关系，「她同意」不是理由","cost":"0 元；不确定年龄就不做","human":"对方不满 14 岁，无论她是否同意都以强奸论并从重，基本刑就是 3 到 10 年。不满 12 岁的一律认定你「应当知道」；12 到 14 岁的，只要从身体发育、言谈举止、衣着能看出可能是幼女仍然实施，就认定「明知」，「确实不知道」的例外把握得很严。","gain":"奸淫不满 14 周岁幼女的以强奸论、从重处罚，基本刑 3 到 10 年；最高法的口径：以暴力、胁迫等强制手段的，不论是否明知是幼女都定强奸罪；非强制手段的，对不满 12 周岁一律认定「应当知道」，12 到 14 周岁从身体发育、言谈举止、衣着等能看出可能是幼女仍实施性侵害的认定「明知」，「确实不知道」的例外从严把握（全国）","grade":"A","src":"全国人大 (2020). 刑法（根据刑法修正案（十一）修正，第二百三十六条）. <https://jtgl.beijing.gov.cn/jgj/jgxx/flfg/fl/11033925/index.html>；最高人民法院 (2015). 关于「与十四周岁以下幼女发生性关系是否要明知才构成犯罪」的答复. <https://www.court.gov.cn/hudong/xiangqing/13363.html>","note":"两高两部关于办理性侵害未成年人刑事案件的意见原文和最高法 2003 年批复页面本节未能打开，「明知」的认定标准引自最高法官网答复；法条用语为「幼女」，本条对行为人性别不作区分。","money":"0","time":"少","will":"否","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"极高"},{"id":"9.19","sec":9,"n":19,"title":"动手打人前算清这笔账：拘留、赔钱、判刑","cost":"0 元；忍住那几秒钟","human":"动手一次的账：拘留 5 到 10 日加罚 500 到 1000 元；结伙打、打老人孕妇小孩或一次打几个人，拘留 10 到 15 日加罚 1000 到 2000 元；打成轻伤就是刑事案件，判 3 年以下，重伤 3 到 10 年。钱另算：有人打断对方三根肋骨，赔了 11.3 万元和解才没被起诉；另一人打断对方桡骨没赔，判了 10 个月。","gain":"殴打他人或故意伤害的，拘留 5 到 10 日并罚 500 到 1000 元；结伙、打残疾人孕妇老人小孩、多次或一次打多人的，拘留 10 到 15 日并罚 1000 到 2000 元；打成轻伤就是故意伤害罪，3 年以下有期徒刑、拘役或管制，重伤 3 到 10 年；民事上要赔医疗费、误工费、护理费、交通费、住院伙食补助费、营养费，致残的残疾赔偿金按受诉法院所在地上年度城镇居民人均可支配收入乘 20 年（60 岁以上每多一岁减一年，75 岁以上按 5 年）；2022 年全国检察机关受理轻伤害案件 7 万余件，多因婚姻家庭邻里纠纷或偶然事件引发；最高检典型案例：卢某打断对方三根肋骨（轻伤二级），赔 11.3 万元达成和解才获不起诉；石某打断对方桡骨（轻伤二级）没赔，判有期徒刑十个月（全国，治安管理处罚法 2026 年 1 月 1 日起施行）","grade":"A","src":"全国人大常委会 (2025). 治安管理处罚法（2025 年修订，第九、五十一条）. <https://www.spp.gov.cn/spp/fl/202506/t20250627_699863.shtml>；全国人大 (1997). 刑法（第二百三十四条）. <https://www.spp.gov.cn/spp/fl/201802/t20180206_364975.shtml>；最高人民法院 (2022 修正). 关于审理人身损害赔偿案件适用法律若干问题的解释（法释〔2022〕14 号，第六至十二、十五条）. <https://www.court.gov.cn/zixun/xiangqing/357071.html>；最高人民检察院、公安部 (2023). 关于依法妥善办理轻伤害案件的指导意见. <https://www.spp.gov.cn/spp/xwfbh/wsfbt/202303/t20230302_604352.shtml>；最高人民检察院 (2023). 检察机关依法妥善办理轻伤害案件典型案例. <https://www.spp.gov.cn/xwfbh/dxal/202303/t20230302_605116.shtml>","note":"怎么避免冲突、先动手吃亏和正当防卫见第 8 节第 9 条，本条只算账，为泄愤对人下手的账见第 8 节第 10 到 13 条。因民间纠纷引起、情节较轻的打架公安可以调解，轻伤害案件和解并履行的可以从宽甚至不起诉，但赔的钱一分不少；伤到多重算轻伤由鉴定标准定，本节未核实。误工费、护理费按实际收入和天数算，没有统一数字。","money":"0","time":"少","will":"些","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"9.20","sec":9,"n":20,"title":"孩子生下来养不了，只有民政登记这一条合法出路：收钱把孩子给人可能按拐卖罪判，扔下不管是遗弃罪","cost":"0 元；到县级以上民政部门办收养登记，交材料、等审核和收养评估","human":"养不了有出路，但合法的只有一条：由民政部门办收养登记，收养关系从登记那天才成立；能当送养人的是孤儿的监护人、儿童福利机构，以及「有特殊困难无力抚养子女的生父母」。私下把孩子给人、尤其是收了钱，可能从「送养」直接变成拐卖儿童罪，起刑 5 年以上，情节特别严重的到死刑。官方划的线是「有没有非法获利的目的」：生完就卖的、明知对方没有抚养目的或者根本不管对方能不能养就为收钱把孩子「送」人的、收了明显不属于营养费感谢费的巨额钱财的，都算出卖亲生子女。反过来，确实迫于生活困难私自送养、只收少量营养费感谢费的，属于民间送养，不按拐卖办。把孩子扔下不管是遗弃罪，判 5 年以下；遗弃不管、拒不抚养的，情节恶劣就是遗弃罪。","gain":"刑法第二百四十条：「拐卖妇女、儿童的，处五年以上十年以下有期徒刑，并处罚金」，有加重情形的处十年以上有期徒刑或者无期徒刑并处罚金或者没收财产，「情节特别严重的，处死刑，并处没收财产」。《关于依法惩治拐卖妇女儿童犯罪的意见》第 17 条：区分出卖亲生子女与民间送养「关键在于行为人是否具有非法获利的目的」，三种情形可以认定为出卖亲生子女并以拐卖妇女、儿童罪论处——「将生育作为非法获利手段，生育后即出卖子女的」「明知对方不具有抚养目的，或者根本不考虑对方是否具有抚养目的，为收取钱财将子女『送』给他人的」「为收取明显不属于『营养费』『感谢费』的巨额钱财将子女『送』给他人的」；不以非法获利为目的、迫于生活困难私自送养并收取少量营养费感谢费的，属民间送养，不以拐卖罪论处。刑法第二百六十一条：「对于年老、年幼、患病或者其他没有独立生活能力的人，负有扶养义务而拒绝扶养，情节恶劣的，处五年以下有期徒刑、拘役或者管制」。民法典第一千零九十四条：可以作送养人的是孤儿的监护人、儿童福利机构、有特殊困难无力抚养子女的生父母；第一千一百零五条：「收养应当向县级以上人民政府民政部门登记。收养关系自登记之日起成立」","grade":"A","src":"全国人大 (1997). 刑法（第二百四十、二百六十一条）. <https://www.spp.gov.cn/spp/fl/201802/t20180206_364975.shtml>；最高人民法院、最高人民检察院、公安部、司法部 (2010). 关于依法惩治拐卖妇女儿童犯罪的意见（法发〔2010〕7 号，第 17 条）. 最高人民法院官网 <https://www.court.gov.cn/fabu/xiangqing/977.html>；全国人大 (2020). 民法典（第一千零九十四、一千一百零五条）. 盐城市人民政府转载收养编全文 <https://xxgk.yczf.gov.cn/xzf/ycmzj/fdzdgknr/fgwj_41995/202112/t20211203_1506640.shtml>","note":"这条不谈要不要生，只解决生下来之后那个岔路口。顺序上省事的做法是：去医院生（产检和住院分娩见第 27 节），出生医学证明是后面所有手续的前提；要送养先找县级以上民政部门，别经由中间人，钱一旦过手，性质就可能变；产后一年内出现「有伤害自己或者伤害孩子的念头」按急症处理，见第 27 节第 7、16 条和第 1 节第 25 条。本条没有配案例：拐卖亲生子女的官方典型案例本轮未逐案核对，只引条文和意见原文。","money":"0","time":"中","will":"否","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"9.21","sec":9,"n":21,"title":"别伪造事故、别夸大损失骗理赔：这是保险诈骗罪，帮你作证、帮你修车、帮你鉴定的人一起算","cost":"0 元，只是不去做","human":"五种情形都在刑法第一百九十八条里：虚构保险标的、编造虚假的事故原因或者夸大损失程度、编造未曾发生的保险事故、故意造成财产损失的保险事故、故意造成被保险人死亡伤残疾病。数额较大判 5 年以下并处 1 万到 10 万元罚金，数额巨大 5 到 10 年，特别巨大 10 年以上。「找人帮忙」不是免责：鉴定人、证明人、财产评估人故意提供虚假证明文件的，以保险诈骗的共犯论处。安徽宣城那起案子里，除了主犯，王某信等 8 人因保险诈骗罪被判有期徒刑 4 年到 2 年、各并处罚金 1 万元，他们做的事是伪造车辆转让协议、拿它去法院打官司。文件要求承保和理赔两头都核验风险信息：按 2024 年的《反保险欺诈工作办法》，行业要建反欺诈信息平台对可疑数据集中筛查，承保端和理赔端都要核验风险信息，查出线索涉嫌犯罪的及时向公安机关报案，监管部门和公安、检察院、法院之间有案件移送和调查取证的衔接机制。","gain":"刑法第一百九十八条列五种情形：（一）投保人故意虚构保险标的；（二）投保人、被保险人或者受益人对发生的保险事故编造虚假的原因或者夸大损失的程度；（三）编造未曾发生的保险事故；（四）投保人、被保险人故意造成财产损失的保险事故；（五）投保人、受益人故意造成被保险人死亡、伤残或者疾病。数额较大处 5 年以下有期徒刑或者拘役并处 1 万元以上 10 万元以下罚金，数额巨大或有其他严重情节处 5 至 10 年并处 2 万至 20 万元罚金，数额特别巨大或有其他特别严重情节处 10 年以上并处 2 万至 20 万元罚金或者没收财产；末款：保险事故的鉴定人、证明人、财产评估人故意提供虚假的证明文件，为他人诈骗提供条件的，以保险诈骗的共犯论处。保险法第二十七条：未发生保险事故而谎称发生的，保险人有权解除合同并不退还保险费；以伪造、变造的证明资料或者编造虚假事故原因、夸大损失程度的，保险人对虚报部分不承担责任，已经支付的应当退回或者赔偿。案例：安徽宣城张某松案中，王某信等 8 人因保险诈骗罪被判处有期徒刑 4 年到 2 年不等，均并处罚金 1 万元；涉案的一起虚假诉讼中，保险公司定损 2 万元，其通过伪造车辆转让协议取得诉讼资格起诉，法院判赔 7 万余元，该生效民事判决于 2019 年 9 月 26 日经再审撤销。《反保险欺诈工作办法》要求：强化承保端和理赔端风险信息核验；探索建立多险种的行业反欺诈信息平台、反欺诈情报中心，对欺诈可疑数据集中筛查，线索交由行业协会、反欺诈组织和保险机构核查，涉嫌犯罪的及时向公安机关报案；金融监管总局及其派出机构应建立健全与公安机关、人民检察院、人民法院之间的行政执法与刑事司法衔接机制（全国，2024 年 7 月 31 日印发）","grade":"A","src":"全国人大常委会. 中华人民共和国刑法（经刑法修正案十一修正的整合文本）第一百九十八条. <https://flk.npc.gov.cn/detail?id=ff808181796a636a0179822a19640c92>；全国人大常委会 (2015 修正). 中华人民共和国保险法第二十七条. <https://flk.npc.gov.cn/detail?id=2c909fdd678bf17901678bf7c4060811>；国家金融监督管理总局 (2024). 关于印发《反保险欺诈工作办法》的通知. <https://www.gov.cn/gongbao/2024/issue_11586/202409/content_6975080.html>；安徽省人民检察院转载《法制日报》(2020-01-13). 杀妻骗保牵出案中案. <http://www.ah.jcy.gov.cn/jczt/jjslhyqkjc/mtjj/202001/t20200113_2758841.shtml>","note":"常见的几种自以为无害的做法都在这五项里：出了小事故找修理厂「多报一点」、把旧伤旧损算进这次、和朋友对撞一下再报案、没出事却编一个。车险该怎么买见第 5 节第 26 条（三者险买够）。涉及人命的那一档——给家人投保后故意造成其死亡——法条明确数罪并罚，见第 8 节第 36 条。医保这一侧是另一套规则（空刷医保卡、拿个人账户套现按诈骗办），见第 5 节第 13 条备注","money":"0","time":"少","will":"否","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"极高"},{"id":"9.22","sec":9,"n":22,"title":"不卖自己的器官，也别帮人找供体：肾到手 2 万多，同一枚转手卖 20 万，钱要被没收还要按交易额罚 10 到 20 倍","cost":"0 元，只是不去做","human":"合法的活体器官只能给配偶、直系血亲或者三代以内的旁系血亲，不满 18 周岁的人不得摘活体器官，所以「网上配型、当场给钱」这条路没有合法版本。钱的账：北京那起 51 枚肾脏、涉案 1034 万余元的案子里，供体拿到 2 万到 2.5 万，同一枚肾卖给患者是 18 万到 22 万；湖南 17 岁的王某为买苹果手机卖掉一个肾，出院时拿到 2.2 万，受体方付出去的是 15 万加 1 万美元，他术后肾功能不全，鉴定结论是重伤、三级伤残。身体那一侧的账更长：就算是筛查过、有随访的正规捐献者，剩下那个肾也要替两个肾干活，长期代价见第 1 节第 33 条，卖肾的人连筛查和随访都没有，见第 1 节第 33 条。法律的账：卖的人所得要被没收，再按交易额罚 10 到 20 倍，一枚肾按 20 万算就是 200 万到 400 万；拉人头、找供体找受体、联系医生的是组织出卖人体器官罪，判 5 年以下，情节严重 5 年以上，那起案子的组织者判了 12 年。手术台也不是医院的：摘肾点是每月 7500 元租来的四层小楼，团伙自己的护士长供述那地方脏乱不堪、连抢救设备都没有。","gain":"《人体器官捐献和移植条例》第五条「任何组织或者个人不得以任何形式买卖人体器官，不得从事与买卖人体器官有关的活动」；第十条「任何组织或者个人不得获取未满 18 周岁公民的活体器官用于移植」；第十一条「活体器官的接受人限于活体器官捐献人的配偶、直系血亲或者三代以内旁系血亲」；第三十七条：买卖人体器官或者从事与买卖人体器官有关活动的，由县级以上地方人民政府卫生健康部门没收违法所得，并处交易额 10 倍以上 20 倍以下的罚款，医务人员参与的吊销执业证书并终身禁止从事医疗卫生服务，构成犯罪的依法追究刑事责任（全国，2024 年 5 月 1 日起施行，原《人体器官移植条例》同时废止）。刑法第二百三十四条之一：「组织他人出卖人体器官的，处五年以下有期徒刑，并处罚金；情节严重的，处五年以上有期徒刑，并处罚金或者没收财产」；未经本人同意摘取其器官、摘取不满十八周岁的人的器官、强迫或者欺骗他人捐献器官的，依照刑法第二百三十四条、第二百三十二条（故意伤害、故意杀人）定罪处罚。案例一：北京市第一中级人民法院 2014 年 8 月 20 日终审的郑伟等 15 人案，51 枚肾脏、涉案金额 1034 万余元，供体「换来的仅仅是 2 万到 2.5 万元不等的报酬」，受体方的价码「以前是一个肾 18 万或 19 万，后来是 21 万或 22 万」，摘肾点是每月 7500 元租的四层小楼，团伙护士长供述该处「脏乱不堪，连抢救设备都没有」，组织者郑伟以组织出卖人体器官罪判处有期徒刑 12 年，其余 14 人判 3 年半至 9 年。案例二：最高人民检察院公布的「少年卖肾买苹果手机」案，17 岁的王某 2011 年 4 月 28 日晚在郴州一处由无移植资质医院科室承包人提供的场地被切除右肾，5 月 2 日出院时拿到 2.2 万元，受体方付给中介 15 万元人民币和 1 万美元，主犯获利 5.6 万余元，王某术后肾功能不全，「伤情构成重伤、三级伤残」","grade":"A","src":"国务院 (2023). 人体器官捐献和移植条例（国务院令第 767 号，第五、十、十一、三十七条）. <https://www.gov.cn/zhengce/zhengceku/202312/content_6920196.htm>；全国人大常委会. 中华人民共和国刑法（经刑法修正案十一修正的整合文本）第二百三十四条之一. <https://flk.npc.gov.cn/detail?id=ff808181796a636a0179822a19640c92>；最高人民检察院 (2012-04-09). 「少年卖肾买苹果手机」案诉至法院. <https://www.spp.gov.cn/gs/201204/t20120409_34342.shtml>；河北省廊坊市中级人民法院官网转载 (2014-09-02). 全国最大贩肾案终审 组织者摘肾 51 枚获利千万. <https://lfzy.hebeicourt.gov.cn/article/detail/2014/09/id/1430881.shtml>","note":"受益人是你自己。这笔交易的真实价格不是「一次性拿两万」，而是拿一个器官换一台手机：少年卖肾案的鉴定结论是重伤、三级伤残，不是休息几个月就好；那起案子检方认定 5 名被告人触犯刑法第二百三十四条第二款、以故意伤害罪起诉，理由之一是医务人员术前没有核实「供体」是不是未成年人就切了右肾；今天同样的事，拉人头的按组织出卖人体器官罪办，摘取不满十八周岁的人的器官仍依第二百三十四条按故意伤害罪定罪处罚。黑中介的手术在出租屋或借来的场地做，没有配型之外的评估、没有术后随访，出并发症找不到人认账。真想给亲人捐，走第十一条那条路，在有移植资质的医疗机构、经伦理委员会审查，全程不收钱；身后的遗体器官捐献是另一回事，无偿，不在本条范围。摘掉一个肾之后身体要付什么代价，见第 1 节第 33 条。缺钱到考虑卖器官时先看第 7 节的兜底渠道（失业保险、临时救助、低保），网贷和「包装材料」贷款的坑见本节第 6 条。","money":"0","time":"少","will":"否","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"极高"}]},{"n":10,"title":"恋爱和结婚划不划算","intro":"本节把「结婚划不划算」拆成几笔可以分开算的账：钱、时间、健康、法律风险和关系质量，每笔账只给官方统计或荟萃分析里能找到的数字，不做道德判断，也不替读者下结论；健康类数字按死亡风险口径，时间类数字按每日分钟口径，法律类按条文口径，三者不互相换算。拆账方法、填空清单和常见误区见 [docs/结婚划不划算.md](../docs/结婚划不划算.md)。","entries":[{"id":"10.1","sec":10,"n":1,"title":"认识更多人，而不是死磕一个：两个人合不合得来，见面之前预测不出来","cost":"0 元；把时间花在扩大认识面上，而不是反复琢磨同一个人","human":"两场闪电约会研究让人在见面前填了 100 多项择偶问卷，结果只能算出「这个人普遍容易喜欢别人」和「这个人普遍受欢迎」，唯独算不出「这两个具体的人之间来不来电」；连人自己说的理想型（看重外貌还是看重经济前景），也预测不了他现场对某个人的兴趣。合不合得来只有见了面才知道，所以把时间花在多认识几个人上，比押在一个人身上划算。","gain":"两场闪电约会研究里，参与者事先填了 100 多项与择偶有关的自陈量表，随机森林模型能预测「一个人整体上有多容易喜欢别人」（4%–18% 的方差）和「一个人整体上有多受欢迎」（7%–27%），但对「这两个具体的人之间来不来电」，用会前任何组合的特质与偏好都预测不出来。同一批研究者更早的一项闪电约会实验还发现，参与者会前自陈的理想型偏好（看重外貌还是看重经济前景），预测不了他们在现场对具体某个人的兴趣","grade":"A","src":"Joel S, Eastwick PW, Finkel EJ (2017). Is romantic desire predictable? Machine learning applied to initial romantic attraction. Psychological Science, 28(10), 1478-1489. <https://doi.org/10.1177/0956797617714580>；Eastwick PW, Finkel EJ (2008). Sex differences in mate preferences revisited: do people know what they initially desire in a romantic partner? Journal of Personality and Social Psychology, 94(2), 245-264. <https://doi.org/10.1037/0022-3514.94.2.245>","note":"这两项研究说的是「见面之前算不出来」，不是「怎么努力都没用」。既然合不合得来只能见了面才知道，那把成本花在多认识几个人、每个都真正见一面，就比把全部时间押在一个人身上更划算。都是欧美大学生样本，中国的婚恋市场结构不同，结论迁移要打折","money":"0","time":"中","will":"些","level":"中","lens":"时间","dispute":false,"todo":false,"ratio":"一般"},{"id":"10.2","sec":10,"n":2,"title":"对方明确拒绝之后就停下，继续纠缠是治安违法，不是「诚意」","cost":"0 元；忍住不再发消息、不再去等人","human":"对方明确拒绝之后还发消息、还去等人，2026 年 1 月起就是治安违法：拘留 5 日以下或罚 1000 元以下，情节较重拘留 5 到 10 日。公安还可以责令你一段时间内禁止接触对方，违反禁止接触的规定再拘留 5 到 10 日。- 收益：2026 年 1 月 1 日起施行的治安管理处罚法把纠缠、跟踪单列出来：「多次发送淫秽、侮辱、恐吓等信息或者采取滋扰、纠缠、跟踪等方法，干扰他人正常生活的」，处五日以下拘留或者一千元以下罚款，情节较重的处五日以上十日以下拘留，可以并处一千元以下罚款；而且这一项还多一层——经公安机关负责人批准，可以责令行为人在一定期限内禁止接触被侵害人，违反禁止接触规定的，再处五日以上十日以下拘留","gain":"","grade":"A","src":"全国人大常委会 (2025 修订). 治安管理处罚法（第五十条第一款第五项、第二款）. <https://www.spp.gov.cn/spp/fl/202506/t20250627_699863.shtml>（最高人民检察院转载）","note":"「死追到底会感动对方」没有任何研究支持，但拘留和禁止接触令是白纸黑字的。留下的记录还会影响考公、考编、政审和一部分职业的从业资格。追一个人和骚扰一个人的分界线不由你的动机决定，由对方是否已经明确表示拒绝决定","money":"0","time":"少","will":"是","level":"中","lens":"自由","dispute":false,"todo":false,"ratio":"一般"},{"id":"10.3","sec":10,"n":3,"title":"判断对方有没有兴趣，看行为不看「信号」：谁主动、谁安排、谁跟进","cost":"0 元；把注意力从解读表情、语气挪到记录事实","human":"让 52 对陌生男女聊十来分钟再互相判断有没有在调情，结果是「对方没在调情」判得比较准，「对方在调情」反而看不出来；换成 261 个人看一分钟视频判断，结论一样。所以别从表情语气反推心思，看可观察的行为：谁主动发起、谁安排下一次、你不推进时对方跟不跟进。","gain":"两项研究测了人识别调情的准确率：52 对互不相识的异性两两交谈 10 到 12 分钟后各自报告自己有没有在调情、觉得对方有没有在调情，结果是「没有发生调情的互动被判断得更准，发生了调情的互动反而判断得更差」；第二项用 26 段一分钟视频给 261 名旁观者判断，结论一致——人能比较可靠地看出「对方没在调情」，却很难看出「对方在调情」","grade":"B","src":"Hall JA, Xing C, Brooks S (2015). Accurately detecting flirting: error management theory, the traditional sexual script, and flirting base rate. Communication Research, 42(7), 939-958. <https://doi.org/10.1177/0093650214534972>","note":"争议。另有研究认为男性并非高估了女性的性意图，而是女性在自陈时低报了，双方到底谁的判断更准仍无定论（Perilloux C, Kurzban R (2015). Do men overperceive women's sexual interest? Psychological Science, 26(1), 70-77. <https://doi.org/10.1177/0956797614555727>）。但两派都同意一件事：从表情、语气这类细微线索反推对方心思，准确率很低。可观察的行为要可靠得多——是否主动发起、是否安排下一次、是否在你不推进时也跟进","money":"0","time":"少","will":"些","level":"中","lens":"时间","dispute":true,"todo":false,"ratio":"一般"},{"id":"10.4","sec":10,"n":4,"title":"关系好不好，主要看你自己在这段关系里的感受，不是看对方条件","cost":"0 元；把择偶清单换成对相处过程的观察","human":"29 个实验室、43 份配对追踪数据的分析里，最能说明关系好不好的全是当事人自己的感受——感觉到对方的承诺、欣赏、性满意度、感觉到对方满意、冲突多不多，而不是对方的条件；自己报告的这些东西，预测力是伴侣报告的二到四倍。但同一项研究也发现，这段关系往后是变好还是变坏，用任何自陈问卷都基本算不出来。","gain":"29 个实验室、43 份纵向配对数据的机器学习分析：预测关系质量最强的几个变量全部来自当事人对这段关系的感受——感觉到对方的承诺、欣赏、性满意度、感觉到对方满意、冲突；个体层面最强的是生活满意度、负面情绪、抑郁、回避型依恋、焦虑型依恋。关系变量能解释基线时最多 45% 的方差，研究结束时最多 18%。而且「自己报告的变量」预测力是「伴侣报告的变量」的二到四倍，加入个体差异和伴侣报告后，相对于只用自己报告的关系变量没有额外预测力","grade":"A","src":"Joel S, Eastwick PW, Allison CJ, et al. (2020). Machine learning uncovers the most robust self-report predictors of relationship quality across 43 longitudinal couples studies. Proceedings of the National Academy of Sciences, 117(32), 19061-19071. <https://doi.org/10.1073/pnas.1917036117>","note":"同一项研究还发现，关系质量的「变化」（在研究期间是变好还是变坏）用任何自陈变量组合都基本预测不出来。所以这条能用的部分是：判断当下这段关系好不好，问自己的感受比核对对方的条件清单准；但别指望能预测它以后会怎样。与本节「情绪价值别只问有没有」那条说的是同一件事，这条给出具体是哪几项","money":"0","time":"少","will":"些","level":"中","lens":"时间","dispute":false,"todo":false,"ratio":"一般"},{"id":"10.5","sec":10,"n":5,"title":"想拉近距离就轮流回答一组由浅入深的问题，别学话术","cost":"0 元；45 分钟","human":"把两个陌生人配对，轮流回答三组由浅入深、共 36 道问题，45 分钟后彼此的亲近感明显高于闲聊同样时长的对照组，甚至高过那批学生对自己现实中最亲密关系的平均打分。起作用的是两边轮流、一层层往深里说真话，不是话术。它测的只是短时间内的亲近感，不代表能发展成长期关系。","gain":"把互不相识的两人配对，让他们轮流回答三组逐步深入的问题（共 36 题，从「你最想请谁吃饭」到「上一次当着别人的面哭是什么时候」），45 分钟后的亲近感显著高于做同样时长闲聊的对照组，也高于该研究中大学生对自己现实中最亲密关系的平均评分","grade":"B","src":"Aron A, Melinat E, Aron EN, Vallone RD, Bator RJ (1997). The experimental generation of interpersonal closeness: a procedure and some preliminary findings. Personality and Social Psychology Bulletin, 23(4), 363-377. <https://doi.org/10.1177/0146167297234003>","note":"单次实验、样本是大学生，测的是短时间内的亲近感，不是能不能发展成长期关系。可用的部分是它的机制：亲近感来自逐步升级的双向自我披露，而不是话术、套路或单方面表现。所以聊天时的有效动作是「我说一点真实的，也问一句对等深度的」，并且两边轮流","money":"0","time":"少","will":"否","level":"小","lens":"时间","dispute":false,"todo":false,"ratio":"一般"},{"id":"10.6","sec":10,"n":6,"title":"异地不比同城差，真正的坎是搬到一起之后的头三个月","cost":"路费和时间；见面频率低","human":"异地在分开期间反而更稳，因为见得少、想象成分高；真正的坎在搬到一起之后。追踪数据里约一半异地伴侣走到了同城这一步，另一半在分开期间就结束了；而重聚的这一半里，三分之一在 3 个月内分手。分开时见面间隔越长、想得越美，重聚后越不稳。要准备的是重聚后那几个月：重聚后头三个月里有三分之一的人分手。","gain":"两项研究给出的图景一致：异地恋在分开期间反而比同城恋更稳定，因为异地关系里的理想化程度（理想化失真、浪漫爱、关系回忆、感知到的一致）明显更高，而理想化又与见面频率低相关；但这种稳定只在双方仍然分开时成立，一旦变成同城，异地伴侣更容易分手。追踪异地转同城的那项研究给出的比例是：约一半异地伴侣走到了搬到一起这一步，另一半在分开期间就结束了；而在重聚的这一半里，三分之一在重聚后 3 个月内分手。分开期间见面间隔越长、理想化越强，重聚后越不稳","grade":"B","src":"Stafford L, Merolla AJ, Castle JD (2006). When long-distance dating partners become geographically close. Journal of Social and Personal Relationships, 23(6), 901-919. <https://doi.org/10.1177/0265407506070472>；Stafford L, Merolla AJ (2007). Idealization, reunions, and stability in long-distance dating relationships. Journal of Social and Personal Relationships, 24(1), 37-54. <https://doi.org/10.1177/0265407507072578>","note":"样本是美国大学生的恋爱关系，不含婚姻，年代也较早，绝对比例别直接套。另一项 717 人异地、425 人同城的研究发现两类关系在关系质量上差别很小，预测关系质量的是个人和关系特征而不是距离本身（Dargie E, et al. (2015). Journal of Sex & Marital Therapy, 41(2), 181-202. <https://doi.org/10.1080/0092623X.2013.864367>）。可用的结论：要不要异地，别拿「异地一定散」当理由；要提前准备的是重聚后那几个月——自主空间变少、彼此了解变多、冲突和吃醋变多","money":"多","time":"多","will":"是","level":"中","lens":"时间","dispute":false,"todo":false,"ratio":"一般"},{"id":"10.7","sec":10,"n":7,"title":"先看登记数据再听长辈：结婚率、离婚率各是什么口径","cost":"0 元；读一遍民政部年度公报里的婚姻登记段落，几分钟","human":"2024 年全国办理结婚登记 610.6 万对，比上一年少了两成，办理离婚 351.3 万对。网上传的「离婚率过半」是拿这两个数一除（约 57.5%），分子分母根本不是同一批人，公报里没有这个指标，不能读成「一半婚姻会离」。公报里的结婚率 4.3‰、离婚率 2.5‰，分母是全体人口而不是已婚人口。","gain":"2024 年全国依法办理结婚登记 610.6 万对，比上年下降 20.5%，结婚率 4.3‰；依法办理离婚手续 351.3 万对（民政部门登记离婚 262.2 万对、法院判决和调解离婚 89.1 万对），离婚率 2.5‰；公报注明结（离）婚率 = 当年结（离）婚对数 / 当年平均总人口数 × 1000‰，是「粗率」，分母是全体人口而不是已婚人口","grade":"A","src":"民政部 (2025). 2024 年民政事业发展统计公报（五（二）1 婚姻登记服务、注释 5），网页版与 PDF 版. <https://www.mca.gov.cn/n1288/n1294/n1554/c1662004999980006190/content.html>、<https://www.mca.gov.cn/gdnps/n2445/n2451/n2458/n2681/c1662004999980006189/attr/400985.pdf>","note":"网上常见的「离婚率 50% 以上」是用当年离婚对数除以当年结婚对数（351.3 / 610.6 ≈ 57.5%），这是「离结比」，分子分母不是同一批人，公报里没有这个指标，不能读成「一半婚姻会离」；「一段婚姻最终离婚的概率」需要队列数据，本节未找到官方原文","money":"0","time":"少","will":"否","level":"小","lens":"时间","dispute":false,"todo":false,"ratio":"一般"},{"id":"10.8","sec":10,"n":8,"title":"把健康收益算进去，但按观察性数据打折","cost":"0 元；知道这些数字是「已婚者死亡率更低」的相关，不是「结婚会让你活得久」的因果","human":"已婚的人同期死亡的概率比非婚的人低约 12%，从未结过婚的人比已婚的人高约 24%，年纪越大差距越小，男性受的影响更明显些。但这是相关不是因果：本来健康、收入高、社交多的人既更容易结婚，也更容易活得久，研究做得越严谨算出的差距越小，而且数字基本来自欧美样本，对国内只能当量级参考。","gain":"老年人荟萃分析（53 组比较、25 万余人）已婚相对非婚全因死亡 RR 0.88（95% CI 0.85–0.91），丧偶 1.11、离异或分居 1.16、未婚 1.11，男女无差异，最保守估计 RR 0.94；未婚（从未结婚）相对已婚的荟萃分析（95 篇文献、5 亿余人）HR 1.24（1.19–1.30），效应随年龄增长而变小；按性别拆的荟萃分析（21 项研究、789 万余人）非婚与全因、癌症、心血管死亡在两性均相关，男性的心血管和全因死亡关联更强，未婚男性相对未婚女性卒中死亡多 31%、全因死亡多 9%","grade":"A","src":"Manzoli L, et al. (2007). Marital status and mortality in the elderly: a systematic review and meta-analysis. Soc Sci Med 64:77–94. <https://doi.org/10.1016/j.socscimed.2006.08.031>；Roelfs DJ, et al. (2011). The rising relative risk of mortality for singles: meta-analysis and meta-regression. Am J Epidemiol 174(4):379–389. <https://doi.org/10.1093/aje/kwr111>；Wang Y, et al. (2020). Sex differences in the association between marital status and the risk of cardiovascular, cancer, and all-cause mortality: a systematic review and meta-analysis of 7,881,040 individuals. Glob Health Res Policy 5:4. <https://doi.org/10.1186/s41256-020-00133-8>","note":"争议在于选择效应：健康、收入高、社交多的人本来就更容易结婚也更容易活得久，三项荟萃都是观察性研究，作者自己也写明存在发表偏倚或方法局限，Roelfs 还发现研究质量越高效应越小；这些数字来自欧美为主的样本，对国内人群只能当量级参考","money":"0","time":"少","will":"否","level":"小","lens":"死亡率","dispute":true,"todo":false,"ratio":"一般"},{"id":"10.9","sec":10,"n":9,"title":"时间账按「无酬劳动」算，谈清分工再领证","cost":"0 元；婚前花一两个小时把家务、照料、谁的工作让步这些无酬劳动谈成明确的分工，之后按分工执行","human":"全国时间利用调查里，家务和陪伴照料家人这类没报酬的活，男性每天平均 1 小时 52 分，女性 3 小时 29 分，差了一个半小时；参与率也差 16 个百分点。调查没按婚姻状况分组，所以「结了婚家务会多多少」没有官方数字，这个性别差距只能当上限参考。分工完全可以在领证前谈成另一个样子。","gain":"2024 年全国时间利用调查，无酬劳动（家务、陪伴照料家人等）参与者每日平均 2 小时 45 分，男性 1 小时 52 分、女性 3 小时 29 分，参与率男性 67.5%、女性 83.9%；居民家务劳动每日平均 1 小时 17 分（参与者 1 小时 59 分，比 2018 年少 28 分），陪伴照料家人 30 分（参与者 1 小时 46 分）；2018 年家务劳动男性 45 分、女性 2 小时 6 分，陪伴照料孩子男性 17 分、女性 53 分","grade":"A","src":"国家统计局 (2024). 第三次全国时间利用调查公报（第二号、第三号）. <https://www.stats.gov.cn/sj/zxfb/202410/t20241031_1957216.html>、<https://www.stats.gov.cn/sj/zxfb/202410/t20241031_1957215.html>；国家统计局 (2019). 2018 年全国时间利用调查公报. <https://www.stats.gov.cn/sj/zxfb/202302/t20230203_1900224.html>","note":"两次调查都只按性别、城乡、年龄分组，没有按婚姻状况分组，所以「结婚后家务会多多少」没有官方数字，只能用性别差距做上限参考；数字是全国平均，个体分工完全可以谈成另一个样子，这正是谈的价值","money":"0","time":"中","will":"些","level":"大","lens":"时间","dispute":false,"todo":false,"ratio":"高"},{"id":"10.10","sec":10,"n":10,"title":"钱账先看法律默认规则，再决定要不要书面约定","cost":"0 元起；读一遍民法典婚姻家庭编财产条文，有需要就双方签书面财产约定（法律只要求书面形式，公证不是必要条件）","human":"不签书面约定的话，法律默认婚后挣的工资奖金、经营和投资收益、知识产权收益、继承或受赠的财产都归两人共有；婚前财产、人身损害赔偿、遗嘱或赠与合同写明只给一方的、一方专用的生活用品才是个人的。双方可以书面约定各归各或部分共有，签了就有约束力，公证不是必要条件。因带孩子、照料老人多付出的一方，离婚时可以要求补偿。","gain":"默认规则是婚后所得的工资奖金劳务报酬、生产经营投资收益、知识产权收益、继承或受赠财产归夫妻共同所有（第一千零六十二条）；婚前财产、人身损害赔偿、遗嘱或赠与合同明确只归一方的财产、一方专用生活用品是个人财产（第一千零六十三条）；双方可以书面约定婚前和婚后财产归各自、共同或部分各自部分共同所有，约定对双方有法律约束力（第一千零六十五条）；因抚育子女、照料老人、协助另一方工作负担较多义务的一方，离婚时有权请求补偿（第一千零八十八条）","grade":"A","src":"全国人民代表大会 (2020). 中华人民共和国民法典（2021 年 1 月 1 日起施行，第一千零六十二、一千零六十三、一千零六十五、一千零八十八条）. 国家法律法规数据库 <https://flk.npc.gov.cn/detail?title=%E4%B8%AD%E5%8D%8E%E4%BA%BA%E6%B0%91%E5%85%B1%E5%92%8C%E5%9B%BD%E6%B0%91%E6%B3%95%E5%85%B8&id=ff808081729d1efe01729d50b5c500bf>；条文全文见最高人民法院公报转载 <http://gongbao.court.gov.cn/Details/7f184078694d811fb3314f6af9accf.html>","note":"彩礼、婚礼、婚房没有官方统计，本条不写数字；第一千零八十八条的补偿金额由双方协议、协议不成由法院判，没有法定公式；财产约定是双向的，对收入高的一方和承担无酬劳动多的一方都有用","money":"0","time":"中","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"10.11","sec":10,"n":11,"title":"父母出资买房，在转账的时候就把是借是送写清楚","cost":"0 元；出资当天写一页说明，写明这笔钱是赠与谁还是借给谁，由出资的父母和子女签字（写借款就让夫妻双方都签），转账备注同一句话","human":"婚前父母出钱买房，默认算给自己孩子一个人的；婚后出的钱没约定就按共同财产处理。2025 年 2 月起，婚内一方父母全额出资、赠与合同又没写明只给自己孩子的，离婚时法院可以把房判给出资方的孩子，再看共同生活和生育情况、有没有过错、谁对家庭贡献大、房子现在值多少，决定补不补偿另一方。要按借款办就当天写清楚、双方签字。","gain":"婚前父母为双方购房出资的，认定为对自己子女个人的赠与，父母明确表示赠与双方的除外；婚后出资的，有约定按约定，没有约定或者约定不明确的，按夫妻共同财产的原则处理。2025 年 2 月 1 日起，婚内由一方父母全额出资、赠与合同没写明只赠与自己子女的，离婚分割时法院可以判房屋归出资人子女一方所有，再综合共同生活和生育共同子女的情况、离婚过错、对家庭的贡献大小、离婚时房屋市场价格，确定要不要给另一方补偿、补多少；一方父母部分出资或者双方父母都出资的，以出资来源和比例为基础判归其中一方并合理补偿（全国）","grade":"A","src":"最高人民法院 (2020). 关于适用《民法典》婚姻家庭编的解释（一）（法释〔2020〕22 号，第二十九条）. <https://www.court.gov.cn/fabu/xiangqing/282071.html>；最高人民法院 (2025). 关于适用《民法典》婚姻家庭编的解释（二）（法释〔2025〕1 号，第八条）. <https://www.court.gov.cn/zixun/xiangqing/452771.html>；全国人大 (2020). 民法典（第一千零六十二条第一款第四项）. <https://www.spp.gov.cn/spp/fl/202006/t20200602_463888.shtml>","note":"这条对两边都有用。出钱的父母不必再指望离婚时补一张借条来保住出资——解释（二）施行后，出资来源本身就是分割依据，登记在谁名下不再决定归属；接受出资的一方也不用等到离婚才知道这笔钱算什么。要按借款办就真按借款办：借款合意、还款约定、转账备注、必要时的还款记录，缺一样都要在庭上解释","money":"0","time":"少","will":"否","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"极高"},{"id":"10.12","sec":10,"n":12,"title":"配偶一方大额借的钱，你没签字也没追认，不自动变成你的债","cost":"0 元；不在配偶的借条、担保书上签「共同借款人」「担保人」，也别在聊天里写「这钱我们会还」这类可能被当作事后追认的话","human":"配偶背着你借的钱，只要明显超出家里日常开销、你又没签字没追认，就不自动变成你的债，要债的人得自己证明这钱用在了共同生活或共同经营上。但买房这种钱如果确实变成了你们一起住或共有的房子，对方往往证得到这一层。离婚时对方父母突然掏出一张只有配偶签字的借条，先质证这笔借贷到底发生没发生：只有转账凭证的，主张借款的一方还得继续举证。","gain":"夫妻双方共同签名或者一方事后追认等共同意思表示所负的债务，以及一方在婚内以个人名义为家庭日常生活需要所负的债务，属于夫妻共同债务；一方以个人名义超出家庭日常生活需要所负的债务不属于夫妻共同债务，除非债权人能证明该债务用于夫妻共同生活、共同生产经营或者基于双方共同意思表示。买房的钱明显超出家庭日常生活需要，举证责任在主张债权的一方；但反过来说，这笔钱如果确实变成了夫妻共同居住或共有的房子，债权人往往能证到「用于夫妻共同生活」这一层，所以真正管用的是第 11 条（父母出资时写清是借是送）那一步（全国，2021 年起）","grade":"A","src":"全国人大 (2020). 民法典（第一千零六十四条）. <https://www.spp.gov.cn/spp/fl/202006/t20200602_463888.shtml>；最高人民法院 (2020 年第二次修正). 关于审理民间借贷案件适用法律若干问题的规定（第十五、十六条）. <http://gongbao.court.gov.cn/Details/94b6623974526df7d2430a3c73f050.html>（最高人民法院公报）","note":"离婚分财产时对方父母突然拿出一张只有配偶签字的借款协议，要分两层质证：先看借贷关系成不成立——抗辩借贷行为尚未实际发生并能作出合理说明的，法院应当结合借贷金额、款项交付、当事人经济能力、交易方式与习惯、财产变动情况、证人证言综合判断；只有转账凭证的，仍由主张借款的一方就借贷关系成立举证。成立之后再看是不是共同债务。借条和担保书的一般规则见第 8 节第 16 条","money":"0","time":"少","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"10.13","sec":10,"n":13,"title":"领证只要身份证加一份签字声明，不用户口簿，不收钱，当场发证","cost":"0 元；双方亲自到场，办完通常几十分钟","human":"2025 年 5 月起领证只要两样东西——本人身份证，加一份「本人无配偶、与对方没有直系血亲和三代以内旁系血亲关系」的签字声明，户口簿不用带，也不用回一方户口所在地办。登记本身一分钱不收，符合条件当场发证，通常几十分钟办完。遇到收「工本费」「加急费」的直接拒绝并投诉。","gain":"2025 年 5 月 10 日起施行的新婚姻登记条例，内地居民结婚只需出具两样东西：「（一）本人的居民身份证；（二）本人无配偶以及与对方当事人没有直系血亲和三代以内旁系血亲关系的签字声明」，户口簿不再是必需材料；登记机关是「县级人民政府民政部门或者省、自治区、直辖市人民政府按照便民原则确定的乡（镇）人民政府」，旧条例里「到一方当事人常住户口所在地」的限制已经取消；「婚姻登记机关办理婚姻登记，不得收取费用」；「对当事人符合结婚条件的，应当当场予以登记，发给结婚证」","grade":"A","src":"国务院 (2025). 婚姻登记条例（国令第 804 号，第二、六、八、十条）. <https://www.gov.cn/zhengce/zhengceku/202504/content_7017752.htm>","note":"不予登记的四种情形是：未到法定结婚年龄、非双方完全自愿、一方或双方已有配偶、属于直系血亲或三代以内旁系血亲。收费的只可能是照相、复印这类周边服务，登记本身一分钱不收，遇到「工本费」「加急费」直接拒绝并投诉。离婚登记的 30 天冷静期见本节退出成本那条","money":"0","time":"少","will":"否","level":"小","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"10.14","sec":10,"n":14,"title":"婚前做一次婚检，有重大疾病必须在登记前如实告诉对方","cost":"多数地区对适龄人群免费或减免，自费也是几百元；半天","human":"有重大疾病没在登记前如实告诉对方，对方可以去法院请求撤销这段婚姻，撤销要在知道之日起一年内提出。婚检本身自 2003 年起就不是领证的前置条件，去不去自愿，费用看本地政策、花半天。","gain":"隐瞒的法律后果是明确的：新婚姻登记条例规定「一方当事人患有重大疾病的，应当在结婚登记前如实告知另一方当事人；不如实告知的，另一方当事人可以依据民法典第一千零五十三条的规定向人民法院请求撤销婚姻」。国家把婚检当作出生缺陷防治的第一道关口，现行目标是「婚前医学检查率、孕前优生健康检查目标人群覆盖率分别保持在 70% 和 80% 以上」，并要求「推进婚前医学检查机构与婚姻登记场所就近设置方便群众」、推广「婚姻登记、婚前医学检查、生育指导『一站式』服务」；民法典规定一方患有重大疾病的应当在结婚登记前如实告知，不如实告知的另一方可以向人民法院请求撤销婚姻，请求撤销婚姻的应当自知道或者应当知道撤销事由之日起一年内提出","grade":"B","src":"全国人大 (2020). 民法典（第一千零五十三条）. <https://www.spp.gov.cn/spp/fl/202006/t20200602_463888.shtml>；国务院 (2025). 婚姻登记条例（国令第 804 号，第十二条）. <https://www.gov.cn/zhengce/zhengceku/202504/content_7017752.htm>；国家卫生健康委办公厅 (2023). 出生缺陷防治能力提升计划（2023—2027 年）（国卫办妇幼发〔2023〕9 号）. <https://www.gov.cn/zhengce/zhengceku/202308/content_6900320.htm>","note":"婚检自 2003 年起就不是登记的前置条件，去不去自愿，但「不如实告知重大疾病」的撤销权是真实存在的救济。撤销要在知道之日起一年内向法院提出。是否免费、查哪些项目由各地定，去当地妇幼保健机构或婚姻登记处一站式窗口问。TODO（待核实：全国层面婚检免费政策的统一文件依据与覆盖范围）","money":"少","time":"少","will":"否","level":"中","lens":"死亡率","dispute":false,"todo":true,"ratio":"一般"},{"id":"10.15","sec":10,"n":15,"title":"情绪价值别只问「有没有」，要看关系质量","cost":"0 元；婚前用几次冲突、几个月相处来观察关系质量，而不是只核对条件清单","human":"126 篇研究、7.2 万多人的汇总显示，婚姻质量越高健康越好，但这个关联很弱，量级跟饮食这类健康行为对健康的影响差不多，男女之间基本没发现差别。能用的部分是：关系好不好要拿几次冲突、几个月相处去看，不是核对条件清单。至于「坏婚姻是不是比不结婚更差」，没有直接对比的数据，目前只是推论。","gain":"126 篇研究、7.2 万余人的荟萃分析显示婚姻质量越高健康越好，效应量 r 在 0.07 到 0.21 之间，其中死亡风险 r = 0.11、冲突时心血管反应 r = −0.13，量级与饮食等健康行为对健康的影响相当；明确检验性别差异的研究里基本没发现男女不同；心血管领域综述指出婚姻不满意度和婚姻质量对心血管风险有显著影响","grade":"B","src":"Robles TF, et al. (2014). Marital quality and health: a meta-analytic review. Psychol Bull 140(1):140–187. <https://doi.org/10.1037/a0031859>；Dhindsa DS, et al. (2020). Marital status and outcomes in patients with cardiovascular disease. Trends Cardiovasc Med 30(4):215–220. <https://doi.org/10.1016/j.tcm.2019.05.012>","note":"争议在于效应量小、部分结局有发表偏倚、多为横断面设计不能推因果，Robles 原文自己列了这些局限；本节没有找到直接比较「低质量婚姻」与「未婚」死亡率的荟萃分析，「坏婚姻比不结婚差」这句话目前只能算推论，不能算数字结论","money":"0","time":"中","will":"些","level":"中","lens":"时间","dispute":true,"todo":false,"ratio":"一般"},{"id":"10.16","sec":10,"n":16,"title":"算退出成本：协议离婚有 30 天冷静期，诉讼离婚有法定条件","cost":"0 元；婚前把「万一要退出要花多久、走什么程序」读一遍","human":"协议离婚不是签完就完：交了申请后 30 天内任何一方都能撤回，期满还要在 30 天内两人亲自去领离婚证，不去就当撤回。对方不同意只能起诉，法院先调解，要有重婚或与他人同居、家暴虐待遗弃、赌博吸毒屡教不改、分居满两年这些情形，调解不成才判离；判了不离再分居满一年，第二次起诉应当准予。","gain":"协议离婚要签书面离婚协议并亲自到婚姻登记机关申请（第一千零七十六条）；自登记机关收到申请之日起 30 日内任何一方可撤回，期满后 30 日内双方须亲自申领离婚证，不申领视为撤回（第一千零七十七条）；一方不同意时走诉讼，法院应先调解，重婚或与他人同居、家庭暴力或虐待遗弃、赌博吸毒屡教不改、因感情不和分居满二年等情形调解无效应准予离婚，判不离后又分居满一年再诉应准予（第一千零七十九条）；2024 年全国离婚 351.3 万对里 89.1 万对走的是法院判决、调解","grade":"A","src":"全国人民代表大会 (2020). 中华人民共和国民法典（第一千零七十六、一千零七十七、一千零七十九条）. <http://gongbao.court.gov.cn/Details/7f184078694d811fb3314f6af9accf.html>；民政部 (2020). 关于贯彻落实《中华人民共和国民法典》中有关婚姻登记规定的通知（民发〔2020〕116 号）. <https://www.gov.cn/zhengce/zhengceku/2020-12/04/content_5567010.htm>；民政部 (2025). 2024 年民政事业发展统计公报. 同第 1 条","note":"冷静期只适用于协议离婚，诉讼离婚没有冷静期但周期更长；诉讼费、律师费各地不同，本条不写数字；退出成本高不是不结婚的理由，但应当在结婚前就知道","money":"0","time":"中","will":"些","level":"大","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"10.17","sec":10,"n":17,"title":"给「为长辈结婚」单独记一笔账，别和自己的账混在一起","cost":"0 元；在纸上分两栏写：这段婚姻里哪些收益是自己的（本节前面几条能算出来的），哪些是长辈的（安心、面子、催婚停止）","human":"长辈那份收益（安心、面子、不再催）是真的，但它不会自动变成你的健康收益或关系质量，而时间账、钱账和退出成本这三笔全部由你自己承担。在纸上分两栏，把哪些收益归自己、哪些归长辈写开，这笔账划不划算自己一眼就能看出来。","gain":"长辈的收益是真实的，但它不会自动转成健康收益（第 8 条）或关系质量（第 15 条），而时间账（第 9 条）、钱账（第 10 到 12 条）和退出成本（第 16 条）全部由当事人承担；分开记账以后，「做任务式结婚」的性价比是高是低一眼能看出来，不需要别人替你判断","grade":"C","src":"作者经验，方法类建议；数据部分见本节前面各条","note":"这一条不替读者下结论，长辈的账也可以算成很重的一笔；填空清单见 [docs/结婚划不划算.md](../docs/结婚划不划算.md)","money":"0","time":"少","will":"些","level":"中","lens":"时间","dispute":false,"todo":false,"ratio":"一般"}]},{"n":11,"title":"程序员和技术人容易踩的红线","intro":"本节口径是人身自由与金钱：写代码、做技术的人常把下面这些事当成「只是技术问题」，实际对应的是刑法里的具体罪名或民事上的具体赔偿，每条给出法条里的数字和最高检、最高法官网公布的案例。刑法引用北京市公安交管局转载的「根据刑法修正案（十一）修正」整合文本；排序按「技术人最容易以为没事 × 后果最重」从高到低，第 1 条是总则。","entries":[{"id":"11.1","sec":11,"n":1,"title":"动手前先问三句：损害了谁的利益、对方多有能力追究、我留了多少证据；被追究后马上找刑事律师","cost":"0 元；把「技术上能不能做」换成「厂商、平台、公司会不会报案」来想，服务器日志、支付记录、群聊记录默认都会被调取","human":"动手之前先想的不是「技术上能不能做」，而是「厂商、平台、公司会不会报案」——服务器日志、支付记录、群聊记录默认都会被调取。真被刑事拘留了，最长 37 天内决定捕不捕；从第一次讯问起就可以委托律师，律师提出会见，看守所最迟 48 小时内安排。这 37 天是找刑事律师最管用的窗口，等起诉后再找就晚了。","gain":"任何单位和个人发现犯罪事实都有权报案，机关认为有犯罪事实就应当立案；被刑事拘留后公安 3 日内提请批捕、特殊情况可延长 1 到 4 日、流窜作案等可延长至 30 日，检察院再用 7 日决定，也就是最长 37 天内决定捕不捕；从第一次讯问或被采取强制措施起就可以委托律师，侦查阶段只能委托律师，律师要求会见看守所最迟 48 小时内安排；可能判管制、拘役或独立适用附加刑等情形可以取保候审，取保最长 12 个月（全国）","grade":"C","src":"全国人大 (2018). 刑事诉讼法（2018 年修正，第三十四、三十九、六十七、七十九、九十一、一百一十、一百一十二条）. <https://www.spp.gov.cn/zdgz/201810/t20181027_396818.shtml>","note":"37 天是拘留到批捕决定的上限，不是关押上限，批捕后进入侦查羁押期限。「懂行的律师」起作用的窗口主要是这 37 天里的会见、向检察院提交不批捕意见和申请取保，等到起诉后再找就晚了；本节其余条目讲的都是「对方有没有报案的理由」。","money":"0","time":"少","will":"些","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"11.2","sec":11,"n":2,"title":"不做、不卖游戏外挂和辅助，包括「只读屏幕不碰内存」的 AI 辅助","cost":"0 元；放弃这类接单和「小工具」收入","human":"卖给 20 人次或者挣到 5000 元就够「情节严重」，判 3 年以下，特别严重 3 到 7 年，量很小。有人做读写游戏内存实现透视、自瞄的外挂，3 个月卖了 8 万多、自己挣 3 万多，判 1 年缓 1 年罚 5000 元；拿到服务端程序改参数开私服、收了 2000 多万充值的，判 4 年到 2 年 6 个月，罚金最高 1000 万元。","gain":"提供专门用于侵入、非法控制计算机信息系统的程序、工具，情节严重的判 3 年以下并处或单处罚金，情节特别严重 3 到 7 年并处罚金，情节严重的门槛是提供工具 20 人次以上或违法所得 5000 元以上；故意避开或破坏权利人技术措施还可构成侵犯著作权罪，判 3 年以下、严重 3 到 10 年；官方案例：王某等制售读取修改游戏内存实现透视、自瞄的外挂，3 个月卖 8 万余元、获利 3 万余元，判 1 年缓 1 年罚 5000 元；项某等卖「TZ」系列外挂销售额 20 余万元，项某判 3 年缓 3 年罚 2 万元；刘某某等拿到游戏服务端程序改参数开私服，收充值 2000 余万元，判 4 年到 2 年 6 个月、罚 1000 万到 130 万元（全国）","grade":"A","src":"全国人大 (2020). 刑法（根据刑法修正案（十一）修正，第二百八十五条第三款、第二百一十七条第六项）. <https://jtgl.beijing.gov.cn/jgj/jgxx/flfg/fl/11033925/index.html>；最高人民法院、最高人民检察院 (2011). 关于办理危害计算机信息系统安全刑事案件应用法律若干问题的解释（第三条）. <https://ga.sz.gov.cn/ZWGK/ZCFG/ZCJD/content/post_1304363.html>（深圳市公安局转载）；最高人民检察院 (2026). 上海静安：严惩制售游戏外挂黑灰产共护清朗网络空间. <https://www.spp.gov.cn/spp/zdgz/202608/t20260825_735480.shtml>；最高人民检察院 (2021). 2020 年度检察机关保护知识产权典型案例（案例五）. <https://www.spp.gov.cn/spp/xwfbh/wsfbt/202104/t20210425_516525.shtml>","note":"已公布的外挂判例都是读写内存、绕过反作弊的；「只截屏、只模拟按键」的辅助尚未见官方判例，但第 3 条抢票案说明不碰内存、只发请求也能定非法获取数据罪，最终怎么定性由办案机关按厂商报案的材料判断，不由作者自己认定。卖 20 人次就够「情节严重」，量很小。","money":"0","time":"少","will":"些","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"11.3","sec":11,"n":3,"title":"不写、不卖抢票、秒杀、刷单、薅羊毛脚本，哪怕只是「自动化点按钮」","cost":"0 元","human":"脚本不改内存、不破解，只是发请求比人快，一样按非法获取计算机信息系统数据定罪，门槛是挣到 5000 元或给对方造成 1 万元损失。有人批量导入外购的 12306 账号多线程抢票，代抢 200 多张、挣 2 万多，判 1 年 6 个月缓 1 年 6 个月罚 5000 元；在网店卖抢票软件的另被判不正当竞争赔 2 万元。","gain":"侵入计算机信息系统或用其他技术手段获取其中数据，情节严重的判 3 年以下并处或单处罚金，特别严重 3 到 7 年，情节严重的门槛是违法所得 5000 元以上或造成损失 1 万元以上；官方案例：某人用外挂批量导入外购 12306 账号、多线程密集提交购票请求代抢火车票 200 余张、获利 2 万余元，以非法获取计算机信息系统数据罪判 1 年 6 个月缓 1 年 6 个月罚 5000 元；郑某在网店卖针对某售票 App 的抢票软件，被判构成不正当竞争赔 2 万元（全国）","grade":"A","src":"全国人大 (2020). 刑法（根据刑法修正案（十一）修正，第二百八十五条第二款）. <https://jtgl.beijing.gov.cn/jgj/jgxx/flfg/fl/11033925/index.html>；最高人民法院、最高人民检察院 (2011). 关于办理危害计算机信息系统安全刑事案件应用法律若干问题的解释（第一条）. <https://ga.sz.gov.cn/ZWGK/ZCFG/ZCJD/content/post_1304363.html>；最高人民检察院 (2026). 上海静安：查办利用外挂软件批量代抢火车票牟利案. <https://www.spp.gov.cn/spp/dfjcdt/202607/t20260707_731426.shtml>；最高人民法院 (2025). 2024 年人民法院知识产权典型案例（案例七，抢票软件不正当竞争案）. <https://enipc.court.gov.cn/zh-cn/news/view-4205.html>","note":"抢票案里的脚本不改内存、不破解，只是「比人快」，仍然按 285 条定罪；收钱代抢和卖脚本都算牟利，自用一次的情形没有官方案例。","money":"0","time":"少","will":"否","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"极高"},{"id":"11.4","sec":11,"n":4,"title":"爬虫只爬无需登录的公开页面，不绕反爬、不碰个人信息，爬到的数据不卖","cost":"0 元；看 robots 和接口授权，需要登录、token、破解签名才能拿的数据不爬","human":"要登录、要 token、要破解签名才拿得到的数据属于绕过防护，判 3 年以下、严重的 3 到 7 年。爬到个人信息更麻烦：行踪、通信、征信、财产类 50 条，住宿、健康、交易类 500 条，其他类 5000 条，或挣到 5000 元，就算情节严重。有开发者把偷相册的功能伪装成「颜值检测」软件，拿到 1751 张人脸照片倒卖，判 3 年缓 3 年。","gain":"绕过防护获取系统数据同第 3 条（抢票秒杀刷单脚本）判 3 年以下或 3 到 7 年；非法获取、出售或提供公民个人信息，行踪轨迹、通信内容、征信、财产信息 50 条以上，住宿、通信记录、健康、交易信息 500 条以上，其他个人信息 5000 条以上，或违法所得 5000 元以上即「情节严重」，判 3 年以下并处或单处罚金，特别严重 3 到 7 年；官方案例：软件开发人员李某把窃取手机相册的功能伪装成「颜值检测」软件、拿到人脸照片 1751 张并倒卖社工库资料，判 3 年缓 3 年；某网络科技公司用爬虫拿外卖平台店铺、订单数据造成损失 4 万余元，被以非法获取计算机信息系统数据罪追诉（全国）","grade":"A","src":"全国人大 (2020). 刑法（根据刑法修正案（十一）修正，第二百八十五条第二款、第二百五十三条之一）. <https://jtgl.beijing.gov.cn/jgj/jgxx/flfg/fl/11033925/index.html>；最高人民法院、最高人民检察院 (2017). 关于办理侵犯公民个人信息刑事案件适用法律若干问题的解释（第三、四、五条）. <https://www.spp.gov.cn/xwfbh/wsfbt/201705/t20170509_190088.shtml>；最高人民检察院 (2022). 检察机关依法惩治侵犯公民个人信息犯罪典型案例（案例二）. <https://www.spp.gov.cn/spp/xwfbh/wsfbt/202212/t20221207_594915.shtml>；最高人民检察院 (2025). 检察机关依法惩治侵害企业数据安全犯罪 服务保障企业创新发展（案例一）. <https://www.spp.gov.cn/xwfbh/wsfbh/202501/t20250124_680670.shtml>","note":"2017 年解释把「未经同意把合法收集的信息提供给他人」也算提供，公司里把用户表导给外部合作方同样适用；5000 条是一个小表的量。","money":"0","time":"少","will":"些","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"11.5","sec":11,"n":5,"title":"不接赌博、诈骗、色情 App 的开发单，不替「客户」搭支付通道、解封账号","cost":"0 元；放弃这类报价高、需求含糊的外包","human":"这类报价高、需求含糊的单子，代价是按赌博团伙的共犯算，不是帮信罪那个 3 年上限。做赌博游戏「包网外销」的集团涉案近 70 亿元，负责外包研发的 79 人判了 6 个月到 9 年 9 个月；电竞竞猜 App 案里在海南写代码的 28 人以开设赌场罪判 3 年 6 个月到 1 年；替诈骗团伙解封 QQ 号的判 1 年 6 个月罚 2 万元。","gain":"明知他人利用网络犯罪仍提供技术支持、支付结算等帮助，情节严重的判 3 年以下并处或单处罚金，同时构成其他犯罪按重的定；开设赌场判 5 年以下并处罚金，情节严重 5 到 10 年；官方案例：张盛集团研发赌博游戏后「包网外销」收建站费、报表费，涉案近 70 亿元，张盛判 9 年 9 个月罚 5000 万元，负责外包研发的王强等 79 人判 6 个月到 9 年 9 个月不等；陈东等人开发运营电竞竞猜 App，技术团队在海南写代码，28 人以开设赌场罪判 3 年 6 个月到 1 年不等并处罚金；张某某开工作室替诈骗团伙解封被封的 QQ 号，判 1 年 6 个月罚 2 万元（全国）","grade":"A","src":"全国人大 (2020). 刑法（根据刑法修正案（十一）修正，第二百八十七条之二、第三百零三条第二款）. <https://jtgl.beijing.gov.cn/jgj/jgxx/flfg/fl/11033925/index.html>；最高人民检察院 (2023). 建赌博网站并出售，涉案近 70 亿元. <https://www.spp.gov.cn/spp/zdgz/202307/t20230711_621248.shtml>；最高人民检察院 (2022). 上海闵行区：办理一起新型开设网络赌场案. <https://www.spp.gov.cn/spp/zdgz/202208/t20220805_569952.shtml>；最高人民检察院 (2025). 依法惩治帮助信息网络犯罪活动及相关犯罪典型案例（案例一）. <https://www.spp.gov.cn/xwfbh/wsfbt/202507/t20250728_702377.shtml>","note":"「明知」不要求对方明说，报价明显高于市价、功能是充值提现加赔率、客户不肯说用途，在实务里都会拿来推定；开发赌博 App 的技术人员被按开设赌场罪共犯处理，不是帮信罪的 3 年上限。","money":"0","time":"少","will":"些","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"11.6","sec":11,"n":6,"title":"离职时交清账号权限，不删库、不留后门、不改密码锁系统，哪怕公司欠你钱","cost":"0 元；工资纠纷走劳动仲裁（见第 7 节）","human":"账号密码是公司给的，不等于离职后还能用，登进去就算非法控制，判 3 年以下；删数据让系统跑不起来的判 5 年以下，后果特别严重 5 年以上。有个被辞退的高级工程师用原管理员账号登录公司服务器改密码、删数据和日志，损失 12 万多元，判 3 年缓 5 年罚 3 万元。- 收益：非法控制计算机信息系统，情节严重的判 3 年以下并处或单处罚金，特别严重 3 到 7 年；删除、修改系统功能或数据造成不能正常运行、后果严重的判 5 年以下，特别严重 5 年以上；官方案例：IT 高级工程师吕某某被辞退后用原管理员账号登录公司共享服务器改密码、删数据和日志，损失 12 万余元，判 3 年缓 5 年罚 3 万元；软件公司员工白某某写升级程序时故意加错误代码致客户系统无法登录，损失 4 万余元，以破坏计算机信息系统罪追诉（全国）","gain":"","grade":"A","src":"全国人大 (2020). 刑法（根据刑法修正案（十一）修正，第二百八十五条第二款、第二百八十六条）. <https://jtgl.beijing.gov.cn/jgj/jgxx/flfg/fl/11033925/index.html>；最高人民检察院 (2024). 检察机关「依法惩治网络犯罪 助力网络空间综合治理」典型案例（案例六）. <https://www.spp.gov.cn/xwfbh/wsfbh/202402/t20240223_644505.shtml>；最高人民检察院 (2025). 检察机关依法惩治侵害企业数据安全犯罪 服务保障企业创新发展（案例七）. <https://www.spp.gov.cn/xwfbh/wsfbh/202501/t20250124_680670.shtml>","note":"账号密码是公司给的不等于离职后还能用，用原账号登录就算「非法控制」；损失按数据恢复费用算，几万元就够立案。","money":"0","time":"少","will":"些","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"11.7","sec":11,"n":7,"title":"离职不带走源码、客户名单和技术文档，不上传个人网盘，不在下家复用","cost":"0 元；离职前把个人电脑和网盘里的公司资料删干净","human":"自己写的代码著作权也归公司，带走就是拿公司的东西，客户名单同样算商业秘密。有离职员工带着安检系统源码和核心算法去新公司，本人判 5 年罚 50 万元、新公司罚 400 万元；有人利用系统漏洞下载 3.3 万多个设计文件，判 1 年 10 个月罚 10 万元。刑事之外，公司还可以另行提民事索赔。","gain":"违反保密义务披露、使用商业秘密，情节严重的判 3 年以下并处或单处罚金，特别严重 3 到 10 年并处罚金；反不正当竞争法把「电子侵入」获取商业秘密和教唆、帮助他人违反保密义务都列为侵权；官方案例：孙某明等离职员工带走安检系统源码和核心算法用于新公司产品，孙某明判 5 年罚 50 万元，新公司罚 400 万元；田某某利用系统漏洞下载 3.3 万余个设计文件，判 1 年 10 个月罚 10 万元；工程师杨某某把 App 模块源码存进个人电脑和云端、跳槽后做同类 App，以侵犯商业秘密罪追诉（全国）","grade":"A","src":"全国人大 (2020). 刑法（根据刑法修正案（十一）修正，第二百一十九条）. <https://jtgl.beijing.gov.cn/jgj/jgxx/flfg/fl/11033925/index.html>；全国人大常委会 (2025). 反不正当竞争法（2025 年修订，第十条）. <https://www.spp.gov.cn/spp/fl/202506/t20250627_699862.shtml>；最高人民检察院 (2025). 检察机关知识产权保护典型案例（案例七）. <https://www.spp.gov.cn/xwfbh/wsfbh/202504/t20250423_693691.shtml>；最高人民检察院 (2020). 2019 年度检察机关保护知识产权典型案例（案例十六）. <https://www.spp.gov.cn/xwfbh/wsfbh/202004/t20200425_459623.shtml>；最高人民检察院 (2025). 检察机关依法惩治侵害企业数据安全犯罪 服务保障企业创新发展（案例五）. <https://www.spp.gov.cn/xwfbh/wsfbh/202501/t20250124_680670.shtml>","note":"「自己写的代码」著作权也归公司（见第 13 条），带走就是拿公司的东西；客户名单属于经营信息，同样是商业秘密。刑事之外公司还会另起民事索赔。","money":"0","time":"少","will":"些","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"11.8","sec":11,"n":8,"title":"不在别人的电脑、服务器、摄像头上跑自己的程序，公司机器不拿来挖矿","cost":"0 元","human":"未经允许控制别人的电脑、服务器、摄像头，到 20 台就算情节严重，判 3 年以下，特别严重 3 到 7 年；够不上犯罪的也要拘留 5 日以下，还可能罚 5 万到 50 万元，情节较重拘留 5 到 15 日并罚 10 万到 100 万元。对技术人更重的是附带后果：受过治安处罚的 5 年内、受过刑事处罚的终身不能干网络安全管理和网络运营关键岗位。","gain":"对计算机信息系统实施非法控制，情节严重的判 3 年以下并处或单处罚金，特别严重 3 到 7 年，非法控制 20 台以上即「情节严重」；尚不构成犯罪的，公安没收违法所得、拘留 5 日以下并可罚 5 万到 50 万元，情节较重拘留 5 到 15 日并可罚 10 万到 100 万元，受过治安处罚 5 年内、受过刑事处罚终身不得从事网络安全管理和网络运营关键岗位；官方案例：李某买网络摄像头 IP 用软件控制 105 台摄像头窥探隐私，判 3 年缓 5 年罚 2 万元；吴某等把木马植入手机主板控制 330 余万部手机回传验证码，判 2 年到 4 年 6 个月（全国）","grade":"A","src":"全国人大 (2020). 刑法（根据刑法修正案（十一）修正，第二百八十五条第二款）. <https://jtgl.beijing.gov.cn/jgj/jgxx/flfg/fl/11033925/index.html>；最高人民法院、最高人民检察院 (2011). 关于办理危害计算机信息系统安全刑事案件应用法律若干问题的解释（第一条）. <https://ga.sz.gov.cn/ZWGK/ZCFG/ZCJD/content/post_1304363.html>；全国人大常委会 (2025). 网络安全法（2025 年修正，2026 年 1 月 1 日施行，第二十九、六十六条；2016 年文本为第二十七、六十三条，终身禁业为修正后的第六十六条第三款）. <https://www.cac.gov.cn/2025-12/29/c_1768735112911946.htm>；最高人民检察院 (2022). 山东滨州开发区：办理一起非法控制计算机信息系统案. <https://www.spp.gov.cn/spp/dfjcdt/202205/t20220518_557113.shtml>；最高人民检察院 (2021). 充分发挥检察职能 推进网络空间治理典型案例（案例六）. <https://www.spp.gov.cn/spp/xwfbh/wsfbh/202101/t20210125_507452.shtml>","note":"用公司服务器挖矿没有找到最高检、最高法公布的案例，条目按「未经授权控制他人系统」的法条写；「终身不得从事关键岗位」是网络安全法的附带后果，对技术人比罚款重。","money":"0","time":"少","will":"否","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"极高"},{"id":"11.9","sec":11,"n":9,"title":"没有书面授权不测别人的系统，「出于好意」和「事后上报」都不是出罪理由","cost":"0 元；放弃「顺手试一下」，参加厂商 SRC 或众测前先拿到授权范围、目标清单和时间窗口；验证到漏洞存在即停","human":"定不定罪看有没有授权、拿了多少，不看你想干什么。非金融类的身份认证信息拿到 500 组，或者违法所得 5000 元、给对方造成 1 万元损失，就够「情节严重」判 3 年以下，五倍以上是 3 到 7 年——为了证明一个注入漏洞顺手导一张用户表，往往一次就过了 500 这条线。有授权也不等于可以随便翻：最高检的指导性案例认定，超出授权范围用账号密码登录，这个行为本身就算侵入。够不上犯罪的那一档拘留、罚款和终身禁业同第 8 条（不在别人的机器上跑自己的程序）。","gain":"侵入国家事务、国防建设、尖端科学技术领域以外的计算机信息系统，或者采用其他技术手段，获取其中存储、处理、传输的数据，情节严重的判 3 年以下有期徒刑或拘役并处或单处罚金，特别严重的 3 到 7 年并处罚金；「情节严重」的标准是获取支付结算、证券交易、期货交易等网络金融服务的身份认证信息 10 组以上，获取其他身份认证信息 500 组以上，非法控制计算机信息系统 20 台以上，违法所得 5000 元以上或造成经济损失 1 万元以上，「情节特别严重」为上述标准的 5 倍以上；官方案例：检例第 36 号确立「超出授权范围使用账号、密码登录计算机信息系统，属于侵入计算机信息系统的行为」，该案三人用工作中掌握的账号、密码和令牌异地登录公司内部系统、下载非工作范围的数据在网上出售，违法所得 37000 元，分别判 4 年、3 年 9 个月、4 年，各罚 4 万元（全国）","grade":"A","src":"全国人大 (2020). 刑法（根据刑法修正案（十一）修正，第二百八十五条第一款、第二款）. <https://jtgl.beijing.gov.cn/jgj/jgxx/flfg/fl/11033925/index.html>；最高人民法院、最高人民检察院 (2011). 关于办理危害计算机信息系统安全刑事案件应用法律若干问题的解释（第一条）. <https://ga.sz.gov.cn/ZWGK/ZCFG/ZCJD/content/post_1304363.html>（深圳市公安局转载）；最高人民检察院 (2017). 第九批指导性案例（检例第 36 号，卫梦龙、龚旭、薛东东非法获取计算机信息系统数据案）. <https://www.spp.gov.cn/spp/jczdal/201710/t20171017_202593.shtml>","note":"检例第 36 号是卖数据牟利的案子，引它是为了「超出授权即侵入」这条要旨，不是说善意测试会判到同样的刑期。动机和事后上报在定罪上都不是出罪事由，只可能影响量刑和起不起诉；厂商先致谢、后报案在法律上并不矛盾，致谢不是授权。本节写作时未在最高法、最高检官网找到可逐字核对的善意测试类案例，故只按法条和处罚标准写。要做就走厂商公开的 SRC 或有书面委托的测评，把范围、目标和时间窗口写进文件；证明漏洞存在用最小证据，不批量取数据。发现漏洞之后怎么处理见下一条。","money":"0","time":"少","will":"些","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"11.10","sec":11,"n":10,"title":"漏洞按规定报送，修补前不公开细节、不发利用工具、不交给境外","cost":"0 元；报给产品提供者或官方平台，忍住不在修补前发细节和验证代码","human":"这份规定管的就是「从事网络产品安全漏洞发现、收集、发布等活动的组织或者个人」，个人也在里面。发布有五条硬线，核心是厂商给出修补措施之前不发漏洞信息、不发在用系统的漏洞细节、不发专门用来利用漏洞的程序和工具、发的时候要同步给出怎么修。还有一条容易被忽略：没公开的漏洞不能提供给产品提供者之外的境外组织和个人——往境外赏金平台提国内系统的洞正落在这条上。违规收集、发布由工信部和公安部依职责处理，够得上网络安全法那一档的，责令改正、警告并可罚 1 万到 10 万元，拒不改正或情节严重罚 10 万到 100 万元，还可能被停业整顿、关站、吊销执照，直接负责的人另罚 1 万到 10 万元。","gain":"规定适用于境内网络产品提供者、网络运营者以及从事漏洞发现、收集、发布等活动的组织或者个人；任何组织或者个人不得利用漏洞从事危害网络安全的活动，不得非法收集、出售、发布漏洞信息；向社会发布漏洞信息应当遵守五项：不得在产品提供者提供修补措施之前发布，不得发布网络运营者在用的网络、信息系统及其设备存在漏洞的细节情况，不得刻意夸大危害和风险、不得利用漏洞信息实施恶意炒作或者诈骗，不得发布或者提供专门用于利用漏洞从事危害网络安全活动的程序和工具，发布时应当同步发布修补或者防范措施；不得将未公开的漏洞信息向产品提供者之外的境外组织或者个人提供；鼓励向工业和信息化部网络安全威胁和漏洞信息共享平台、国家网络与信息安全信息通报中心漏洞平台、国家计算机网络应急技术处理协调中心漏洞平台、中国信息安全测评中心漏洞库报送；违反规定收集、发布漏洞信息的由工业和信息化部、公安部依据各自职责依法处理，构成网络安全法规定情形的依该法处罚——向社会发布系统漏洞等网络安全信息应当遵守国家有关规定，违反的由有关主管部门责令改正、给予警告，可以处 1 万元以上 10 万元以下罚款，拒不改正或者情节严重的处 10 万元以上 100 万元以下罚款，并可以责令暂停相关业务、停业整顿、关闭网站或者应用程序、吊销相关业务许可证或者吊销营业执照，对直接负责的主管人员和其他直接责任人员处 1 万元以上 10 万元以下罚款（全国）","grade":"A","src":"工业和信息化部、国家互联网信息办公室、公安部 (2021). 网络产品安全漏洞管理规定（工信部联网安〔2021〕66 号，第二、四、九、十、十四条，2021 年 9 月 1 日施行）. <https://www.gov.cn/gongbao/content/2021/content_5641351.htm>；全国人大常委会 (2025). 网络安全法（2025 年修正，2026 年 1 月 1 日施行，第二十八、六十五条；2016 年文本为第二十六、六十二条，规定第十四条援引的是 2016 年文本的条号）. <https://www.cac.gov.cn/2025-12/29/c_1768735112911946.htm>","note":"规定把个人明确列进适用范围，「我只是个业余爱好者」不在例外里。这条讲的是拿到漏洞之后怎么处置，先有没有资格去测见上一条——两件事分开：合法发现的漏洞也可能因为发布方式违规被罚，未经授权测出来的漏洞则是两头都占。报送渠道里工信部平台和国家互联网应急中心（CNCERT）是实务中最常用的两个。规定对发布的限制没有区分「已通知厂商但厂商不修」的情形，实践中的做法是把协商和报告过程留痕并同步报官方平台。","money":"0","time":"少","will":"否","level":"中","lens":"自由","dispute":false,"todo":false,"ratio":"高"},{"id":"11.11","sec":11,"n":11,"title":"不卖翻墙工具、VPN 账号，不替人搭这类节点","cost":"0 元","human":"自己建或者用国家公用信道以外的国际信道，公安可以责令停止联网、警告，并罚 1.5 万元以下、没收违法所得；靠这个做生意的，办案机关可以按非法经营罪办，情节严重判 5 年以下并罚违法所得的 1 到 5 倍，特别严重 5 年以上。这条讲的是卖和搭节点，个人自己用的处罚以警告加罚款为上限。各地处理差异大，官网上没找到公布的判例。","gain":"直接进行国际联网必须使用国家公用电信网提供的国际出入口信道，任何单位和个人不得自行建立或使用其他信道，违反的由公安责令停止联网、警告、可并处 1.5 万元以下罚款、没收违法所得；以此经营，办案机关可按非法经营罪处理，情节严重判 5 年以下并处或单处违法所得 1 到 5 倍罚金，特别严重 5 年以上（全国）","grade":"B","src":"国务院 (1997). 计算机信息网络国际联网管理暂行规定（第六、十四条）. <https://nyncw.cq.gov.cn/wsdw/zz/zhfb/wlyxxaq/202406/t20240619_13306645.html>（重庆市农业农村委员会转载）；全国人大 (2020). 刑法（根据刑法修正案（十一）修正，第二百二十五条第四项）. <https://jtgl.beijing.gov.cn/jgj/jgxx/flfg/fl/11033925/index.html>","note":"本节写作时未在最高法、最高检官网找到公布的翻墙类判例，各地处理差异大，故定 B 级；条目只讲「卖和搭」，个人使用的处罚以暂行规定第十四条的警告和罚款为上限。","money":"0","time":"少","will":"否","level":"大","lens":"自由","dispute":false,"todo":false,"ratio":"极高"},{"id":"11.12","sec":11,"n":12,"title":"签了竞业协议，离职后公司不按月给补偿就书面催告，满 3 个月没给可以解除；没接触过商业秘密的岗位可请求确认条款不生效","cost":"0 元；离职时留好协议原件和公司未付款的证据","human":"这条是保护自己的。竞业限制最长 2 年，公司必须按月给补偿；没约定数额的按你离职前 12 个月平均工资的 30% 算，且不低于当地最低工资。公司自己的原因 3 个月没给，可以请求解除。2025 年起，岗位上没接触过商业秘密的可以请求确认条款不生效——有家医药公司告首席技术官索赔 710 万元违约金，法院认定竞业范围只能限于他实际知道的秘密，全部驳回。","gain":"竞业限制只能约束高管、高级技术人员和其他负有保密义务的人，期限最长 2 年，公司必须在期限内按月给经济补偿；没约定补偿数额的按离职前 12 个月平均工资的 30% 且不低于当地最低工资；公司自身原因 3 个月未付，劳动者可请求解除；公司主动解除要额外付 3 个月补偿；2025 年起劳动者未知悉、接触商业秘密的可请求确认条款不生效，范围超出所知悉秘密的部分无效；官方案例：某医药公司起诉首席技术官郑某索赔违约金 710 万元，法院认定其新东家产品与原公司不具替代性、竞业范围应限于实际知悉的秘密，全部驳回（全国）","grade":"A","src":"全国人大常委会 (2012). 劳动合同法（2012 年修正，第二十三、二十四条）. <https://yjglj.fushun.gov.cn/008/20260622/d846d3c2-df3d-4c4c-af16-898ede43e1ee.html>（抚顺市应急管理局转载）；最高人民法院 (2020). 关于审理劳动争议案件适用法律问题的解释（一）（第三十六至四十条）. <https://www.court.gov.cn/zixun/xiangqing/282121.html>；最高人民法院 (2025). 关于审理劳动争议案件适用法律问题的解释（二）（法释〔2025〕12 号，第十三至十五条）. <https://www.court.gov.cn/zixun/xiangqing/472691.html>；最高人民法院 (2025). 劳动争议典型案例（案例四）. <https://www.court.gov.cn/zixun/xiangqing/472681.html>","note":"这是保护自己的条目。反过来，协议有效且公司按月付了钱，去竞品就要按约定付违约金，付完还可能被要求继续履行；在职期间的竞业约定不以支付补偿为前提。","money":"0","time":"少","will":"否","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"高"},{"id":"11.13","sec":11,"n":13,"title":"上班时间、用公司资源写的代码归公司，自己的开源项目用自己的时间和设备做，不混公司代码","cost":"0 元；入职时看清劳动合同里的知识产权条款","human":"软件被法律明确列在「著作权归单位」那一档：主要用了公司的设备、内网或业务数据又由公司担责，或者合同这么约定，代码著作权就是公司的，你只保留署名权；用公司资源做出的发明，专利也归公司。「下班写的」如果用了公司电脑或公司业务数据，同样可能被认定为主要利用了单位的物质技术条件。","gain":"为完成单位工作任务创作的作品是职务作品，一般情形著作权归作者、单位有权在业务范围内优先使用且 2 年内作者不得许可第三人以相同方式使用，但主要利用单位物质技术条件创作并由单位承担责任的工程设计、软件等作品，或合同约定归单位的，作者只保留署名权；执行本单位任务或主要利用本单位物质技术条件完成的发明创造是职务发明，专利申请权和专利权归单位（全国）","grade":"A","src":"全国人大常委会 (2020). 著作权法（2020 年修正，第十八条）. <http://www.npc.gov.cn/npc/c2/c30834/202011/t20201119_308796.html>；全国人大常委会 (2020). 专利法（2020 年修正，第六条）. <http://www.npc.gov.cn/npc/c2/c30834/202011/t20201119_308800.html>","note":"软件明确列在「著作权归单位」的那一款里，程序员几乎没有第一款的空间；「下班写的」如果用了公司电脑、内网或公司业务数据，同样可能被认定为主要利用单位物质技术条件。想把个人项目做干净，就用自己的机器、不碰公司仓库、不和公司业务重叠。","money":"0","time":"少","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"11.14","sec":11,"n":14,"title":"用 GPL 等开源代码做产品，按许可证要求开源或换许可证，不当「没人管」","cost":"0 元；引入依赖时看一眼许可证，GPL 系与闭源商用冲突就换","human":"侵犯著作权按权利人的实际损失或你的违法所得赔，算不清就参照许可费，故意且情节严重的能判到 1 到 5 倍。有个案子里被告招了原告的前员工开发网关软件，代码实质相似，被告抗辩说原告的软件本来基于 GPLv2、本就该开源，最高法认定这是两个独立问题，照样判停止侵害、赔 50 万元。","gain":"侵犯著作权按权利人实际损失或侵权人违法所得赔，难以计算的参照许可使用费，故意侵权情节严重可判 1 到 5 倍赔偿，损害公共利益的还可没收违法所得并处罚款；官方案例：（2021）最高法知民终 51 号，被告招聘原告前员工开发的网关软件与原告软件实质相似，被告以原告软件基于 GPLv2、本就该开源为由抗辩，最高法认定「开发者自身是否违反 GPLv2 协议和是否享有软件著作权是两个独立问题」，判停止侵害、赔偿 50 万元（全国）","grade":"B","src":"全国人大常委会 (2020). 著作权法（2020 年修正，第五十三、五十四条）. <http://www.npc.gov.cn/npc/c2/c30834/202011/t20201119_308796.html>；最高人民法院知识产权法庭 (2022). 涉「开源软件」著作权侵权案（（2021）最高法知民终 51 号）. <https://ipc.court.gov.cn/zh-cn/news/view-3042.html>","note":"这个案子说明「对方用了 GPL 代码」不是你抄它的挡箭牌；反过来，GPL 作者起诉不开源的商用方在国内已有生效判决，本节未在最高法官网找到原文故不引。等级 B 是因为许可证义务本身靠合同和著作权法一般条款，没有专门法条。","money":"0","time":"少","will":"些","level":"中","lens":"金钱","dispute":false,"todo":false,"ratio":"一般"},{"id":"11.15","sec":11,"n":15,"title":"做 App 只收业务必需的个人信息，14 岁以下要监护人同意，隐私政策写清楚","cost":"0 元；上线前把权限列表和隐私政策对一遍，能不要的权限不要","human":"只收业务真正必需的信息，不满 14 岁的要拿到监护人同意。违规先责令改正、警告、没收违法所得，App 可能被责令暂停或终止服务，拒不改正罚 100 万元以下，直接负责的人罚 1 万到 10 万元；情节严重的罚 5000 万元以下或上一年营业额的 5%，责任人罚 10 万到 100 万元。法条里的「直接责任人员」可能包括具体经办的技术和产品人员。","gain":"处理个人信息应当有明确合理目的、与目的直接相关、取对个人权益影响最小的方式，处理需取得个人同意或符合法定情形，不满 14 周岁的须取得父母或监护人同意；违反的由监管部门责令改正、警告、没收违法所得，对违法的 App 责令暂停或终止服务，拒不改正的罚 100 万元以下，对直接负责的主管人员和其他直接责任人员罚 1 万到 10 万元；情节严重的罚 5000 万元以下或上一年度营业额 5% 以下，责任人员罚 10 万到 100 万元并可被禁止一定期限内担任相关企业董事、监事、高管；出售或提供个人信息构成犯罪的见第 4 条（全国）","grade":"B","src":"全国人大常委会 (2021). 个人信息保护法（第六、十三、三十一、六十六条）. <http://www.npc.gov.cn/npc/c2/c30834/202108/t20210820_313088.html>","note":"「直接责任人员」在实务里常落到写代码和做产品的人头上；工信部定期通报下架违规 App，本节未核实具体通报文号故不引。","money":"0","time":"少","will":"些","level":"中","lens":"自由","dispute":false,"todo":false,"ratio":"一般"},{"id":"11.16","sec":11,"n":16,"title":"网站、App 上线前先做 ICP 备案，按等级保护要求留 6 个月以上日志","cost":"备案免费，走云厂商流程约几周；等保测评按级别收费，小站一般不需要测评","human":"备案不要钱，走云厂商流程大概几周；境内服务器不备案，域名根本解析不了。不备案的先责令改正，拒不改正就责令关站；主页不标备案号罚 5000 元到 5 万元；备案成非经营性却实际收费的按未经许可经营办，没收违法所得并罚 10 万到 100 万元。日志要留满 6 个月，不留的责令改正、警告，拒不改正或造成后果罚 1 万到 10 万元。","gain":"经营性互联网信息服务实行许可、非经营性实行备案，未取得许可或未备案不得从事；未备案的由电信管理机构责令改正，拒不改正的责令关闭网站，未经许可经营的没收违法所得并罚违法所得 3 到 5 倍或 10 万到 100 万元；网站主页不标备案号罚 5000 元到 5 万元；网络运营者须按等级保护制度制定安全管理制度、防范攻击、留存网络日志不少于 6 个月、对数据分类备份加密，不履行的责令改正、警告，拒不改正或造成后果的罚 1 万到 10 万元、主管人员罚 5000 元到 5 万元（全国）","grade":"A","src":"国务院 (2011). 互联网信息服务管理办法（2011 年修订，第四、十九、二十二条）. <https://www.gov.cn/gongbao/content/2011/content_1860864.htm>；全国人大常委会 (2025). 网络安全法（2025 年修正，2026 年 1 月 1 日施行，第二十三、六十一条；2016 年文本为第二十一、五十九条）. <https://www.cac.gov.cn/2025-12/29/c_1768735112911946.htm>","note":"境内服务器不备案域名根本解析不了，真正踩坑的是「备案成个人非经营性、实际在收费」和「换了域名或主体没变更备案」。日志留 6 个月既是义务也是自保，出事时能证明不是你干的。","money":"少","time":"中","will":"否","level":"中","lens":"自由","dispute":false,"todo":false,"ratio":"一般"},{"id":"11.17","sec":11,"n":17,"title":"对公众提供生成式 AI 服务前先按规定做安全评估和算法备案，生成内容加标识","cost":"0 元；走网信部门流程，个人小工具不对公众开放则不触发","human":"面向公众提供有舆论属性或社会动员能力的生成式 AI 服务，上线前要按国家规定做安全评估、办算法备案，改了或停了还要办变更、注销，生成的图片视频要加标识。自己用、不对公众开放的小工具不触发这一套。这个办法本身没写罚则，违反了按网络安全法、数据安全法、个人信息保护法处理。","gain":"提供具有舆论属性或社会动员能力的生成式人工智能服务，应当按国家规定开展安全评估，并按算法推荐管理规定履行算法备案和变更、注销手续；提供者应当对图片、视频等生成内容进行标识；办法自 2023 年 8 月 15 日施行（全国）","grade":"B","src":"国家互联网信息办公室等七部门 (2023). 生成式人工智能服务管理暂行办法（第十二、十七条）. <https://www.gov.cn/zhengce/zhengceku/202307/content_6891752.htm>","note":"办法对违反的处罚引用网络安全法、数据安全法、个人信息保护法处理，没有单独罚则，故定 B 级；用 AI 生成内容侵犯他人著作权、肖像的民事案例本节未在最高法官网核实原文，不引。","money":"0","time":"中","will":"否","level":"中","lens":"自由","dispute":false,"todo":false,"ratio":"一般"}]}]
